import { afterEach, describe, expect, mock, test } from "bun:test"

type LoggerContext = Record<string, unknown>

type ApiLogHandlerArgs = {
  logger: {
    set: (context: LoggerContext) => void
  }
  requestId: string
}

type ApiLogHandlerResult = {
  response: Response
  status: number
  outcome?: string
}

type RunWithApiRequestLogArgs = {
  request: Request
  path: string
  event: string
  handler: (args: ApiLogHandlerArgs) => Promise<ApiLogHandlerResult>
}

const originalFetch = globalThis.fetch

afterEach(() => {
  globalThis.fetch = originalFetch
})

const loadRouteModule = async (options?: {
  userId?: string | null
  storedToken?: string | null
  storedTokenThrows?: boolean
  upsertThrows?: boolean
  integrationToken?: string | null
  integration?: {
    id: string
    instanceUrl: string
    projectId: string
  } | null
}) => {
  const loggerContext: LoggerContext = {}
  const runWithApiRequestLog = mock(async ({ handler }: RunWithApiRequestLogArgs) => {
    const logger = {
      set: (context: LoggerContext) => {
        Object.assign(loggerContext, context)
      },
    }
    const result = await handler({ logger, requestId: "req_1" })
    return result.response
  })

  const getSessionUserId = mock(async () =>
    options?.userId === undefined ? "user-1" : options.userId,
  )

const getGitLabUserInstanceToken = mock(async () => {
  if (options?.storedTokenThrows) {
    throw new Error("lookup failed")
  }
  return options?.storedToken
    ? {
        token: options.storedToken,
        staleAt: null,
        staleReason: null,
      }
    : null
})

const upsertGitLabUserInstanceToken = mock(async () => {
  if (options?.upsertThrows) {
    throw new Error("upsert failed")
  }
})
const markGitLabUserInstanceTokenStale = mock(async () => {})
const getUserIntegration = mock(async () => {
  if (!options?.integration) {
    return null
  }
  return {
    ...options.integration,
    tokenCiphertext: "cipher",
    tokenIv: "iv",
    tokenAuthTag: "tag",
  }
})
const decryptIntegrationToken = mock(() => options?.integrationToken ?? "")

mock.module("@/lib/session", () => ({ getSessionUserId }))
mock.module("@/lib/utils/logger", () => ({ runWithApiRequestLog }))
mock.module("@/lib/gitlab/service", () => ({
  getUserIntegration,
  decryptIntegrationToken,
}))
mock.module("@/lib/gitlab/user-token", () => ({
  getGitLabUserInstanceToken,
  upsertGitLabUserInstanceToken,
  markGitLabUserInstanceTokenStale,
}))

const routeModule = await import(`./route?cacheBust=${Math.random().toString(36).slice(2)}`)

  return {
    POST: routeModule.POST as (request: Request) => Promise<Response>,
    loggerContext,
    getSessionUserId,
    getGitLabUserInstanceToken,
    upsertGitLabUserInstanceToken,
    markGitLabUserInstanceTokenStale,
    getUserIntegration,
    decryptIntegrationToken,
  }
}

describe("gitlab proxy route", () => {
  test("uses stored instance token when token is omitted", async () => {
    const fetchMock = mock(async (_url: string, init?: RequestInit) => {
      expect((init?.headers as Record<string, string>)["PRIVATE-TOKEN"]).toBe("stored-token")
      return new Response(JSON.stringify([{ id: 1, name: "proj", path: "proj" }]), {
        status: 200,
        headers: { "content-type": "application/json" },
      })
    })
    globalThis.fetch = fetchMock as unknown as typeof fetch

    const {
      POST,
      getGitLabUserInstanceToken,
      upsertGitLabUserInstanceToken,
    } = await loadRouteModule({ storedToken: "stored-token" })

    const response = await POST(
      new Request("http://localhost/api/gitlab", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({
          action: "projects",
          instanceUrl: "https://gitlab.global.lmco.com",
        }),
      }),
    )

    expect(response.status).toBe(200)
    expect(getGitLabUserInstanceToken).toHaveBeenCalledWith(
      "user-1",
      "https://gitlab.global.lmco.com",
    )
    expect(upsertGitLabUserInstanceToken).not.toHaveBeenCalled()
  })

