test("supports raw diffs larger than the previous browser-oriented cap", async () => {
  const patch =
    "diff --git a/src/a.ts b/src/a.ts\n--- a/src/a.ts\n+++ b/src/a.ts\n@@ -1 +1 @@\n-test\n+test"
  const fetchMock = mock(async (url: string, init?: RequestInit) => {
    expect((init?.headers as Record<string, string>)["PRIVATE-TOKEN"]).toBe("stored-token")
    expect(url).toContain("/raw_diffs")
    return new Response(patch, {
      status: 200,
      headers: {
        "content-type": "text/plain",
        "content-length": "3000000",
      },
    })
  })
  globalThis.fetch = fetchMock as unknown as typeof fetch

