type FeedbackPayload = {
  reviewId?: unknown
  feedback?: unknown
}

const normalizeReviewId = (value: unknown) => {
  if (typeof value !== "string") {
    return ""
  }
  return value.trim()
}

const normalizeFeedback = (value: unknown): "up" | "down" | null | undefined => {
  if (value === null) {
    return null
  }
  if (typeof value !== "string") {
    return undefined
  }
  const normalized = value.trim().toLowerCase()
  if (!normalized) {
    return null
  }
  if (normalized === "up" || normalized === "down") {
    return normalized
  }
  return undefined
}

export async function POST(request: Request) {
  return runWithApiRequestLog({
    request,
    path: "/api/review/feedback",
    event: "api.review.feedback",
    handler: async ({ logger }) => {
      const userId = await getSessionUserId()
      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      const payload = (await request.json().catch(() => null)) as FeedbackPayload | null
      const reviewId = normalizeReviewId(payload?.reviewId)
      const feedback = normalizeFeedback(payload?.feedback)

      if (!reviewId) {
        return {
          status: 400,
          outcome: "invalid_request",
          response: NextResponse.json({ error: "reviewId is required." }, { status: 400 }),
        }
      }
      if (feedback === undefined) {
        return {
          status: 400,
          outcome: "invalid_request",
          response: NextResponse.json(
            { error: "feedback must be one of: up, down, or null." },
            { status: 400 },
          ),
        }
      }

      const now = new Date()
      const rows = await db
        .update(aiReviewRuns)
        .set({
          feedback,
          feedbackSubmittedAt: feedback === null ? null : now,
        })
        .where(and(eq(aiReviewRuns.id, reviewId), eq(aiReviewRuns.userId, userId)))
        .returning({
          id: aiReviewRuns.id,
          feedback: aiReviewRuns.feedback,
          feedbackSubmittedAt: aiReviewRuns.feedbackSubmittedAt,
        })

      if (!rows[0]) {
        return {
          status: 404,
          outcome: "not_found",
          response: NextResponse.json({ error: "Review not found." }, { status: 404 }),
        }
      }

      logger.set({
        reviewId,
        feedback,
      })

      return {
        status: 200,
        outcome: "success",
        response: NextResponse.json({
          data: {
            review: {
              id: rows[0].id,
              feedback: rows[0].feedback,
              feedbackSubmittedAt: rows[0].feedbackSubmittedAt?.toISOString() ?? null,
            },
          },
        }),
      }
    },
  })
}

