import path from "node:path"
import { promisify } from "node:util"

import { z } from "zod"

const execFileAsync = promisify(execFile)

const indexPackStatsSchema = z
  .object({
    filesParsed: z.number().int().nonnegative().optional(),
    chunksEmitted: z.number().int().nonnegative().optional(),
    nodesEmitted: z.number().int().nonnegative().optional(),
    edgesEmitted: z.number().int().nonnegative().optional(),
  })
  .optional()

const indexPackManifestSchema = z.object({
  schemaVersion: z.string().min(1),
  indexRunId: z.string().min(1),
  generatedAt: z.string().min(1),
  stats: indexPackStatsSchema,
})

type CodeGraphErrorCode =
  | "binary_missing"
  | "command_failed"
  | "invalid_output"
  | "missing_index_pack"

export class CodeGraphError extends Error {
  readonly code: CodeGraphErrorCode
  readonly details: Record<string, unknown> | null

  constructor(code: CodeGraphErrorCode, message: string, details: Record<string, unknown> | null = null) {
    super(message)
    this.code = code
    this.details = details
  }
}

export type CodeGraphSummary = {
  indexRunId: string
  generatedAt: string
  schemaVersion: string
  stats: {
    filesParsed: number
    chunksEmitted: number
    nodesEmitted: number
    edgesEmitted: number
  }
}

const resolveConfigPath = () => path.join(process.cwd(), "code-intelligence.json")
const resolveIndexPackDir = () => path.join(process.cwd(), ".argus-search", "index-pack")

const resolveManifestPath = () => path.join(resolveIndexPackDir(), "manifest.json")

const asRecord = (value: unknown): Record<string, unknown> | null => {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return null
  }

  return value as Record<string, unknown>
}

const normalizeStderr = (stderr: string | undefined) => {
  const trimmed = stderr?.trim()
  if (!trimmed) {
    return null
  }

  return trimmed.slice(0, 1_500)
}

const parseManifest = (raw: string): CodeGraphSummary => {
  let parsed: unknown
  try {
    parsed = JSON.parse(raw)
  } catch {
    throw new CodeGraphError("invalid_output", "Failed to parse graph index-pack manifest JSON.", null)
  }

  const validated = indexPackManifestSchema.safeParse(parsed)
  if (!validated.success) {
    throw new CodeGraphError("invalid_output", "Graph index-pack manifest did not match expected schema.", {
      issues: validated.error.issues.map((issue) => issue.message),
    })
  }

  const stats = validated.data.stats
  return {
    indexRunId: validated.data.indexRunId,
    generatedAt: validated.data.generatedAt,
    schemaVersion: validated.data.schemaVersion,
    stats: {
      filesParsed: stats?.filesParsed ?? 0,
      chunksEmitted: stats?.chunksEmitted ?? 0,
      nodesEmitted: stats?.nodesEmitted ?? 0,
      edgesEmitted: stats?.edgesEmitted ?? 0,
    },
  }
}

export const getCodeGraphSummary = async (): Promise<CodeGraphSummary | null> => {
  try {
    const raw = await readFile(resolveManifestPath(), "utf8")
    return parseManifest(raw)
  } catch (error) {
    if (
      typeof error === "object" &&
      error !== null &&
      "code" in error &&
      (error as { code?: string }).code === "ENOENT"
    ) {
      return null
    }

    if (error instanceof CodeGraphError) {
      throw error
    }

    throw new CodeGraphError("invalid_output", "Failed to read graph index-pack manifest.", {
      message: error instanceof Error ? error.message : "Unknown error.",
    })
  }
}

export const refreshCodeGraphSummary = async (): Promise<CodeGraphSummary> => {
  const configPath = resolveConfigPath()
  const configRaw = await readFile(configPath, "utf8").catch((error) => {
    throw new CodeGraphError("command_failed", "Failed to read code-intelligence config.", {
      configPath,
      message: error instanceof Error ? error.message : "Unknown error.",
    })
  })

  let parsedConfig: unknown
  try {
    parsedConfig = JSON.parse(configRaw)
  } catch {
    throw new CodeGraphError("invalid_output", "Failed to parse code-intelligence config JSON.", {
      configPath,
    })
  }

  const baseConfig = asRecord(parsedConfig)
  if (!baseConfig) {
    throw new CodeGraphError("invalid_output", "Code-intelligence config must be a JSON object.", {
      configPath,
    })
  }

  const phases = asRecord(baseConfig.phases)
  const cache = asRecord(baseConfig.cache)
  const output = asRecord(baseConfig.output)

const fullGraphConfig = {
  ...baseConfig,
  phases: {
    ...phases,
    parse: true,
    graph: true,
    vector: false,
    indexPack: true,
  },
  cache: {
    ...cache,
    enabled: false,
    force: true,
  },
  output: {
    ...output,
    incremental: false,
  },
}

const tempDir = await mkdtemp(path.join(os.tmpdir(), "argus-code-graph-")).catch((error) => {
  throw new CodeGraphError("command_failed", "Failed to prepare temporary graph config directory.", {
    message: error instanceof Error ? error.message : "Unknown error.",
  })
})
const tempConfigPath = path.join(tempDir, "code-intelligence.graph.json")
try {
  await writeFile(tempConfigPath, JSON.stringify(fullGraphConfig, null, 2), "utf8")
} catch (error) {
  await rm(tempDir, { recursive: true, force: true }).catch(() => {})
  throw new CodeGraphError("command_failed", "Failed to write temporary graph config.", {
    tempConfigPath,
    message: error instanceof Error ? error.message : "Unknown error.",
  })
}

  try {
    await execFileAsync(
      "ci",
      [
        "watch",
        "--config",
        tempConfigPath,
        "--project-root",
        process.cwd(),
        "--once",
        "--no-vector",
        "--phases",
        "parse,graph,indexPack",
        "--json",
      ],
      {
        cwd: process.cwd(),
        timeout: 120_000,
        maxBuffer: 4 * 1024 * 1024,
      },
    )
  } catch (error) {
    if (
      typeof error === "object" &&
      error !== null &&
      "code" in error &&
      (error as { code?: string }).code === "ENOENT"
    ) {
      throw new CodeGraphError("binary_missing", "The `ci` binary is not available on PATH.", null)
    }

    const commandError = error as { stderr?: string; message?: string }
    throw new CodeGraphError("command_failed", "Failed to refresh code graph index-pack.", {
      message: commandError.message ?? "Unknown command failure.",
      stderr: normalizeStderr(commandError.stderr),
    })
  } finally {
    await rm(tempDir, { recursive: true, force: true }).catch(() => {})
  }

  const summary = await getCodeGraphSummary()
  if (!summary) {
    throw new CodeGraphError(
      "missing_index_pack",
      "Code graph index-pack was not created at expected path.",
      {
        indexPackDir: resolveIndexPackDir(),
      },
    )
  }

  return summary
}

