/* Argus Logo Interactive Eye Animations */
@keyframes argus-breathe {
  0%,
  100% {
    transform: scale(1);
  }
  50% {
    transform: scale(1.02);
  }
}

@keyframes argus-flow {
  to {
    stroke-dashoffset: -200;
  }
}

@keyframes argus-float {
  0%,
  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-15px);
  }
}

@keyframes argus-float-center {
  0%,
  100% {
    transform: translateX(-50%) translateY(0);
  }
  50% {
    transform: translateX(-50%) translateY(-15px);
  }
}

.argus-eye-container {
  animation: argus-breathe 6s ease-in-out infinite;
}

.argus-flow-line {
  fill: none;
  stroke-width: 2;
  stroke-dasharray: 10 10;
  opacity: 0.6;
  animation: argus-flow 20s linear infinite;
  filter: drop-shadow(0px 0px 5px oklch(0.78 0.07 85));
}

.argus-floating-label {
  position: absolute;
  z-index: 3;
  color: oklch(0.78 0.07 85);
  background: oklch(0.145 0.028 264 / 80%);
  border: 1px solid oklch(0.78 0.07 85);
  padding: 10px 20px;
  border-radius: 20px;
  font-size: 0.9rem;
  font-weight: bold;
  text-transform: uppercase;
  letter-spacing: 1px;
  box-shadow:
    0 0 15px oklch(0.78 0.07 85 / 20%),
    inset 0 0 10px oklch(0.78 0.07 85 / 10%);
  backdrop-filter: blur(5px);
  pointer-events: auto;
  cursor: default;
  user-select: none;
  white-space: nowrap;
  transition: all 0.3s ease;
}

.argus-floating-label:hover {
  background: oklch(0.78 0.07 85 / 12%);
  box-shadow: 0 0 25px oklch(0.78 0.07 85 / 40%);
  transform: scale(1.05);
}

.argus-label-diffs {
  top: 10%;
  left: 5%;
  animation: argus-float 4s ease-in-out infinite;
  animation-delay: 0s;
}

.argus-label-impact {
  top: 10%;
  right: 5%;
  animation: argus-float 4s ease-in-out infinite;
  animation-delay: 1.5s;
}

.argus-label-obs {
  bottom: 5%;
  left: 50%;
  animation: argus-float-center 4s ease-in-out infinite;
  animation-delay: 0.7s;
}

@media (max-width: 768px) {
  .argus-floating-label {
    font-size: 0.7rem;
    padding: 6px 12px;
  }
}

