export type SiteHeaderBreadcrumb = {
  label: string
  href: string | null
}

const SEGMENT_LABELS: Record<string, string> = {
  "code-graph": "Code Graph",
  integrations: "Integrations",
  indexing: "Indexing",
  mrs: "Merge Requests",
  observability: "Observability",
  onboarding: "Onboarding",
  projects: "Projects",
  repos: "Repositories",
  settings: "Settings",
  tokens: "Tokens",
  description: "Description",
}

const decodeSegment = (segment: string) => {
  try {
    return decodeURIComponent(segment)
  } catch {
    return segment
  }
}

const toTitleCase = (value: string) =>
  value
    .split(/\s+/)
    .filter(Boolean)
    .map((word) => (
      word.length <= 2
        ? word.toUpperCase()
        : `${word[0]?.toUpperCase() ?? ""}${word.slice(1)}`
    ))
    .join(" ")

const humanize = (value: string) => {
  const normalized = value
    .replace(/[_-]+/g, " ")
    .replace(/\s+/g, " ")
    .trim()

  return normalized ? toTitleCase(normalized) : value
}

const formatRepoRouteId = (value: string) => {
  const parts = value.split("--")
  if (parts.length < 3) {
    return humanize(value)
  }

  const projectToken = parts[1]?.trim()
  if (!projectToken) {
    return humanize(value)
  }

  return humanize(projectToken)
}

const segmentLabel = (segments: string[], index: number) => {
  const current = decodeSegment(segments[index] ?? "")
  const previous = decodeSegment(segments[index - 1] ?? "")

  if (previous === "repos") {
    return formatRepoRouteId(current)
  }

  if (previous === "mrs") {
    return `!${current}`
  }

  return SEGMENT_LABELS[current] ?? humanize(current)
}

export const buildSiteHeaderBreadcrumbs = (pathname: string): SiteHeaderBreadcrumb[] => {
  const rawSegments = pathname.split("/").filter(Boolean)
  const segments = rawSegments.filter((segment, index) => {
    const current = decodeSegment(segment)
    const twoBack = decodeSegment(rawSegments[index - 2] ?? "")

    if (current === "description" && twoBack === "mrs") {
      return false
    }

    return true
  })

  if (segments.length === 0) {
    return [{ label: "Home", href: null }]
  }

  return segments.map((_, index) => {
    const isLast = index === segments.length - 1
    const href = isLast ? null : `/${segments.slice(0, index + 1).join("/")}`

    return {
      label: segmentLabel(segments, index),
      href,
    }
  })
}

export const resolveSiteHeaderTitle = (
  explicitTitle: string | null,
) => (explicitTitle?.trim() ? explicitTitle : null)

import { Fragment, type ReactNode } from "react"

import { cn } from "@/lib/utils"

type HeadingBlock = {
  type: "heading"
  level: 1 | 2 | 3 | 4 | 5 | 6
  text: string
}

type ParagraphBlock = {
  type: "paragraph"
  text: string
}

type ListItem = {
  text: string
  checked: boolean | null
}

type ListBlock = {
  type: "list"
  ordered: boolean
  items: ListItem[]
}

type BlockquoteBlock = {
  type: "blockquote"
  text: string
}

type CodeBlock = {
  type: "code"
  language: string
  text: string
}

type RuleBlock = {
  type: "rule"
}

type MarkdownBlock =
  | HeadingBlock
  | ParagraphBlock
  | ListBlock
  | BlockquoteBlock
  | CodeBlock
  | RuleBlock

const headingClassName: Record<HeadingBlock["level"], string> = {
  1: "text-2xl font-semibold tracking-tight",
  2: "text-xl font-semibold tracking-tight",
  3: "text-lg font-semibold",
  4: "text-base font-semibold",
  5: "text-sm font-semibold",
  6: "text-sm font-semibold text-muted-foreground",
}

const isHeading = (line: string) => /^#{1,6}\s+/.test(line)
const isRule = (line: string) => /^(-{3,}|\*{3,}|_{3,})$/.test(line.trim())
const isCodeFence = (line: string) => /^```/.test(line.trim())
const isBlockquote = (line: string) => /^>\s?/.test(line)
const isUnorderedList = (line: string) => /^\s*[-*+]\s+/.test(line)
const isOrderedList = (line: string) => /^\s*\d+\.\s+/.test(line)

const isBlockStart = (line: string) => {
  if (!line.trim()) return false
  return (
    isHeading(line) ||
    isRule(line) ||
    isCodeFence(line) ||
    isBlockquote(line) ||
    isUnorderedList(line) ||
    isOrderedList(line)
  )
}

const parseBlocks = (markdown: string): MarkdownBlock[] => {
  const lines = markdown.replace(/\r\n?/g, "\n").split("\n")
  const blocks: MarkdownBlock[] = []

  let index = 0
  while (index < lines.length) {
    const line = lines[index] ?? ""
    const trimmedLine = line.trim()

    if (!trimmedLine) {
      index += 1
      continue
    }

    if (isCodeFence(trimmedLine)) {
      const language = trimmedLine.replace(/^```/, "").trim()
      const codeLines: string[] = []
      index += 1
      while (index < lines.length && !isCodeFence((lines[index] ?? "").trim())) {
        codeLines.push(lines[index] ?? "")
        index += 1
      }
      if (index < lines.length) {
        index += 1
      }
      blocks.push({
        type: "code",
        language,
        text: codeLines.join("\n").trimEnd(),
      })
      continue
    }

    const headingMatch = trimmedLine.match(/^(#{1,6})\s+(.*)$/)
    if (headingMatch) {
      blocks.push({
        type: "heading",
        level: headingMatch[1].length as HeadingBlock["level"],
        text: headingMatch[2].trim(),
      })
      index += 1
      continue
    }

    if (isRule(trimmedLine)) {
      blocks.push({ type: "rule" })
      index += 1
      continue
    }

    if (isBlockquote(line)) {
      const quoteLines: string[] = []
      while (index < lines.length && isBlockquote(lines[index] ?? "")) {
        quoteLines.push((lines[index] ?? "").replace(/^>\s?/, ""))
        index += 1
      }
      blocks.push({
        type: "blockquote",
        text: quoteLines.join("\n").trim(),
      })
      continue
    }

  if (isUnorderedList(line) || isOrderedList(line)) {
    const ordered = isOrderedList(line)
    const items: ListItem[] = []
    while (index < lines.length) {
      const nextLine = lines[index] ?? ""
      if (ordered ? !isOrderedList(nextLine) : !isUnorderedList(nextLine)) {
        break
      }
      const content = nextLine.replace(ordered ? /^\s*\d+\.\s+/ : /^\s*[-*+]\s+/, "")
      const checkboxMatch = content.match(/^\[( |x|X)\]\s+(.*)$/)
      if (checkboxMatch) {
        items.push({
          text: checkboxMatch[2].trim(),
          checked: checkboxMatch[1].toLowerCase() === "x",
        })
      } else {
        items.push({
          text: content.trim(),
          checked: null,
        })
      }
      index += 1
    }
    blocks.push({
      type: "list",
      ordered,
      items,
    })
    continue
  }

  const paragraphLines: string[] = []
  while (index < lines.length) {
    const nextLine = lines[index] ?? ""
    if (!nextLine.trim()) {
      break
    }
    if (isBlockStart(nextLine)) {
      break
    }
    paragraphLines.push(nextLine.trim())
    index += 1
  }

  if (paragraphLines.length > 0) {
    blocks.push({
      type: "paragraph",
      text: paragraphLines.join(" "),
    })
    continue
  }

  blocks.push({
    type: "paragraph",
    text: trimmedLine,
  })
  index += 1
}

return blocks

}

const renderInlineMarkdown = (text: string): ReactNode[] => {
  const nodes: ReactNode[] = []
  const pattern = /\[([^\]]+)\]\(([^)]+)\)|`([^`]+)`|\*\*([^*]+)\*\*/g
  let lastIndex = 0
  let match = pattern.exec(text)

  while (match) {
    if (match.index > lastIndex) {
      nodes.push(text.slice(lastIndex, match.index))
    }

    if (match[1] && match[2]) {
      nodes.push(
        <a
          key={`link-${match.index}`}
          href={match[2]}
          target="_blank"
          rel="noreferrer"
          className="font-medium text-primary underline decoration-primary/60 underline-offset-4"
        >
          {match[1]}
        </a>,
      )
    } else if (match[3]) {
      nodes.push(
        <code
          key={`code-${match.index}`}
          className="rounded bg-muted px-1.5 py-0.5 font-mono text-[0.85em]"
        >
          {match[3]}
        </code>,
      )
    } else if (match[4]) {
      nodes.push(
        <strong key={`strong-${match.index}`} className="font-semibold">
          {match[4]}
        </strong>,
      )
    }

    lastIndex = pattern.lastIndex
    match = pattern.exec(text)
  }

  if (lastIndex < text.length) {
    nodes.push(text.slice(lastIndex))
  }

  if (nodes.length === 0) {
    nodes.push(text)
  }

  return nodes
}

type MergeRequestMarkdownRendererProps = {
  markdown: string
  className?: string
}

export function MergeRequestMarkdownRenderer({
  markdown,
  className,
}: MergeRequestMarkdownRendererProps) {
  const blocks = parseBlocks(markdown)

  if (blocks.length === 0) {
    return null
  }

return (
  <div className={cn("space-y-3 text-sm leading-6 text-foreground", className)}>
    {blocks.map((block, index) => {
      if (block.type === "heading") {
        const Tag = `h${block.level}` as const
        return (
          <Tag key={`h-${index}`} className={headingClassName[block.level]}>
            {renderInlineMarkdown(block.text).map((node, nodeIndex) => (
              <Fragment key={`heading-${index}-${nodeIndex}`}>{node}</Fragment>
            ))}
          </Tag>
        )
      }

      if (block.type === "paragraph") {
        return (
          <p key={`p-${index}`} className="text-sm leading-6 text-foreground/95">
            {renderInlineMarkdown(block.text).map((node, nodeIndex) => (
              <Fragment key={`paragraph-${index}-${nodeIndex}`}>{node}</Fragment>
            ))}
          </p>
        )
      }

      if (block.type === "blockquote") {
        return (
          <blockquote
            key={`quote-${index}`}
            className="border-l-2 border-border pl-4 text-sm text-muted-foreground"
          >
            {renderInlineMarkdown(block.text).map((node, nodeIndex) => (
              <Fragment key={`quote-${index}-${nodeIndex}`}>{node}</Fragment>
            ))}
          </blockquote>
        )
      }

if (block.type === "list") {
  const ListTag = block.ordered ? "ol" : "ul"
  return (
    <ListTag
      key={`list-${index}`}
      className={cn(
        "space-y-1 pl-6",
        block.ordered ? "list-decimal" : "list-disc",
      )}
    >
      {block.items.map((item, itemIndex) => (
        <li key={`list-${index}-${itemIndex}`} className="text-sm leading-6">
          {item.checked === null ? null : (
            <span className="mr-2 inline-flex items-center font-mono text-xs text-muted-foreground">
              [{item.checked ? "x" : " "}]
            </span>
          )}
          {renderInlineMarkdown(item.text).map((node, nodeIndex) => (
            <Fragment key={`list-inline-${index}-${itemIndex}-${nodeIndex}`}>{node}</Fragment>
          ))}
        </li>
      ))}
    </ListTag>
  )
}

if (block.type === "code") {
  return (
    <div key={`code-${index}`} className="rounded-md border bg-muted/35">
      {block.language ? (
        <div className="border-b px-3 py-1.5 font-mono text-[11px] uppercase tracking-wide text-muted-foreground">
          {block.language}
        </div>
      ) : null}
      <pre className="overflow-x-auto p-3 text-xs leading-6">
        <code>{block.text}</code>
      </pre>
    </div>
  )
}

        return <hr key={`rule-${index}`} className="border-border/70" />
      })}
    </div>
  )
}

