import { eq } from 'drizzle-orm'

import { db } from '@/lib/db'
import {
  indexFileStates,
  indexRunFileChanges,
} from '@/lib/db/schema'

export type ExistingFileState = {
  path: string
  fileId: string
}

export const clearStagedChanges = async (runId: string): Promise<void> => {
  await db
    .delete(indexRunFileChanges)
    .where(eq(indexRunFileChanges.runId, runId))
}

export const stageUpsert = async (args: {
  runId: string
  path: string
  fileId: string
  sizeBytes: number
}) => {
  const now = new Date()
  await db
    .insert(indexRunFileChanges)
    .values({
      runId: args.runId,
      path: args.path,
      changeType: 'upsert',
      fileId: args.fileId,
      sizeBytes: args.sizeBytes,
      skipReason: null,
      createdAt: now,
      updatedAt: now,
    })
    .onConflictDoUpdate({
