  const onboardingEvents = { __table: "onboarding_events" }

  const recordOnboardingCompletedIfMissing = mock(async () => {
    return (
      options?.completionResult ?? {
        alreadyCompleted: false,
        onboardingDurationMs: 2_400,
        onboardingCompletedAt: new Date("2026-02-15T00:00:00.000Z"),
