  mock.module("next/headers", () => ({ headers }))
  mock.module("@/lib/auth", () => ({
    auth: {
      api: {
        getSession,
      },
    },
  }))
  mock.module("@/lib/db", () => ({ db: { insert } }))
  mock.module("@/lib/db/schema", () => ({ onboardingEvents }))
  mock.module("@/lib/onboarding/service", () => ({ recordOnboardingCompletedIfMissing }))
  mock.module("@/lib/utils/logger", () => ({ runWithApiRequestLog }))

  const routeModule = await import(`./route?cacheBust=${Math.random().toString(36).slice(2)}`)

  return {
    POST: routeModule.POST as (request: Request) => Promise<Response>,
    loggerContext,
    runWithApiRequestLog,
    headers,
    getSession,
    insert,
    insertValues,
    onboardingEvents,
    recordOnboardingCompletedIfMissing,
  }
}

