"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

type CollapsibleContextValue = {
  open: boolean
  setOpen: (open: boolean) => void
}

const CollapsibleContext = React.createContext<CollapsibleContextValue | null>(null)

const useCollapsibleContext = () => {
  const context = React.useContext(CollapsibleContext)
  if (!context) {
    throw new Error("Collapsible components must be used within a Collapsible.")
  }
  return context
}

type CollapsibleProps = {
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  disabled?: boolean
  asChild?: boolean
  className?: string
  children: React.ReactNode
}

export const Collapsible = ({
  open,
  defaultOpen = false,
  onOpenChange,
  disabled = false,
  className,
  children,
}: CollapsibleProps) => {
  const [internalOpen, setInternalOpen] = React.useState(defaultOpen)
  const controlled = typeof open === "boolean"
  const isOpen = controlled ? open : internalOpen

  React.useEffect(() => {
    if (!controlled) {
      return
    }
    setInternalOpen(open)
  }, [controlled, open])

  const setOpen = React.useCallback(
    (nextOpen: boolean) => {
      if (disabled) {
        return
      }

      if (!controlled) {
        setInternalOpen(nextOpen)
      }
      onOpenChange?.(nextOpen)
    },
    [disabled, controlled, onOpenChange],
  )

  return (
    <CollapsibleContext.Provider value={{ open: isOpen, setOpen }}>
      <div
        className={cn(
          "group/collapsible",
          "data-[state=open]:animate-in data-[state=closed]:animate-out",
          className,
        )}
        data-state={isOpen ? "open" : "closed"}
      >
        {children}
      </div>
    </CollapsibleContext.Provider>
  )
}

type CollapsibleTriggerProps = React.HTMLAttributes<HTMLElement> & {
  asChild?: boolean
}

export const CollapsibleTrigger = ({
  className,
  children,
  asChild,
  onClick,
  ...props
}: CollapsibleTriggerProps) => {
  const { open, setOpen } = useCollapsibleContext()

  const handleClick = (event: React.MouseEvent<HTMLElement>) => {
    onClick?.(event)
    if (event.defaultPrevented) {
      return
    }
    setOpen(!open)
  }

  if (!asChild || !React.isValidElement(children)) {
    return (
      <button
        type="button"
        aria-expanded={open}
        onClick={handleClick}
        className={className}
        {...props}
      >
        {children}
      </button>
    )
  }

  const child = React.Children.only(children) as React.ReactElement<
    React.HTMLAttributes<HTMLElement> & { "data-state"?: string }
  >
  const childProps = child.props

  return React.cloneElement(child, {
    ...props,
    ...childProps,
    onClick: (event: React.MouseEvent<HTMLElement>) => {
      childProps.onClick?.(event)
      if (event.defaultPrevented) {
        return
      }
      handleClick(event)
    },
    "aria-expanded": childProps["aria-expanded"] ?? open,
    "data-state": open ? "open" : "closed",
    className: cn(childProps.className, className),
  })
}

type CollapsibleContentProps = React.HTMLAttributes<HTMLDivElement>

export const CollapsibleContent = ({ className, children, ...props }: CollapsibleContentProps) => {
  const { open } = useCollapsibleContext()

  return (
    <div
      className={cn(
        "data-[state=open]:animate-in data-[state=closed]:animate-out",
        "overflow-hidden",
        className,
      )}
      data-state={open ? "open" : "closed"}
      hidden={!open}
      {...props}
    >
      {children}
    </div>
  )
}

