const querySchema = z.object({
  branch: z.string().trim().min(1).optional(),
  configHash: z.string().trim().min(1).optional(),
})

const asRecord = (value: unknown): Record<string, unknown> | null => {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return null
  }
  return value as Record<string, unknown>
}

const asNumber = (value: unknown) => {
  if (typeof value !== "number" || !Number.isFinite(value)) {
    return null
  }
  return value
}

const buildBranchConfigKey = (branch: string, configHash: string) =>
  `${branch}\u0000${configHash}`

const parseReconcileBranchChecks = (value: unknown) => {
  if (!Array.isArray(value)) {
    return []
  }

  return value.flatMap((entry) => {
    const row = asRecord(entry)
    if (!row) {
      return []
    }

    if (typeof row.branch !== "string" || typeof row.configHash !== "string") {
      return []
    }

    if (typeof row.headSha !== "string" || typeof row.enqueued !== "boolean") {
      return []
    }

    return [
      {
        branch: row.branch,
        configHash: row.configHash,
        lastReadySha: typeof row.lastReadySha === "string" ? row.lastReadySha : null,
        headSha: row.headSha,
        enqueued: row.enqueued,
      },
    ]
  })
}

