    actionBusy,
    canLoadProjects,
    isHydrated,
    buildSignature,
    routeStep,
    setTokenTestBusy,
    setTokenTestFeedback,
    testToken,
    tokenAutoTestTimeoutRef,
    tokenTestResultCacheRef,
    tokenTestRunRef,
    tokenTestSignatureRef,
  ])

  const triggerTokenAutotestNow = useCallback(() => {
    if (!isHydrated || routeStep !== "tokens" || !canLoadProjects || actionBusy) {
      return
    }

    const signature = buildSignature()
    if (!signature || signature.endsWith("::")) {
      return
    }

    if (tokenAutoTestTimeoutRef.current !== null) {
      window.clearTimeout(tokenAutoTestTimeoutRef.current)
      tokenAutoTestTimeoutRef.current = null
    }

    tokenTestSignatureRef.current = signature
    void testToken(signature)
  }, [
    actionBusy,
    buildSignature,
    canLoadProjects,
    isHydrated,
    routeStep,
    testToken,
    tokenAutoTestTimeoutRef,
    tokenTestSignatureRef,
  ])

  return { triggerTokenAutotestNow }
}

