if (!integration) {
  return {
    status: 404,
    outcome: "not_found",
    response: NextResponse.json({ error: "Integration not found." }, { status: 404 }),
  }
}

if (integration.status === "disabled") {
  return {
    status: 409,
    outcome: "conflict",
    response: NextResponse.json({ error: "Integration is disabled." }, { status: 409 }),
  }
}

const parsed = enableSchema.safeParse(payload)
if (!parsed.success) {
  return {
    status: 400,
    outcome: "invalid_request",
    response: NextResponse.json({ error: "Invalid enable payload." }, { status: 400 }),
  }
}

      try {
        const queuedJob = await enqueuePlanJob({
          integrationId: integration.id,
          branch: parsed.data.branch,
          hintedHeadSha: parsed.data.hintedHeadSha,
          configHash: parsed.data.configHash,
          configJson: parsed.data.configJson,
        })
        const reconcileJob = await enqueueReconcileJob({
          integrationId: integration.id,
        })
        logger.set({
          branch: parsed.data.branch,
          planJobId: queuedJob.id,
          reconcileJobId: reconcileJob.id,
        })

        return {
          status: 200,
          outcome: "success",
          response: NextResponse.json({
            data: {
              integrationId: integration.id,
              branch: parsed.data.branch,
              job: queuedJob,
              reconcileJob,
            },
          }),
        }
      } catch (error) {
        const message = error instanceof Error ? error.message : "Failed to enable indexing."
        return {
          status: 400,
          outcome: "invalid_request",
          response: NextResponse.json({ error: message }, { status: 400 }),
        }
      }
    },
  })
}

