import { NextResponse } from "next/server"
import { z } from "zod"

import { CodeGraphError } from "@/lib/code-intelligence/graph-index-pack"
import { samplePersistedGraphForVisualization } from "@/lib/code-intelligence/persisted-graph-query"
import { getSessionUserId } from "@/lib/session"
import { runWithApiRequestLog } from "@/lib/utils/logger"

export const runtime = "nodejs"

const payloadSchema = z.object({
  maxNodes: z.number().int().positive().max(2_000).optional(),
  maxEdges: z.number().int().positive().max(10_000).optional(),
  edgeTypes: z.array(z.string().trim().min(1).max(100)).max(20).optional(),
})

const mapGraphErrorStatus = (code: CodeGraphError["code"]) => {
  if (code === "binary_missing") {
    return 503
  }
  if (code === "missing_index_pack") {
    return 404
  }
  return 502
}

export async function POST(request: Request) {
  return runWithApiRequestLog({
    request,
    path: "/api/code/graph/visualization",
    event: "api.code.graph.visualization",
    handler: async ({ logger }) => {
      const userId = await getSessionUserId()
      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      const payload = await request.json().catch(() => ({}))
      const parsed = payloadSchema.safeParse(payload)

      if (!parsed.success) {
        return {
          status: 400,
          outcome: "invalid_request",
          response: NextResponse.json({ error: "Invalid graph visualization payload." }, { status: 400 }),
        }
      }

      try {
        const graph = await samplePersistedGraphForVisualization(parsed.data)
        logger.set({
          nodeCount: graph.nodes.length,
          edgeCount: graph.edges.length,
          appliedEdgeTypes: graph.appliedEdgeTypes,
        })

        return {
          status: 200,
          outcome: "success",
          response: NextResponse.json({ data: graph }),
        }
      } catch (error) {
        if (error instanceof CodeGraphError) {
          logger.set({
            graphErrorCode: error.code,
            graphErrorDetails: error.details,
          })
          return {
            status: mapGraphErrorStatus(error.code),
            outcome: "graph_failed",
            response: NextResponse.json({ error: error.message }, { status: mapGraphErrorStatus(error.code) }),
          }
        }

        logger.set({ graphErrorCode: "unknown" })
        return {
          status: 500,
          outcome: "graph_failed",
          response: NextResponse.json({ error: "Failed to generate graph visualization payload." }, { status: 500 }),
        }
      }
    },
  })
}

