import type { FileDiffMetadata } from "@pierre/diffs"
import { useMemo } from "react"

import {
  getFileLabel,
  INITIAL_FILE_BATCH_SIZE,
  type DiffDataSource,
  type DiffLoadProfile,
} from "./merge-request-diff-viewer.utils"

type UseMergeRequestDiffDerivedOptions = {
  parsedFiles: FileDiffMetadata[]
  filenameFilter: string
  patchText: string
  visibleResetToken: number
  visibleWindow: { key: string; count: number }
  dataSource: DiffDataSource | null
  loadProfile: DiffLoadProfile
}

export function useMergeRequestDiffDerived({
  parsedFiles,
  filenameFilter,
  patchText,
  visibleResetToken,
  visibleWindow,
  dataSource,
  loadProfile,
}: UseMergeRequestDiffDerivedOptions) {
  const normalizedFilter = filenameFilter.trim().toLowerCase()

  const filteredFiles = useMemo(() => {
    if (!normalizedFilter) {
      return parsedFiles
    }

    return parsedFiles.filter((file) => {
      const label = getFileLabel(file).toLowerCase()
      return label.includes(normalizedFilter)
    })
  }, [normalizedFilter, parsedFiles])

  const totals = useMemo(
    () =>
      filteredFiles.reduce(
        (accumulator, file) => {
          for (const hunk of file.hunks) {
            accumulator.additions += hunk.additionLines
            accumulator.deletions += hunk.deletionLines
          }
          return accumulator
        },
        { additions: 0, deletions: 0 },
      ),
    [filteredFiles],
  )

  const visibleWindowKey = `${visibleResetToken}:${normalizedFilter}:${patchText}`

  const visibleFileCount =
    visibleWindow.key === visibleWindowKey
      ? visibleWindow.count
      : INITIAL_FILE_BATCH_SIZE

  const visibleFiles = filteredFiles.slice(0, visibleFileCount)
  const canLoadMore = visibleFileCount < filteredFiles.length

  const loadProfileSummary = useMemo(() => {
    if (!dataSource || loadProfile.fetchMs == null) {
      return ""
    }

    const parts = [
      `Source: ${dataSource === "changes" ? "changes" : "raw_diffs"}`,
      `fetch ${loadProfile.fetchMs}ms`,
    ]
    if (loadProfile.firstParseMs != null) {
      parts.push(`first parse ${loadProfile.firstParseMs}ms`)
    }
    if (loadProfile.fullParseMs != null) {
      parts.push(`full parse ${loadProfile.fullParseMs}ms`)
    }
    return parts.join(" · ")
  }, [dataSource, loadProfile.fetchMs, loadProfile.firstParseMs, loadProfile.fullParseMs])

  return {
    filteredFiles,
    totals,
    visibleWindowKey,
    visibleFileCount,
    visibleFiles,
    canLoadMore,
    loadProfileSummary,
  }
}

import { NextResponse } from "next/server"
import { z } from "zod"

import { traceGraph, CodeTraceError } from "@/lib/code-intelligence/trace-callers"
import { getSessionUserId } from "@/lib/session"
import { runWithApiRequestLog } from "@/lib/utils/logger"

export const runtime = "nodejs"

const tracePayloadSchema = z
  .object({
    mode: z.enum(["callers", "impact"]).optional(),
    symbol: z.string().trim().min(1).max(300).optional(),
    nodeId: z.string().trim().min(1).max(500).optional(),
    limit: z.number().int().positive().max(200).optional(),
    depth: z.number().int().positive().max(64).optional(),
  })
  .superRefine((value, ctx) => {
    if (!value.symbol && !value.nodeId) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        message: "Either symbol or nodeId is required.",
      })
    }
  })

export async function POST(request: Request) {
  return runWithApiRequestLog({
    request,
    path: "/api/code/trace-callers",
    event: "api.code.trace_callers",
    handler: async ({ logger }) => {
      const userId = await getSessionUserId()
      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      const payload = await request.json().catch(() => ({}))
      const parsed = tracePayloadSchema.safeParse(payload)

if (!parsed.success) {
  return {
    status: 400,
    outcome: "invalid_request",
    response: NextResponse.json({ error: "Invalid trace payload." }, { status: 400 }),
  }
}

const { mode = "callers", symbol, nodeId, limit, depth } = parsed.data

try {
  const results = await traceGraph({
    mode,
    symbol,
    nodeId,
    limit,
    depth: mode === "impact" ? depth : undefined,
  })

  logger.set({
    mode,
    symbol: symbol ?? null,
    nodeId: nodeId ?? null,
    depth: mode === "impact" ? depth ?? 3 : null,
    callersCount: results.length,
  })

  return {
    status: 200,
    outcome: "success",
    response: NextResponse.json({
      data: {
        mode,
        symbol: symbol ?? null,
        nodeId: nodeId ?? null,
        depth: mode === "impact" ? depth ?? 3 : null,
        count: results.length,
        results,
      },
    }),
  }
} catch (error) {

        if (error instanceof CodeTraceError) {
          const status = error.code === "binary_missing" ? 503 : 502
          logger.set({
            traceErrorCode: error.code,
            traceErrorDetails: error.details,
          })

          return {
            status,
            outcome: "trace_failed",
            response: NextResponse.json(
              {
                error:
                  error.code === "binary_missing"
                    ? "Code intelligence CLI is unavailable."
                    : "Failed to trace code graph.",
              },
              { status },
            ),
          }
        }

        logger.set({
          traceErrorCode: "unknown",
        })

        return {
          status: 500,
          outcome: "trace_failed",
          response: NextResponse.json({ error: "Failed to trace code graph." }, { status: 500 }),
        }
      }
    },
  })
}

import { headers } from "next/headers"
import { notFound, redirect } from "next/navigation"

import { IndexingConsole } from "@/components/indexing/indexing-console"
import { SiteHeaderTitle } from "@/components/site-header-title"
import { auth } from "@/lib/auth"
import { buildRepoRouteId, findIntegrationByRepoRouteId } from "@/lib/gitlab/repo-route"
import { listUserIntegrations } from "@/lib/gitlab/service"

type RepoIndexingPageProps = {
  params: Promise<{
    integrationId: string
  }>
}

export default async function RepoIndexingPage({ params }: RepoIndexingPageProps) {
  const session = await auth.api.getSession({
    headers: await headers(),
  })

  if (!session?.user?.id) {
    redirect("/")
  }

  const { integrationId: repoRouteId } = await params
  const integrations = await listUserIntegrations(session.user.id)
  const integration = findIntegrationByRepoRouteId(integrations, repoRouteId)

  if (!integration) {
    notFound()
  }

  const canonicalRepoRouteId = buildRepoRouteId(integration)
  if (repoRouteId !== canonicalRepoRouteId) {
    redirect(`/repos/${encodeURIComponent(canonicalRepoRouteId)}/indexing`)
  }

  return (
    <div className="space-y-6">
      <SiteHeaderTitle title={`${integration.projectName} indexing`} />
      <IndexingConsole
        initialIntegrationId={integration.id}
        fixedIntegration={{
          id: integration.id,
          projectName: integration.projectName,
          projectPath: integration.projectPath,
          status: integration.status,
        }}
      />
    </div>
  )
}

