const resolveFileReviewStatus = (file: FileDiffMetadata, fileKey: string): FileReviewStatus => {
  const candidatePaths = [file.name, file.prevName]
    .filter((path): path is string => typeof path === "string" && path.trim().length > 0)
    .map((path) => normalizePatchPath(path))

  const isFailed = candidatePaths.some((path) => failedFilePaths.has(path))
  if (isFailed) {
    return "failed"
  }
  if (
    reviewRun.stage === "failed" &&
    failedFilePaths.size === 0 &&
    reviewRun.completedBatches === 0 &&
    reviewError.trim().length > 0
  ) {
    return "failed"
  }

  const isReviewingFile = candidatePaths.some((path) => reviewingFilePaths.has(path))
  if (isReviewingFile) {
    return "reviewing"
  }

  const isReviewedFile = candidatePaths.some((path) => reviewedFilePaths.has(path))
  if (isReviewedFile) {
    if (reviewCoverageByFileKey[fileKey]) {
      return "issues"
    }
    return "clean"
  }

  if (!hasReviewAttempt) {
    return "pending"
  }

  return "pending"
}

