      const centerY = rect.top + rect.height / 2;

      const xVal = (e.clientX - centerX) / (window.innerWidth / 2);
      const yVal = (e.clientY - centerY) / (window.innerHeight / 2);

      setPupilTransform({
        x: Math.max(-1, Math.min(1, xVal)) * range,
        y: Math.max(-1, Math.min(1, yVal)) * range,
