      context: { params: Promise<{ integrationId: string }> },
    ) => Promise<Response>,
    loggerContext,
    getSessionUserId,
    getUserIntegration,
    enqueuePlanJob,
    logScopedError,
  }
}

describe("gitlab index reindex route", () => {

