const handleTestAiEndpoint = useCallback(async () => {
  const apiUrl = aiSettings.apiUrl.trim()
  const model = aiSettings.model.trim()

  if (!apiUrl) {
    setAiTestStatus("API URL is required.")
    return
  }
  if (!model) {
    setAiTestStatus("Model is required.")
    return
  }

  let parsedUrl: URL
  try {
    parsedUrl = new URL(apiUrl)
  } catch {
    setAiTestStatus("API URL must be a valid absolute URL.")
    return
  }

  if (!/^https?:$/i.test(parsedUrl.protocol)) {
    setAiTestStatus("API URL must use http or https.")
    return
  }

  setIsTestingAiEndpoint(true)
  setAiTestStatus("Testing AI endpoint connection...")

  try {
    const response = await fetch("/api/ai/test", {
      method: "POST",
      headers: {
        "content-type": "application/json",
      },
      body: JSON.stringify({
        apiUrl,
        model,
        token: aiSettings.token.trim(),
      }),
    })
    const payload = (await response.json().catch(() => null)) as unknown

    if (!response.ok) {
      setAiTestStatus(extractErrorMessage(payload, `Connection test failed (${response.status}).`))
      return
    }

    const root = asRecord(payload)
    const data = asRecord(root?.data)
    const latencyMs = typeof data?.latencyMs === "number" && Number.isFinite(data.latencyMs)
      ? Math.max(1, Math.round(data.latencyMs))
      : null
    setAiTestStatus(
      latencyMs === null
        ? "Connection succeeded."
        : `Connection succeeded in ${latencyMs}ms.`,
    )
  } catch (error) {
    setAiTestStatus(
      error instanceof Error
        ? `Connection failed before response: ${error.message}`
        : "Connection failed before response.",
    )
  } finally {
    setIsTestingAiEndpoint(false)
  }
