import { mkdtemp, readFile, rm } from "node:fs/promises"
import os from "node:os"
import path from "node:path"
import { describe, expect, test } from "bun:test"

import { FsArtifactStore } from "@/lib/indexing/stores/artifact-store.fs"

const withArtifactsRoot = async <T>(fn: (root: string) => Promise<T>) => {
  const root = await mkdtemp(path.join(os.tmpdir(), "argus-artifacts-test-"))
  const previous = process.env.INDEXER_ARTIFACTS_DIR
  process.env.INDEXER_ARTIFACTS_DIR = root

  try {
    return await fn(root)
  } finally {
    if (previous === undefined) {
      delete process.env.INDEXER_ARTIFACTS_DIR
    } else {
      process.env.INDEXER_ARTIFACTS_DIR = previous
    }
    await rm(root, { recursive: true, force: true })
  }
}

describe("FsArtifactStore", () => {
  test("writes artifacts under the configured root", async () =>
    withArtifactsRoot(async (root) => {
      const store = new FsArtifactStore()
      const prefix = "integrations/a/runs/default/main/sha/run-1"

      await store.writeRunJson({
        artifactsPrefix: prefix,
        run: { id: "run-1", status: "ready" },
      })

      const runJsonPath = path.join(root, prefix, "run.json")
      const payload = await readFile(runJsonPath, "utf8")
      expect(payload).toContain('"id": "run-1"')
    }))

  test("rejects traversal prefixes that escape root", async () =>
    withArtifactsRoot(async () => {
      const store = new FsArtifactStore()

      await expect(
        store.writeRunJson({
          artifactsPrefix: "../../outside-root",
          run: { id: "bad" },
        }),
      ).rejects.toThrow("Invalid artifacts prefix path.")
    }))
})

import { NextResponse } from "next/server"

import { db } from "@/lib/db"
import { aiReviewRuns, type AiReviewFinding } from "@/lib/db/schema"
import { getSessionUserId } from "@/lib/session"
import { sha256Hex } from "@/lib/utils/hash"
import { runWithApiRequestLog } from "@/lib/utils/logger"

const DEFAULT_AI_MODEL = "gpt-4o-mini"
const MAX_FINDINGS = 32

type SaveReviewPayload = {
  patch?: unknown
  findings?: unknown
  summary?: unknown
  instanceUrl?: unknown
  projectId?: unknown
  mergeRequestIid?: unknown
}

const isNonEmptyString = (value: unknown): value is string =>
  typeof value === "string" && value.trim().length > 0

const normalizeApiUrl = (value: string) => value.trim().replace(/\/+$/, "")

const toReviewSide = (value: unknown): AiReviewFinding["side"] => {
  const normalized = String(value ?? "")
    .trim()
    .toLowerCase()
  if (
    normalized === "deletions" ||
    normalized === "deletion" ||
    normalized === "removed" ||
    normalized === "left"
  ) {
    return "deletions"
  }
  return "additions"
}

const toReviewSeverity = (value: unknown): AiReviewFinding["severity"] => {
  const normalized = String(value ?? "")
    .trim()
    .toLowerCase()
  if (normalized === "high") {
    return "high"
  }
  if (normalized === "medium" || normalized === "med") {
    return "med"
  }
  return "low"
}

const toConfidence = (value: unknown) => {
  if (typeof value !== "number" || !Number.isFinite(value)) {
    return 0.7
  }
  return Math.max(0, Math.min(1, value))
}

const parseFindings = (value: unknown): AiReviewFinding[] => {
  if (!Array.isArray(value)) {
    return []
  }

  const deduped = new Map<string, AiReviewFinding>()
  for (const item of value) {
    if (!item || typeof item !== "object") {
      continue
    }
    const finding = item as Record<string, unknown>
    const line = Number(finding.line)
    const file = String(finding.file ?? "").trim()
    const title = String(finding.title ?? "").trim()
    const body = String(finding.body ?? finding.explanation ?? "").trim()
    if (!file || !title || !body || !Number.isFinite(line) || line < 1) {
      continue
    }

    const normalized: AiReviewFinding = {
      file,
      line: Math.floor(line),
      side: toReviewSide(finding.side),
      severity: toReviewSeverity(finding.severity),
      title,
      body,
      confidence: toConfidence(finding.confidence),
    }
    const key = `${normalized.file}:${normalized.side}:${normalized.line}:${normalized.title}`
    if (!deduped.has(key)) {
      deduped.set(key, normalized)
    }
  }

  return Array.from(deduped.values()).slice(0, MAX_FINDINGS)
}

const buildReviewSummary = (findings: AiReviewFinding[]) => {
  if (findings.length === 0) {
    return "AI review complete. No findings."
  }
  const highCount = findings.filter((finding) => finding.severity === "high").length
  const medCount = findings.filter((finding) => finding.severity === "med").length
  const lowCount = findings.length - highCount - medCount
  return `AI review complete: ${findings.length} findings (${highCount} high, ${medCount} med, ${lowCount} low).`
}

const getEnvModel = () => {
  if (isNonEmptyString(process.env.AI_MODEL)) {
    return process.env.AI_MODEL.trim()
  }
  if (isNonEmptyString(process.env.OPENAI_MODEL)) {
    return process.env.OPENAI_MODEL.trim()
  }
  return DEFAULT_AI_MODEL
}

export async function POST(request: Request) {
  return runWithApiRequestLog({
    request,
    path: "/api/review/save",
    event: "api.review.save",
    handler: async ({ logger }) => {
      const userId = await getSessionUserId()
      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      const payload = (await request.json().catch(() => null)) as SaveReviewPayload | null
      const patch = isNonEmptyString(payload?.patch) ? payload.patch : ""
      const instanceUrl = normalizeApiUrl(String(payload?.instanceUrl ?? "").trim())
      const projectId = String(payload?.projectId ?? "").trim()
      const mergeRequestIid = String(payload?.mergeRequestIid ?? "").trim()

const findings = parseFindings(payload?.findings)
const summary = isNonEmptyString(payload?.summary)
  ? payload.summary.trim()
  : buildReviewSummary(findings)

if (!patch) {
  return {
    status: 400,
    outcome: "invalid_request",
    response: NextResponse.json({ error: "Patch is required." }, { status: 400 }),
  }
}
if (!instanceUrl || !projectId || !mergeRequestIid) {
  return {
    status: 400,
    outcome: "invalid_request",
    response: NextResponse.json(
      { error: "instanceUrl, projectId, and mergeRequestIid are required." },
      { status: 400 },
    ),
  }
}

const model = getEnvModel()
const inserted = await db
  .insert(aiReviewRuns)
  .values({
    userId,
    instanceUrl,
    projectId,
    mergeRequestIid,
    model,
    patchLength: patch.length,
    patchHash: sha256Hex(patch),
    findings,
    findingsCount: findings.length,
    summary,
  })
  .returning({
    id: aiReviewRuns.id,
    summary: aiReviewRuns.summary,
    findings: aiReviewRuns.findings,
    feedback: aiReviewRuns.feedback,
    createdAt: aiReviewRuns.createdAt,
  })

const row = inserted[0]
logger.set({
  model,
  patchLength: patch.length,
  findingsCount: findings.length,
  reviewId: row?.id ?? null,
})

      return {
        status: 200,
        outcome: "success",
        response: NextResponse.json({
          data: {
            review: row
              ? {
                  id: row.id,
                  summary: row.summary,
                  findings: row.findings,
                  feedback: row.feedback,
                  createdAt: row.createdAt.toISOString(),
                }
              : null,
          },
        }),
      }
    },
  })
}

