const DEFAULT_LIMIT = 50

const asRecord = (value: unknown): Record<string, unknown> | null => {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return null
  }
  return value as Record<string, unknown>
}

const extractErrorMessage = (payload: unknown, fallback: string) => {
  const record = asRecord(payload)
  const rawError = record?.error
  return typeof rawError === "string" && rawError.trim() ? rawError : fallback
}

const formatDateTime = (value: string | null | undefined) => {
  if (!value) {
    return "n/a"
  }
  const parsed = new Date(value)
  if (Number.isNaN(parsed.getTime())) {
    return "invalid"
  }
  return parsed.toLocaleString()
}

const formatDuration = (value: number | null) => {
  if (value === null || value < 0) {
    return "n/a"
  }
  return `${value}ms`
}

const formatAge = (value: number | null) => {
  if (value === null || value < 0) {
    return "n/a"
  }
  const seconds = Math.floor(value / 1000)
  if (seconds < 60) {
    return `${seconds}s`
  }
  const minutes = Math.floor(seconds / 60)
  if (minutes < 60) {
    return `${minutes}m`
  }
  const hours = Math.floor(minutes / 60)
  return `${hours}h`
}

const toIsoQuery = (value: string) => {
  if (!value.trim()) {
    return ""
  }
  const parsed = new Date(value)
  return Number.isNaN(parsed.getTime()) ? "" : parsed.toISOString()
}

const toLocalDateTimeInput = (value: string | null | undefined) => {
  if (!value) {
    return ""
  }
  const parsed = new Date(value)
  if (Number.isNaN(parsed.getTime())) {
    return ""
  }
  const pad = (segment: number) => String(segment).padStart(2, "0")
  return [
    parsed.getFullYear(),
    "-",
    pad(parsed.getMonth() + 1),
    "-",
    pad(parsed.getDate()),
    "T",
    pad(parsed.getHours()),
    ":",
    pad(parsed.getMinutes()),
  ].join("")
}

type BadgeVariant = "default" | "secondary" | "destructive" | "outline"

const levelBadgeVariant = (
  level: LogLevel,
): BadgeVariant => {
  if (level === "error") {
    return "destructive"
  }
  if (level === "warn") {
    return "secondary"
  }
  if (level === "debug") {
    return "outline"
  }
  return "default"
}

const healthBadgeVariant = (status: HealthStatus): BadgeVariant => {
  if (status === "critical") {
    return "destructive"
  }
  if (status === "degraded") {
    return "secondary"
  }
  return "default"
}

const payloadPreview = (payload: Record<string, unknown>) => {
  try {
    const serialized = JSON.stringify(payload, null, 2)
    if (serialized.length <= 280) {
      return serialized
    }
    return `${serialized.slice(0, 280)}...`
  } catch {
    return "[payload serialization failed]"
  }
}

export default function ObservabilityPage() {
  const [logs, setLogs] = useState<LogRecord[]>([])
  const [health, setHealth] = useState<IndexingHealthPayload | null>(null)
  const [ttfr, setTtfr] = useState<OnboardingTtfrPayload | null>(null)
  const [level, setLevel] = useState<FilterLevel>("all")
  const [service, setService] = useState("")
  const [eventName, setEventName] = useState("")
  const [pathFilter, setPathFilter] = useState("")
  const [requestId, setRequestId] = useState("")
  const [statusFilter, setStatusFilter] = useState("")
  const [since, setSince] = useState("")
  const [until, setUntil] = useState("")
  const [minDurationMs, setMinDurationMs] = useState("")

const [pagination, setPagination] = useState<LogPayload["pagination"] | null>(null)
const [isLoading, setIsLoading] = useState(false)
const [isLoadingHealth, setIsLoadingHealth] = useState(false)
const [isLoadingTtfr, setIsLoadingTtfr] = useState(false)
const [errorMessage, setErrorMessage] = useState("")
const [healthErrorMessage, setHealthErrorMessage] = useState("")
const [ttfrErrorMessage, setTtfrErrorMessage] = useState("")
const [lastRefreshedAt, setLastRefreshedAt] = useState<Date | null>(null)
const [autoRefresh, setAutoRefresh] = useState(true)
const [currentPage, setCurrentPage] = useState(1)
const [payloadDialogOpen, setPayloadDialogOpen] = useState(false)
const [selectedPayloadEntry, setSelectedPayloadEntry] = useState<LogRecord | null>(null)

const totalPages = useMemo(
  () => pagination?.totalPages ?? 1,
  [pagination],
)

const loadLogs = useCallback(async (opts: { page?: number } = {}) => {
  const page = opts.page ?? currentPage
  setIsLoading(true)
  setErrorMessage("")

  try {
    const params = new URLSearchParams()
    if (level !== "all") {
      params.set("level", level)
    }
    if (service.trim()) {
      params.set("service", service.trim())
    }
    if (eventName.trim()) {
      params.set("event", eventName.trim())
    }
    if (pathFilter.trim()) {
      params.set("path", pathFilter.trim())
    }
    if (requestId.trim()) {
      params.set("requestId", requestId.trim())
    }
    const normalizedStatus = statusFilter.trim()

  if (normalizedStatus) {
    params.set("status", normalizedStatus)
  }
  const sinceIso = toIsoQuery(since)
  if (sinceIso) {
    params.set("since", sinceIso)
  }
  const untilIso = toIsoQuery(until)
  if (untilIso) {
    params.set("until", untilIso)
  }
  if (minDurationMs.trim()) {
    params.set("minDurationMs", minDurationMs.trim())
  }
  params.set("page", String(page))
  params.set("limit", String(DEFAULT_LIMIT))

  const response = await fetch(`/api/observability/logs?${params.toString()}`, {
    method: "GET",
    headers: {
      "content-type": "application/json",
    },
  })
  const payload = await response.json().catch(() => null)
  if (!response.ok) {
    throw new Error(extractErrorMessage(payload, "Failed to load logs."))
  }

  const typedPayload = payload as LogPayload | null
  const typedLogs = Array.isArray(typedPayload?.data) ? typedPayload.data : []
  setLogs(typedLogs)
  setPagination(
    typedPayload?.pagination ??
      {
        page,
        limit: DEFAULT_LIMIT,
        total: 0,
        totalPages: 1,
      },
  )
  setLastRefreshedAt(new Date())
  setCurrentPage(page)
} catch (error) {
  setLogs([])
  setPagination({
    page,
    limit: DEFAULT_LIMIT,
    total: 0,
    totalPages: 1,
  })
  setErrorMessage(error instanceof Error ? error.message : "Failed to load logs.")
