"use client"

import { QueryClient, QueryClientProvider } from "@tanstack/react-query"
import { useState, type ReactNode } from "react"

const createQueryClient = () =>
  new QueryClient({
    defaultOptions: {
      queries: {
        staleTime: 5 * 60_000,
        gcTime: 30 * 60_000,
        retry: 1,
        refetchOnWindowFocus: false,
        refetchOnReconnect: false,
      },
    },
  })

export const QueryProvider = ({ children }: { children: ReactNode }) => {
  const [queryClient] = useState(createQueryClient)
  return <QueryClientProvider client={queryClient}>{children}</QueryClientProvider>
}

export function useOnboardingTokenInputs({
  gitlabInstance,
  instanceTokens,
  setGitlabInstance,
  setToken,
  setInstanceTokens,
  setCustomInstance,
  setTokenTestFeedback,
  setWebhookSetupFeedback,
}: UseOnboardingTokenInputsOptions) {
  const resetFeedback = useCallback(() => {
    setTokenTestFeedback(null)
    setWebhookSetupFeedback(null)
  }, [setTokenTestFeedback, setWebhookSetupFeedback])

  const handleInstanceChange = useCallback((instanceKey: string) => {
    if (!isInstanceKey(instanceKey)) {
      return
    }

    setGitlabInstance(instanceKey)
    setToken(instanceTokens[instanceKey] ?? "")
    resetFeedback()
  }, [instanceTokens, resetFeedback, setGitlabInstance, setToken])

  const handleTokenChange = useCallback((nextToken: string) => {
    setToken(nextToken)
    setInstanceTokens((current) => ({
      ...current,
      [gitlabInstance]: nextToken,
    }))
    resetFeedback()
  }, [gitlabInstance, resetFeedback, setInstanceTokens, setToken])

  const handleCustomInstanceChange = useCallback((nextCustomInstance: string) => {
    setCustomInstance(nextCustomInstance)
    resetFeedback()
  }, [resetFeedback, setCustomInstance])

  return {
    handleInstanceChange,
    handleTokenChange,
    handleCustomInstanceChange,
  }
}

const parsePositiveInt = (value: string | undefined, fallback: number): number => {
  if (!value) {
    return fallback
  }

  const parsed = Number.parseInt(value, 10)
  if (!Number.isFinite(parsed) || parsed <= 0) {
    return fallback
  }

  return parsed
}

const resolveMaxFileSizeBytes = () =>
  parsePositiveInt(process.env.INDEXER_MAX_FILE_SIZE_BYTES, DEFAULT_MAX_FILE_SIZE_BYTES)

const resolveDeltaFallbackThreshold = () =>
  parsePositiveInt(process.env.INDEXER_DELTA_FALLBACK_THRESHOLD, DEFAULT_DELTA_FALLBACK_THRESHOLD)

const toErrorMessage = (error: unknown) =>
  error instanceof Error ? error.message : 'Unexpected embedding failure.'

const wrapEmbeddingError = (args: {
  path: string
  chunks: Array<Omit<VectorChunkRecord, 'embedding'>>
  error: unknown
}) => {
  const maxChunk = args.chunks.reduce<{ chunkIndex: number; size: number } | null>(
    (largest, chunk) => {
      const size = chunk.content.length
      if (!largest || size > largest.size) {
        return {
          chunkIndex: chunk.chunkIndex,
          size,
        }
      }

      return largest
    },
    null,
  )

  const wrapped = new Error(
    `Embedding failed for ${args.path} (chunks=${args.chunks.length}, maxChunkChars=${maxChunk?.size ?? 0}): ${toErrorMessage(args.error)}`,
  )
  ;(wrapped as Error & { details?: Record<string, unknown> }).details = {
    stage: 'embedding',
    path: args.path,
    chunkCount: args.chunks.length,
    maxChunkChars: maxChunk?.size ?? 0,
    maxChunkIndex: maxChunk?.chunkIndex ?? null,
  }

  return wrapped
}

export class DeltaSnapshotFallbackError extends Error {
  readonly reason: DeltaFallbackReason

  constructor(reason: DeltaFallbackReason) {
    super(`Delta ingest fallback required: ${reason}`)
    this.reason = reason
    this.name = 'DeltaSnapshotFallbackError'
  }
}

export const runDeltaIngest = async (args: {
  run: DeltaRunContext
  source: GitLabSource
  vectorStore: VectorStore
  artifactStore: ArtifactStore
  runtimeDeps?: Partial<DeltaRuntimeDeps>
}): Promise<DeltaResult> => {
  const runtime: DeltaRuntimeDeps = {
    ...defaultRuntimeDeps,
    ...args.runtimeDeps,
  }
  const maxFileSizeBytes = resolveMaxFileSizeBytes()

  const stats = {
    compareChanges: 0,
    filesFetched: 0,
    filesUnchanged: 0,
    filesIndexed: 0,
    filesSkipped: 0,
    filesDeleted: 0,
    chunksUpserted: 0,
  }

  const manifestLines: string[] = []
  const changedFileLines: string[] = []
  const existingByPath = await runtime.loadExistingStates(args.run.branchStateId)

  await runtime.clearStagedChanges(args.run.runId)

  if (!args.run.baseSha) {
    throw new DeltaSnapshotFallbackError('missing_base_sha')
  }

  const compare = await args.source.compare({
    integrationId: args.run.integrationId,
    fromSha: args.run.baseSha,
    toSha: args.run.headSha,
  })
  stats.compareChanges = compare.changes.length

  const fallbackReason = resolveDeltaFallbackReason({
    baseSha: args.run.baseSha,
    compare,
    maxChanges: resolveDeltaFallbackThreshold(),
  })

  if (fallbackReason) {
    throw new DeltaSnapshotFallbackError(fallbackReason)
  }

const deltaPlan = buildDeltaIngestPlan(compare.changes)

for (const deletion of deltaPlan.deletes) {
  await runtime.stageDelete({
    runId: args.run.runId,
    path: deletion.path,
    skipReason: deletion.reason,
  })
  stats.filesDeleted += 1
  manifestLines.push(
    JSON.stringify({
      path: deletion.path,
      status: 'deleted',
      reason: deletion.reason,
    }),
  )
  changedFileLines.push(
    JSON.stringify({
      path: deletion.path,
      changeType: 'deleted',
      reason: deletion.reason,
    }),
  )
}

for (const upsert of deltaPlan.upserts) {
  const file = await args.source.fetchFile({
    integrationId: args.run.integrationId,
    path: upsert.path,
    ref: args.run.headSha,
  })
  stats.filesFetched += 1

  const skipReason = classifySkipReason({
    relativePath: upsert.path,
    content: file.content,
    maxFileSizeBytes,
  })

  const existing = existingByPath.get(upsert.path)
  if (skipReason) {
    stats.filesSkipped += 1
    manifestLines.push(
      JSON.stringify({
        path: upsert.path,
        status: 'skipped',
        skipReason,
      }),
    )

    if (existing) {
      await runtime.stageDelete({
        runId: args.run.runId,
        path: upsert.path,
        skipReason,
      })
      stats.filesDeleted += 1
      changedFileLines.push(
        JSON.stringify({
          path: upsert.path,
          changeType: 'deleted',
          reason: skipReason,
        }),
      )
    }

    continue
  }

const fileId = sha256Hex(file.content)
if (existing?.fileId === fileId) {
  stats.filesUnchanged += 1
  manifestLines.push(
    JSON.stringify({
      path: upsert.path,
      status: 'unchanged',
    }),
  )
  continue
}

const chunks = await runtime.buildVectorChunks({
  path: upsert.path,
  content: file.content.toString('utf8'),
  configHash: args.run.configHash,
})

if (chunks.length === 0) {
  stats.filesSkipped += 1
  manifestLines.push(
    JSON.stringify({
      path: upsert.path,
      status: 'skipped',
      skipReason: 'no_chunks',
    }),
  )

  if (existing) {
    await runtime.stageDelete({
      runId: args.run.runId,
      path: upsert.path,
      skipReason: 'no_chunks',
    })
    stats.filesDeleted += 1
    changedFileLines.push(
      JSON.stringify({
        path: upsert.path,
        changeType: 'deleted',
        reason: 'no_chunks',
      }),
    )
  }
  continue
}

let embeddedChunks: VectorChunkRecord[]
try {
  embeddedChunks = await runtime.embedVectorChunks(chunks)
} catch (error) {
  throw wrapEmbeddingError({
    path: upsert.path,
    chunks,
    error,
  })
}
await args.vectorStore.upsertChunks({
  branchStateId: args.run.branchStateId,
  runId: args.run.runId,
  path: upsert.path,
  fileId,
  chunks: embeddedChunks,
})

    await runtime.stageUpsert({
      runId: args.run.runId,
      path: upsert.path,
      fileId,
      sizeBytes: file.content.length,
    })

    stats.filesIndexed += 1
    stats.chunksUpserted += embeddedChunks.length
    manifestLines.push(
      JSON.stringify({
        path: upsert.path,
        status: existing ? 'changed' : 'new',
        chunks: embeddedChunks.length,
      }),
    )
    changedFileLines.push(
      JSON.stringify({
        path: upsert.path,
        changeType: upsert.changeType,
        oldPath: upsert.oldPath,
        fileId,
      }),
    )
  }

  await args.artifactStore.writeManifest({
    artifactsPrefix: args.run.artifactsPrefix,
    lines: manifestLines,
  })

  await args.artifactStore.writeChangedFiles({
    artifactsPrefix: args.run.artifactsPrefix,
    lines: changedFileLines,
  })

  await args.artifactStore.writeRunJson({
    artifactsPrefix: args.run.artifactsPrefix,
    run: {
      runId: args.run.runId,
      mode: 'delta',
      baseSha: args.run.baseSha,
      headSha: args.run.headSha,
      stats,
    },
  })

  return {
    stats,
  }
}

import { describe, expect, mock, test } from "bun:test"

import {
  indexBranchStates,
  indexFileStates,
  indexRunFileChanges,
  indexRuns,
} from "@/lib/db/schema"

type FinalizeRun = {
  id: string
  branchStateId: string
  baseSha: string | null
  headSha: string
  status: string
}

const loadFinalizeModule = async (dbMock: unknown) => {
  mock.module("@/lib/db", () => ({ db: dbMock }))
  return import(`@/lib/indexing/finalize.ts?cacheBust=${Math.random().toString(36).slice(2)}`)
}

const createFinalizeDbMock = (args: {
  run: FinalizeRun | null
  casSuccess: boolean
  stagedChanges?: Array<{
    path: string
    changeType: "upsert" | "delete"
    fileId: string | null
    sizeBytes: number | null
    skipReason: string | null
  }>
}) => {
  const calls = {
    deleteCalls: 0,
    insertCalls: 0,
    runUpdates: [] as Array<Record<string, unknown>>,
  }

  const tx = {
    select: () => ({
      from: (table: unknown) => {
        if (table === indexRuns) {
          return {
            where: () => ({
              limit: () => Promise.resolve(args.run ? [args.run] : []),
            }),
          }
        }

        if (table === indexRunFileChanges) {
          return {
            where: () => Promise.resolve(args.stagedChanges ?? []),
          }
        }

        throw new Error("Unexpected select table in finalize test.")
      },
    }),

    update: (table: unknown) => ({
      set: (values: Record<string, unknown>) => {
        if (table === indexRuns) {
          calls.runUpdates.push(values)
          return {
            where: () => Promise.resolve([]),
          }
        }

        if (table === indexBranchStates) {
          return {
            where: () => ({
              returning: () => Promise.resolve(args.casSuccess ? [{ id: "branch-state-1" }] : []),
            }),
          }
        }

        throw new Error("Unexpected update table in finalize test.")
      },
    }),
    delete: (table: unknown) => {
      if (table !== indexFileStates) {
        throw new Error("Unexpected delete table in finalize test.")
      }

      return {
        where: () => {
          calls.deleteCalls += 1
          return Promise.resolve([])
        },
      }
    },
    insert: (table: unknown) => {
      if (table !== indexFileStates) {
        throw new Error("Unexpected insert table in finalize test.")
      }

      return {
        values: () => ({
          onConflictDoUpdate: () => {
            calls.insertCalls += 1
            return Promise.resolve([])
          },
        }),
      }
    },
  }

  const db = {
    transaction: async <T>(callback: (txArg: typeof tx) => Promise<T>) => callback(tx),
    update: () => ({
      set: () => ({
        where: () => Promise.resolve([]),
      }),
    }),
  }

  return { db, calls }
}

describe("finalizeIndexRun", () => {

test("applies staged changes and marks ready when CAS succeeds", async () => {
  const dbMock = createFinalizeDbMock({
    run: {
      id: "run-1",
      branchStateId: "branch-state-1",
      baseSha: "base-sha-1",
      headSha: "head-sha-1",
      status: "indexing",
    },
    casSuccess: true,
    stagedChanges: [
      {
        path: "deleted.ts",
        changeType: "delete",
        fileId: null,
        sizeBytes: null,
        skipReason: "deleted",
      },
      {
        path: "new.ts",
        changeType: "upsert",
        fileId: "file-1",
        sizeBytes: 123,
        skipReason: null,
      },
    ],
  })

  const mod = await loadFinalizeModule(dbMock.db)
  const result = await mod.finalizeIndexRun("run-1")

  expect(result.status).toBe("ready")
  expect(dbMock.calls.deleteCalls).toBe(1)
  expect(dbMock.calls.insertCalls).toBe(1)
  expect(
    dbMock.calls.runUpdates.some((entry) => entry.status === "ready"),
  ).toBe(true)
})

  test("marks run superseded and skips file mutations on CAS miss", async () => {
    const dbMock = createFinalizeDbMock({
      run: {
        id: "run-2",
        branchStateId: "branch-state-1",
        baseSha: "base-sha-1",
        headSha: "head-sha-2",
        status: "ingesting",
      },
      casSuccess: false,
      stagedChanges: [
        {
          path: "new.ts",
          changeType: "upsert",
          fileId: "file-2",
          sizeBytes: 456,
          skipReason: null,
        },
      ],
    })

    const mod = await loadFinalizeModule(dbMock.db)
    const result = await mod.finalizeIndexRun("run-2")

    expect(result.status).toBe("superseded")
    expect(dbMock.calls.deleteCalls).toBe(0)
    expect(dbMock.calls.insertCalls).toBe(0)
    expect(
      dbMock.calls.runUpdates.some((entry) => entry.status === "superseded"),
    ).toBe(true)
  })

  test("returns invalid_state for non-finalizable statuses", async () => {
    const dbMock = createFinalizeDbMock({
      run: {
        id: "run-3",
        branchStateId: "branch-state-1",
        baseSha: null,
        headSha: "head-sha-3",
        status: "ready",
      },
      casSuccess: true,
    })

    const mod = await loadFinalizeModule(dbMock.db)
    const result = await mod.finalizeIndexRun("run-3")

    expect(result.status).toBe("invalid_state")
    expect(dbMock.calls.deleteCalls).toBe(0)
    expect(dbMock.calls.insertCalls).toBe(0)
  })
})

