type PipelineStageState = "pending" | "active" | "done" | "failed"

type PipelineStage = {
  key: string
  label: string
  state: PipelineStageState
}

const AUTO_REFRESH_MS = 15_000
const STREAM_RECONNECT_DELAY_MS = 2_000
const LIVE_LOG_STREAM_LIMIT = 120
const MAX_LIVE_LOG_ENTRIES = 240
const WORKER_PENDING_STALE_MS = 3 * 60_000
const WORKER_RECENT_ACTIVITY_MS = 5 * 60_000
const PIPELINE_ACTIVE_STATUSES = new Set(["planned", "ingesting", "indexing"])

const asRecord = (value: unknown): Record<string, unknown> | null => {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return null
  }
  return value as Record<string, unknown>
}

const parseSseRecord = (raw: string): Record<string, unknown> | null => {
  try {
    return asRecord(JSON.parse(raw))
  } catch {
    return null
  }
}

const normalizeRunError = (value: unknown): string | null => {
  if (typeof value === "string" && value.trim().length > 0) {
    return value
  }

  if (value && typeof value === "object" && !Array.isArray(value)) {
    const message = asString((value as { message?: unknown }).message)
    if (message) {
      return message
    }

    const code = asString((value as { code?: unknown }).code)
    if (code) {
      return `Error code: ${code}`
    }

    try {
      return JSON.stringify(value)
    } catch {
      return "Unexpected run error."
    }
  }

  return null
}

const extractErrorMessage = (payload: unknown, fallback: string) => {
  if (
    payload &&
    typeof payload === "object" &&
    "error" in payload &&
    typeof (payload as { error?: unknown }).error === "string"
  ) {
    return (payload as { error: string }).error
  }
  return fallback
}

const formatDateTime = (value: string | null | undefined) => {
  if (!value) {
    return "Never"
  }
  const parsed = new Date(value)
  if (Number.isNaN(parsed.getTime())) {
    return "Unknown"
  }
  return parsed.toLocaleString()
}

const shortSha = (value: string | null | undefined) => {
  if (!value) {
    return "n/a"
  }
  return value.slice(0, 12)
}

const parseTimestampMs = (value: string | null | undefined) => {
  if (!value) {
    return null
  }
  const parsed = new Date(value)
  if (Number.isNaN(parsed.getTime())) {
    return null
  }
  return parsed.getTime()
}

const asString = (value: unknown) =>
  typeof value === "string" && value.trim().length > 0 ? value : null

const truncateText = (value: string, max = 160) =>
  value.length > max ? `${value.slice(0, Math.max(0, max - 3))}...` : value

const formatAge = (ageMs: number | null) => {
  if (ageMs === null || ageMs < 0) {
    return "unknown"
  }

  const minutes = Math.floor(ageMs / 60_000)
  if (minutes < 1) {
    return "under 1m"
  }
  return `${minutes}m`
}

const statusVariant = (
  status: string,
): React.ComponentProps<typeof Badge>["variant"] => {
  if (status === "ready" || status === "succeeded" || status === "active") {
    return "default"
  }
  if (status === "failed" || status === "dead") {
    return "destructive"
  }
  if (
    status === "planned" ||
    status === "pending" ||
    status === "processing" ||
    status === "ingesting" ||
    status === "indexing"
  ) {
    return "secondary"
  }
  return "outline"
}

const logLevelVariant = (
  level: LiveIndexerLogLevel,
): React.ComponentProps<typeof Badge>["variant"] => {
  if (level === "error") {
    return "destructive"
  }
  if (level === "warn") {
    return "secondary"
  }
  if (level === "info") {
    return "default"
  }
  return "outline"
}

const buildBranchKey = (branch: string, configHash: string) =>
  `${branch}\u0000${configHash}`

const isPipelineActiveStatus = (status: string | null | undefined) =>
  Boolean(status && PIPELINE_ACTIVE_STATUSES.has(status))

const buildPipelineStages = (status: string | null): PipelineStage[] => {
  const stages: PipelineStage[] = [
    { key: "planned", label: "Queued", state: "pending" },
    { key: "ingesting", label: "Ingesting", state: "pending" },
    { key: "indexing", label: "Indexing", state: "pending" },
    { key: "complete", label: "Complete", state: "pending" },
  ]

  if (!status) {
    return stages
  }

  if (status === "planned") {
    stages[0].state = "active"
    return stages
  }

  if (status === "ingesting") {
    stages[0].state = "done"
    stages[1].state = "active"
    return stages
  }

  if (status === "indexing") {
    stages[0].state = "done"
    stages[1].state = "done"
    stages[2].state = "active"
    return stages
  }

  stages[0].state = "done"
  stages[1].state = "done"
  stages[2].state = "done"
  stages[3].state = status === "ready" ? "done" : "failed"
  return stages
}

const pipelineStageBadgeVariant = (
  state: PipelineStageState,
): React.ComponentProps<typeof Badge>["variant"] => {
  if (state === "done") {
    return "default"
  }
  if (state === "active") {
    return "secondary"
  }
  if (state === "failed") {
    return "destructive"
  }
  return "outline"
}

const parseLiveLog = (value: unknown): LiveIndexerLog | null => {
  const row = asRecord(value)
  if (!row) {
    return null
  }

  if (
    typeof row.id !== "string" ||
    typeof row.level !== "string" ||
    typeof row.event !== "string" ||
    typeof row.service !== "string"
  ) {
    return null
  }

  const level = row.level as LiveIndexerLogLevel
  if (level !== "info" && level !== "warn" && level !== "error" && level !== "debug") {
    return null
  }

  return {
    id: row.id,
    timestamp: typeof row.timestamp === "string" ? row.timestamp : null,
    createdAt: typeof row.createdAt === "string" ? row.createdAt : null,
    level,
    event: row.event,
    service: row.service,
    requestId: typeof row.requestId === "string" ? row.requestId : null,
    path: typeof row.path === "string" ? row.path : null,
    status: typeof row.status === "number" ? row.status : null,
    durationMs: typeof row.durationMs === "number" ? row.durationMs : null,
    payload: asRecord(row.payload) ?? {},
  }
}

const parseLiveLogs = (value: unknown): LiveIndexerLog[] => {
  if (!Array.isArray(value)) {
    return []
  }

  return value.flatMap((entry) => {
    const parsed = parseLiveLog(entry)
    return parsed ? [parsed] : []
  })
}

const normalizeIndexRun = (value: unknown): IndexRun | null => {
  const row = asRecord(value)
  if (!row) {
    return null
  }

  if (
    typeof row.id !== "string" ||
    typeof row.branchStateId !== "string" ||
    typeof row.branch !== "string" ||
    typeof row.configHash !== "string" ||
    typeof row.headSha !== "string" ||
    typeof row.mode !== "string" ||
    typeof row.status !== "string" ||
    typeof row.createdAt !== "string" ||
    typeof row.updatedAt !== "string"
  ) {
    return null
  }

  return {
    id: row.id,
    branchStateId: row.branchStateId,
    branch: row.branch,
    configHash: row.configHash,
    headSha: row.headSha,
    baseSha: typeof row.baseSha === "string" ? row.baseSha : null,
    mode: row.mode,
    status: row.status,
    error: normalizeRunError(row.error),
    createdAt: row.createdAt,
    updatedAt: row.updatedAt,
  }
}

const liveLogMessage = (entry: LiveIndexerLog) => {
  const payload = asRecord(entry.payload)
  if (!payload) {
    return ""
  }

  if (typeof payload.errorMessage === "string" && payload.errorMessage.trim().length > 0) {
    return payload.errorMessage
  }

  if (typeof payload.outcome === "string" && payload.outcome.trim().length > 0) {
    return `outcome=${payload.outcome}`
  }

  if (typeof payload.errorCode === "string" && payload.errorCode.trim().length > 0) {
    return `errorCode=${payload.errorCode}`
  }

  return ""
}

const branchNeedsReconcile = (branch: IndexBranch) => {
  if (branch.reconcile?.wasEnqueued) {
    return true
  }
  if (branch.reconcile?.headSha) {
    return branch.reconcile.headSha !== (branch.lastReadySha ?? null)
  }
  return false
}

export function IndexingConsole({
  initialIntegrationId = null,
  fixedIntegration = null,
}: IndexingConsoleProps) {
  const router = useRouter()
  const pathname = usePathname()
  const searchParams = useSearchParams()
  const integrationIdFromQuery = searchParams.get("integrationId") ?? ""
  const [integrations, setIntegrations] = useState<GitLabIntegration[]>(
    fixedIntegration ? [fixedIntegration] : [],
  )
  const [selectedIntegrationId, setSelectedIntegrationId] = useState<string>(
    fixedIntegration?.id ?? initialIntegrationId ?? "",
  )
  const [runs, setRuns] = useState<IndexRun[]>([])
  const [runsPagination, setRunsPagination] = useState<IndexRunsPayload["pagination"] | null>(null)
  const [queueSummary, setQueueSummary] = useState<IndexRunsPayload["queue"]>(null)
  const [workerTelemetry, setWorkerTelemetry] = useState<IndexRunsPayload["worker"]>(null)
  const [branches, setBranches] = useState<IndexBranch[]>([])
  const [latestReconcile, setLatestReconcile] = useState<ReconcileSummary | null>(null)
  const [isLoadingIntegrations, setIsLoadingIntegrations] = useState(!fixedIntegration)
  const [isLoadingIndexing, setIsLoadingIndexing] = useState(false)
  const [errorMessage, setErrorMessage] = useState("")
  const [actionMessage, setActionMessage] = useState("")

const [lastRefreshedAt, setLastRefreshedAt] = useState<Date | null>(null)
const [reindexingKey, setReindexingKey] = useState<string | null>(null)
const [recentlyQueuedKey, setRecentlyQueuedKey] = useState<string | null>(null)
const [progressTarget, setProgressTarget] = useState<ProgressTarget | null>(null)
const [progressDialogOpen, setProgressDialogOpen] = useState(false)
const [streamStatus, setStreamStatus] = useState<"idle" | "connecting" | "live" | "disconnected">("idle")
const [liveLogs, setLiveLogs] = useState<LiveIndexerLog[]>([])
const [liveLogStreamStatus, setLiveLogStreamStatus] = useState<"idle" | "connecting" | "live" | "disconnected">("idle")

const selectedIntegration = useMemo(() => {
  if (fixedIntegration) {
    return fixedIntegration
  }
  return integrations.find((integration) => integration.id === selectedIntegrationId) ?? null
}, [fixedIntegration, integrations, selectedIntegrationId])

const staleBranchCount = useMemo(
  () => branches.filter(branchNeedsReconcile).length,
  [branches],
)

const progressBranch = useMemo(() => {
  if (!progressTarget) {
    return null
  }
  return (
    branches.find(
      (branch) =>
        branch.branch === progressTarget.branch &&
        branch.configHash === progressTarget.configHash,
    ) ?? null
  )
}, [branches, progressTarget])

const progressRun = useMemo(() => {
  if (!progressTarget) {
    return null
  }

  const branchLastRunId = progressBranch?.lastRun?.id
  if (branchLastRunId) {
    const byId = runs.find((run) => run.id === branchLastRunId)
    if (byId) {
      return byId
    }
  }

  return (
    runs.find(
      (run) =>
        run.branch === progressTarget.branch &&
        run.configHash === progressTarget.configHash,
    ) ?? null
  )
}, [progressBranch?.lastRun?.id, progressTarget, runs])

const progressRowKey = progressTarget
  ? buildBranchKey(progressTarget.branch, progressTarget.configHash)
  : null

const progressStatus = progressRun?.status ??
  progressBranch?.lastRun?.status ??
  (progressRowKey && progressRowKey === recentlyQueuedKey ? "planned" : null)

const pipelineStages = useMemo(
  () => buildPipelineStages(progressStatus),
  [progressStatus],
)

const progressLogs = useMemo(() => {
  if (!progressTarget) {
    return []
  }

  const runId = progressRun?.id ?? null
  const filtered = liveLogs.filter((entry) => {
    const payload = asRecord(entry.payload)
    if (!payload) {
      return false
    }

    const payloadRunId = asString(payload.runId)
    if (runId && payloadRunId === runId) {
      return true
    }

    const payloadBranch = asString(payload.branch)
    if (payloadBranch !== progressTarget.branch) {
      return false
    }

    const payloadConfigHash = asString(payload.configHash)
    if (payloadConfigHash && payloadConfigHash !== progressTarget.configHash) {
      return false
    }

    return true
  })

  return filtered.slice(-40).reverse()
}, [liveLogs, progressRun?.id, progressTarget])

const workerHealth = useMemo(() => {
  if (workerTelemetry) {
    const heartbeatAgeMs = workerTelemetry.heartbeatAgeMs
    if (workerTelemetry.lastHeartbeatAt === null) {
      return {
        level: "offline" as const,
        label: "offline",
        message: "No worker heartbeat has been recorded yet.",
      }
    }

    if (!workerTelemetry.isOnline) {
      return {
        level: "offline" as const,
        label: "offline",
        message: `Last heartbeat ${formatAge(heartbeatAgeMs)} ago.`,
      }
    }

    return {
      level: "healthy" as const,
      label: "online",
      message: `Last heartbeat ${formatAge(heartbeatAgeMs)} ago.`,
    }
  }

if (!queueSummary) {
  return {
    level: "unknown" as const,
    label: "unknown",
    message: "No queue telemetry yet.",
  }
}

const nowMs = Date.now()
const pending = queueSummary.pending
const processing = queueSummary.processing
const hasBacklog = pending + processing > 0
const oldestPendingAgeMs = (() => {
  const ts = parseTimestampMs(queueSummary.oldestPendingAt)
  return ts === null ? null : nowMs - ts
})()
const lastProcessedAgeMs = (() => {
  const ts = parseTimestampMs(queueSummary.lastProcessedAt)
  return ts === null ? null : nowMs - ts
})()
const hasRecentActivity = (
  lastProcessedAgeMs !== null &&
  lastProcessedAgeMs <= WORKER_RECENT_ACTIVITY_MS
)

if (
  pending > 0 &&
  oldestPendingAgeMs !== null &&
  oldestPendingAgeMs >= WORKER_PENDING_STALE_MS &&
  !hasRecentActivity
) {
  return {
    level: "offline" as const,
    label: "likely offline",
    message: `Pending jobs oldest age: ${formatAge(oldestPendingAgeMs)}.`,
  }
}

if (hasBacklog) {
  return {
    level: "busy" as const,
    label: "active",
    message: `Queue backlog: pending ${pending}, processing ${processing}.`,
  }
}

if (hasRecentActivity) {
  return {
    level: "healthy" as const,
    label: "healthy",
    message: `Last processed ${formatAge(lastProcessedAgeMs)} ago.`,
  }
}

  return {
    level: "unknown" as const,
    label: "unknown",
    message: "No recent processed jobs and no backlog.",
  }
}, [queueSummary, workerTelemetry])

const loadIntegrations = useCallback(async () => {
  if (fixedIntegration) {
    setIntegrations([fixedIntegration])
    setIsLoadingIntegrations(false)
    return
  }

  setIsLoadingIntegrations(true)
  try {
    const response = await fetch("/api/gitlab/integrations", {
      method: "GET",
      headers: { "content-type": "application/json" },
    })
    const payload = await response.json().catch(() => null)
    if (!response.ok) {
      throw new Error(extractErrorMessage(payload, "Failed to load integrations."))
    }

    const records =
      payload &&
        typeof payload === "object" &&
        "data" in payload &&
        Array.isArray((payload as { data?: unknown }).data)
        ? (payload as { data: GitLabIntegration[] }).data
        : []

    setIntegrations(records)
  } catch (error) {
    setErrorMessage(error instanceof Error ? error.message : "Failed to load integrations.")
  } finally {
    setIsLoadingIntegrations(false)
  }
}, [fixedIntegration])

const loadIndexingData = useCallback(async (integrationId: string, quiet?: boolean) => {
  if (!quiet) {
    setIsLoadingIndexing(true)
  }

try {
  const [runsResponse, branchesResponse] = await Promise.all([
    fetch(`/api/gitlab/integrations/${integrationId}/index/runs?page=1&limit=20`, {
      method: "GET",
      headers: { "content-type": "application/json" },
    }),
    fetch(`/api/gitlab/integrations/${integrationId}/index/branches`, {
      method: "GET",
      headers: { "content-type": "application/json" },
    }),
  ])

  const [runsPayload, branchesPayload] = await Promise.all([
    runsResponse.json().catch(() => null),
    branchesResponse.json().catch(() => null),
  ])

  if (!runsResponse.ok) {
    throw new Error(extractErrorMessage(runsPayload, "Failed to load indexing runs."))
  }

  if (!branchesResponse.ok) {
    throw new Error(extractErrorMessage(branchesPayload, "Failed to load branch states."))
  }

  const typedRunsPayload = runsPayload as IndexRunsPayload
  const typedBranchesPayload = branchesPayload as IndexBranchesPayload

  setRuns(
    Array.isArray(typedRunsPayload.data)
      ? typedRunsPayload.data.flatMap((entry) => {
        const run = normalizeIndexRun(entry)
        return run ? [run] : []
      })
      : [],
  )
  setRunsPagination(typedRunsPayload.pagination ?? null)
  setQueueSummary(typedRunsPayload.queue ?? null)
  setWorkerTelemetry(typedRunsPayload.worker ?? null)
  setBranches(Array.isArray(typedBranchesPayload.data) ? typedBranchesPayload.data : [])

    setLatestReconcile(typedBranchesPayload.reconcile ?? typedRunsPayload.reconcile ?? null)
    setLastRefreshedAt(new Date())
    setErrorMessage("")
  } catch (error) {
    setErrorMessage(error instanceof Error ? error.message : "Failed to load indexing data.")
  } finally {
    if (!quiet) {
      setIsLoadingIndexing(false)
    }
  }
}, [])

