  }
  const rowKey = buildBranchKey(branch, configHash)
  setReindexingKey(rowKey)
  setActionMessage("")
  try {
    const response = await fetch(
      `/api/gitlab/integrations/${selectedIntegrationId}/index/reindex`,
      {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({
          branch,
          configHash,
        }),
      },
