    const payload = await response.json().catch(() => null)
    if (!response.ok) {
      throw new Error(extractErrorMessage(payload, `Failed to enqueue reindex for ${branch}.`))
    }
    setActionMessage(`Reindex queued for ${branch}.`)
    setRecentlyQueuedKey(rowKey)
