            totalSessions: sessions.length,
            sessionsWithTtfr: sessionTtfrValues.length,
            p50Ms: overallP50,
            p95Ms: overallP95,
            sloBreached: overallP95 !== null && overallP95 > TTFR_SLO_MS,
          },
