        <PopoverTrigger asChild>
          <button
            className="text-[#FFC169] hover:text-[#FFC169]/80 transition-colors"
            onMouseEnter={() => setOpen(true)}
            onMouseLeave={() => setOpen(false)}
          >
            <Info className="h-4 w-4" />
          </button>
        </PopoverTrigger>
        <PopoverContent
          className="w-80 bg-[#090F1F] border-gray-700 text-white"
          align="end"
          onMouseEnter={() => setOpen(true)}
          onMouseLeave={() => setOpen(false)}
        >
          <div className="space-y-2">
            <h4 className="font-semibold text-[#FFC169]">{row.label}</h4>
            <p className="text-sm text-gray-300">{row.argusDetails}</p>
          </div>
        </PopoverContent>
      </Popover>
    </div>
  );
}

