export type IndexingWorkerBatchSummary = {
  jobsClaimed: number
  jobsSucceeded: number
  jobsFailed: number
  jobsDead: number
  planJobs: number
  reconcileJobs: number
  reconcileScheduled: number
  artifactCleanupTriggered: boolean
  artifactCleanupDeletedRuns: number
  artifactCleanupDeletedBytes: number
  artifactCleanupErrors: number
  queueDepthBefore: QueueDepthSnapshot | null
  queueDepthAfter: QueueDepthSnapshot | null
  deltaFallbacks: number
  deltaFallbackReasons: Record<string, number>
  finalizeFailures: number
  gcFailures: number
  claimed: number
  ready: number
  failed: number
  superseded: number
  skipped: number
}

type RunIndexingWorkerBatchOptions = {
  batchId?: string
}

const parsePositiveInt = (value: string | undefined, fallback: number) => {
  if (!value) {
    return fallback
  }

  const parsed = Number.parseInt(value, 10)
  if (!Number.isFinite(parsed) || parsed <= 0) {
    return fallback
  }

  return parsed
}

const resolveArtifactCleanupIntervalMs = () =>
  parsePositiveInt(process.env.INDEXER_ARTIFACT_CLEANUP_INTERVAL_MS, 30 * 60_000)

let lastArtifactCleanupAt = 0

const toNumber = (value: unknown) => {
  const parsed = Number(value)
  return Number.isFinite(parsed) ? parsed : 0
}

const claimPlannedRuns = async (batchSize: number): Promise<ClaimedRun[]> => {
  const query = sql<ClaimedRun>`
    with due_runs as (
      select
        ${indexRuns.id} as id,
        ${indexRuns.headSha} as head_sha,
        ${indexBranchStates.integrationId} as integration_id,
        ${indexBranchStates.branch} as branch,
        ${indexBranchStates.configHash} as config_hash
      from ${indexRuns}
      inner join ${indexBranchStates}
        on ${indexBranchStates.id} = ${indexRuns.branchStateId}
      where ${indexRuns.status} = 'planned'
      order by ${indexRuns.createdAt} asc
      for update skip locked
      limit ${batchSize}
    ),
    claimed as (
      update ${indexRuns}
        set
          "status" = 'ingesting',
          "updated_at" = now()
      from due_runs
      where ${indexRuns.id} = due_runs.id
      returning ${indexRuns.id} as id
    )
    select
      claimed.id as "id",
      due_runs.head_sha as "headSha",
      due_runs.integration_id as "integrationId",
      due_runs.branch as "branch",
      due_runs.config_hash as "configHash"
    from claimed
    inner join due_runs
      on due_runs.id = claimed.id
  `

  const result = await db.execute(query)
  return result.rows.map((raw) => {
    const row = raw as Record<string, unknown>
    return {
      id: String(row.id),
      headSha: String(row.headSha),
      integrationId: String(row.integrationId),
      branch: String(row.branch),
      configHash: String(row.configHash),
    }
  })
}

export const runIndexingWorkerBatch = async (

try {
  try {
    summary.queueDepthBefore = await getQueueDepthSnapshot()
    batchLog.set({
      queueDepthBefore: summary.queueDepthBefore,
    })
  } catch (error) {
    const errorToLog =
      error instanceof Error
        ? error
        : new Error('Unexpected queue depth snapshot processing error.')
    logScopedError(batchLog, errorToLog, {
      code: 'INDEXER_QUEUE_DEPTH_BEFORE_FAILED',
      why: 'Failed to read queue depth snapshot before batch processing.',
      fix: 'Inspect index_jobs/index_runs queries and database connectivity.',
    })
  }

  const nowMs = Date.now()

if (nowMs - lastArtifactCleanupAt >= resolveArtifactCleanupIntervalMs()) {
  try {
    const cleanupSummary = await cleanupIndexArtifacts()
    summary.artifactCleanupTriggered = cleanupSummary.lock === 'acquired'
    summary.artifactCleanupDeletedRuns = cleanupSummary.deletedRuns
    summary.artifactCleanupDeletedBytes = cleanupSummary.deletedBytes
    summary.artifactCleanupErrors = cleanupSummary.errors
    if (cleanupSummary.lock === 'acquired') {
      lastArtifactCleanupAt = nowMs
    }
    batchLog.set({
      artifactCleanup: cleanupSummary,
    })
  } catch (error) {
    const errorToLog =
      error instanceof Error
        ? error
        : new Error('Unexpected artifact cleanup processing error.')
    logScopedError(batchLog, errorToLog, {
      code: 'INDEXER_ARTIFACT_CLEANUP_FAILED',
      why: 'Failed to prune stale indexing artifacts.',
      fix: 'Inspect artifact retention policy and artifact store connectivity.',
    })
  }
}

try {
  summary.reconcileScheduled = await enqueueDueReconcileJobs()
  batchLog.set({
    reconcileScheduled: summary.reconcileScheduled,
  })
} catch (error) {
  const errorToLog =
    error instanceof Error
      ? error
      : new Error('Unexpected reconcile scheduler processing error.')
  logScopedError(batchLog, errorToLog, {
    code: 'INDEXER_RECONCILE_SCHEDULE_FAILED',
    why: 'Failed to enqueue due reconcile jobs.',
    fix: 'Inspect reconcile scheduler query and index_jobs/index_branch_states health.',
  })
}

const claimedJobs = await claimDueIndexJobs(normalizedBatchSize)
summary.jobsClaimed = claimedJobs.length
batchLog.set({
  jobsClaimed: claimedJobs.length,
})

for (const job of claimedJobs) {
  const jobLog = createScopedLogger({
    method: 'INDEX_JOB',
    path: `/workers/indexer/jobs/${job.jobType}`,
    requestId: job.id,
  })
  const jobStartedAt = Date.now()
  jobLog.set({
    event: 'indexer.job.processing',
    batchId: options.batchId ?? null,
    jobId: job.id,
    jobType: job.jobType,
    integrationId: job.integrationId,
    branch: job.branch,
    configHash: job.configHash,
    attempts: job.attempts,
    debounceKey: job.debounceKey,
  })

  let jobStatus = 500

try {
  const result =
    job.jobType === 'plan'
      ? await (async () => {
          if (!job.branch) {
            throw new Error('Plan job is missing branch.')
          }

          const plannedRun = await processPlanJob({
            integrationId: job.integrationId,
            branch: job.branch,
            hintedHeadSha: job.hintedHeadSha ?? undefined,
            configHash: job.configHash ?? undefined,
            configJson: job.configJson ?? undefined,
            forceReplan: isForcedPlanDebounceKey(job.debounceKey),
          })

          return {
            type: 'plan' as const,
            payload: { run: plannedRun },
          }
        })()
      : await (async () => {
          const reconcile = await processReconcileJob({
            integrationId: job.integrationId,
          })
          return {
            type: 'reconcile' as const,
            payload: reconcile,
          }
        })()

  const committed = await markIndexJobSucceeded({
    jobId: job.id,
    result:
      result.type === 'plan'
        ? {
            type: 'plan',
            ...result.payload,
          }
        : {
            type: 'reconcile',
            ...result.payload,
          },
  })

if (committed) {
  summary.jobsSucceeded += 1
  if (job.jobType === 'plan') {
    summary.planJobs += 1
  } else {
    summary.reconcileJobs += 1
  }

  jobLog.set({
    outcome: 'succeeded',
    committed,
    resultType: result.type,
    runId: result.type === 'plan' ? result.payload.run.runId : null,
    runMode: result.type === 'plan' ? result.payload.run.mode : null,
    reconcileChecked: result.type === 'reconcile' ? result.payload.checked : null,
    reconcileEnqueued: result.type === 'reconcile' ? result.payload.enqueued : null,
  })
  jobStatus = 200
} else {
  jobLog.set({
    outcome: 'succeeded_not_committed',
    committed,
  })
  jobStatus = 409
}

  } catch (error) {
    const status = await markIndexJobFailed({
      job,
      error,
    })
    if (status === 'dead') {
      summary.jobsDead += 1
      jobStatus = 410
    } else if (status === 'failed') {
      summary.jobsFailed += 1
      jobStatus = 500
    } else {
      jobStatus = 500
    }

    const errorToLog =
      error instanceof Error ? error : new Error('Unexpected indexing job processing error.')
    logScopedError(jobLog, errorToLog, {
      code: 'INDEX_JOB_FAILED',
      why: status ? `Job moved to ${status}.` : 'Job failure status was not persisted.',
      fix: 'Inspect job payload and processor path for deterministic retries.',
      details: {
        outcome: 'failed',
        failureStatus: status ?? 'unknown',
      },
    })
  } finally {
    jobLog.emit({
      status: jobStatus,
      durationMs: Date.now() - jobStartedAt,
    })
  }
}

const claimedRuns = await claimPlannedRuns(normalizedBatchSize)
summary.claimed = claimedRuns.length
batchLog.set({
  runsClaimed: claimedRuns.length,
})

for (const run of claimedRuns) {
  const runLog = createScopedLogger({
    method: 'INGEST',
    path: '/workers/indexer/runs/ingest',
    requestId: run.id,
  })
  const runStartedAt = Date.now()

try {
  const result = await processIngestJob({ runId: run.id })

  if (result.status === 'ready') {
    summary.ready += 1
  } else if (result.status === 'failed') {
    summary.failed += 1
  } else if (result.status === 'superseded') {
    summary.superseded += 1
  } else {
    summary.skipped += 1
  }
  if (result.modeFallbackReason) {
    summary.deltaFallbacks += 1
    summary.deltaFallbackReasons[result.modeFallbackReason] =
      (summary.deltaFallbackReasons[result.modeFallbackReason] ?? 0) + 1
  }
  if (result.finalizeStatus === 'invalid_state' || result.finalizeStatus === 'not_found') {
    summary.finalizeFailures += 1
  }
  if (result.gcStatus === 'failed') {
    summary.gcFailures += 1
  }

  runLog.set({
    outcome: result.status,
    statusTransitionFrom: 'planned',
    statusTransitionTo: result.status,
    ingestMode: result.ingestMode,
    modeFallback: result.modeFallback,
    modeFallbackReason: result.modeFallbackReason,
    finalizeStatus: result.finalizeStatus,
    gcStatus: result.gcStatus,
    errorCode: result.errorCode,
    errorMessage: result.errorMessage,
    errorDetails: result.errorDetails,
  })
  runStatus =
    result.status === 'ready'
      ? 200
      : result.status === 'failed'
        ? 500
        : result.status === 'superseded'
          ? 409
          : 204
} catch (error) {

        const errorToLog =
          error instanceof Error ? error : new Error('Unexpected ingest run processing error.')
        logScopedError(runLog, errorToLog, {
          code: 'INGEST_RUN_FAILED',
          why: 'Ingest processor threw before finalize.',
          fix: 'Inspect ingest worker dependencies and run context for this run id.',
        })
        runStatus = 500
        throw error
      } finally {
        runLog.emit({
          status: runStatus,
          durationMs: Date.now() - runStartedAt,
        })
      }
    }

    const hasFailures = summary.jobsFailed > 0 || summary.jobsDead > 0 || summary.failed > 0
    try {
      summary.queueDepthAfter = await getQueueDepthSnapshot()
      batchLog.set({
        queueDepthAfter: summary.queueDepthAfter,
      })
    } catch (error) {
      const errorToLog =
        error instanceof Error
          ? error
          : new Error('Unexpected queue depth snapshot processing error.')
      logScopedError(batchLog, errorToLog, {
        code: 'INDEXER_QUEUE_DEPTH_AFTER_FAILED',
        why: 'Failed to read queue depth snapshot after batch processing.',
        fix: 'Inspect index_jobs/index_runs queries and database connectivity.',
      })
    }
    batchLog.set({
      outcome: hasFailures ? 'partial_failure' : 'success',
    })
    if (hasFailures) {
      batchStatus = 207
    }

    return summary
  } finally {
    const durationMs = Date.now() - startedAt
    batchLog.set({
      durationMs,
      summary,
    })
    batchLog.emit({
      status: batchStatus,
      durationMs,
    })
  }
}

