  flushing: null as Promise<void> | null,
  batchSize: DEFAULT_BATCH_SIZE,
  flushIntervalMs: DEFAULT_FLUSH_INTERVAL_MS,
  dbDrainEnabled: true,
};

const parseBoolean = (value: string | undefined, fallback: boolean) => {
  if (!value) {
    return fallback;
  }

  const normalized = value.trim().toLowerCase();
  if (normalized === "1" || normalized === "true" || normalized === "yes") {
    return true;
  }
  if (normalized === "0" || normalized === "false" || normalized === "no") {
    return false;
  }

  return fallback;
};

const parsePositiveInt = (value: string | undefined, fallback: number) => {
  if (!value) {
    return fallback;
  }

  const parsed = Number.parseInt(value, 10);
  if (!Number.isFinite(parsed) || parsed <= 0) {
    return fallback;
  }

  return parsed;
};

const parseRate = (value: string | undefined, fallback: number) => {
  if (!value) {
    return fallback;
  }

  const parsed = Number.parseInt(value, 10);
  if (!Number.isFinite(parsed)) {
    return fallback;
  }

  return Math.max(0, Math.min(100, parsed));
};

const parseDurationMs = (value: unknown): number | null => {
  if (typeof value === "number" && Number.isFinite(value)) {
    return Math.max(0, Math.floor(value));
  }
  if (typeof value !== "string" || !value.trim()) {
    return null;
  }

  const normalized = value.trim().toLowerCase();
  if (normalized.endsWith("ms")) {
    const parsed = Number.parseFloat(normalized.slice(0, -2));
    return Number.isFinite(parsed) ? Math.max(0, Math.round(parsed)) : null;
  }
  if (normalized.endsWith("s")) {
    const parsed = Number.parseFloat(normalized.slice(0, -1));
    return Number.isFinite(parsed) ? Math.max(0, Math.round(parsed * 1_000)) : null;
  }

  return null;
};

const toSafeJsonObject = (value: unknown): Record<string, unknown> => {
  try {
    if (value && typeof value === "object") {
      return JSON.parse(JSON.stringify(value)) as Record<string, unknown>;
    }
  } catch {
    return { serializationError: true };
  }
  return {};
};

const extractEventName = (event: WideEvent) => {
  if (typeof event.event === "string" && event.event.trim()) {
    return event.event.trim();
  }
  if (typeof event.tag === "string" && event.tag.trim()) {
    return `log.${event.tag.trim()}`;
  }
  if (typeof event.path === "string" && event.path.trim()) {
    return `request.${event.path.trim()}`;
  }
  return "log.unknown";
};

const toDbRow = (event: WideEvent) => {
  const rawStatus =
    typeof event.status === "number" && Number.isFinite(event.status)
      ? Math.floor(event.status)
      : null;

  return {
    timestamp: new Date(event.timestamp),
    level: event.level,
    event: extractEventName(event),
    service: event.service,
    environment: event.environment,
    version: typeof event.version === "string" ? event.version : null,
    commitHash: typeof event.commitHash === "string" ? event.commitHash : null,
    region: typeof event.region === "string" ? event.region : null,
    requestId: typeof event.requestId === "string" ? event.requestId : null,
    method: typeof event.method === "string" ? event.method : null,
    path: typeof event.path === "string" ? event.path : null,
    status: rawStatus,
    durationMs: parseDurationMs(event.duration ?? event.durationMs),
    payload: toSafeJsonObject(event),
  };
};

const scheduleFlush = () => {
  if (state.flushTimer || !state.dbDrainEnabled) {
    return;
  }

  state.flushTimer = setTimeout(() => {
    state.flushTimer = null;
    void flushQueuedLogs();
  }, state.flushIntervalMs);
};

const flushQueuedLogs = async () => {
  if (!state.dbDrainEnabled || state.flushing) {
    return state.flushing ?? Promise.resolve();
  }

  state.flushing = (async () => {
    while (state.queue.length > 0) {
      const batch = state.queue.splice(0, state.batchSize);
      if (batch.length === 0) {
        continue;
      }

      try {
        await db.insert(appLogEvents).values(batch.map(toDbRow));
      } catch (error) {
        // Best effort sink; never block request/worker flow.
        console.error("[logger] failed writing events to db", error);
      }
    }
  })().finally(() => {
    state.flushing = null;
    if (state.queue.length > 0) {
      scheduleFlush();
    }
  });

  return state.flushing;
};

const pushDrainEvent = (ctx: DrainContext) => {
  if (!state.dbDrainEnabled) {
    return;
  }

  if (state.queue.length >= MAX_BUFFER_SIZE) {
    state.queue.shift();
    state.dropCount += 1;
  }
  state.queue.push(ctx.event);

  if (state.queue.length >= state.batchSize) {
    void flushQueuedLogs();
    return;
  }

  scheduleFlush();
};

const resolveSamplingRates = (
  environment: string,
  overrides?: Partial<SamplingRates>,
): SamplingRates => {
  const prodDefaultDebug = environment === "production" ? 0 : 100;

  return {
    info:
      overrides?.info ??
      parseRate(process.env.APP_LOG_SAMPLE_INFO, 100),
    warn:
      overrides?.warn ??
      parseRate(process.env.APP_LOG_SAMPLE_WARN, 100),
    debug:
      overrides?.debug ??
      parseRate(process.env.APP_LOG_SAMPLE_DEBUG, prodDefaultDebug),
    error:
      overrides?.error ??
      parseRate(process.env.APP_LOG_SAMPLE_ERROR, 100),
  };
};

const resolveKeepRules = () => {
  const keep: Array<{ status?: number; duration?: number; path?: string }> = [];

  const minStatus = parsePositiveInt(process.env.APP_LOG_KEEP_MIN_STATUS, 400);
  if (minStatus > 0) {
    keep.push({ status: minStatus });
  }

  const minDuration = parsePositiveInt(process.env.APP_LOG_KEEP_MIN_DURATION_MS, 1_000);
  if (minDuration > 0) {
    keep.push({ duration: minDuration });
  }

  const pathPrefix = process.env.APP_LOG_KEEP_PATH_PREFIX?.trim();
  if (pathPrefix) {
    keep.push({ path: `${pathPrefix}/**` });
  }

  return keep;
};

export const initAppLogger = (options: InitAppLoggerOptions = {}) => {
  if (state.initialized) {
    return;
  }

  const service = options.service ?? process.env.SERVICE_NAME?.trim() ?? "argus-app";
  const environment = options.environment ?? process.env.NODE_ENV ?? "development";

  state.batchSize = parsePositiveInt(process.env.APP_LOG_DB_BATCH_SIZE, DEFAULT_BATCH_SIZE);
  state.flushIntervalMs = parsePositiveInt(
    process.env.APP_LOG_DB_FLUSH_INTERVAL_MS,
    DEFAULT_FLUSH_INTERVAL_MS,
  );
  state.dbDrainEnabled = parseBoolean(process.env.APP_LOG_DB_ENABLED, true);

  initLogger({
    env: {
      service,
      environment,
      version: options.version ?? process.env.npm_package_version,
    },
    pretty: options.pretty,
    sampling: {
      rates: resolveSamplingRates(environment, options.samplingRates),
      keep: resolveKeepRules(),
    },
    drain: state.dbDrainEnabled ? pushDrainEvent : undefined,
  });
  state.initialized = true;

  if (options.initEvent) {
    log.info({
      event: options.initEvent,
      logger: {
        dbDrainEnabled: state.dbDrainEnabled,
        batchSize: state.batchSize,
        flushIntervalMs: state.flushIntervalMs,
      },
      ...(options.initContext ?? {}),
    });
  }
};

export const flushAppLogger = async () => {
  if (state.flushTimer) {
    clearTimeout(state.flushTimer);
    state.flushTimer = null;
  }
  await flushQueuedLogs();
};

export const createCorrelationId = () =>
  typeof crypto.randomUUID === "function"
    ? crypto.randomUUID()
    : `${Date.now()}-${Math.random().toString(16).slice(2)}`;

export const createScopedLogger = (options: ScopedLoggerOptions = {}) => {
  if (!state.initialized) {
    initAppLogger({
      pretty: parseBoolean(process.env.APP_LOG_PRETTY, process.env.NODE_ENV !== "production"),
    });
  }

  return createEvlogRequestLogger({
    method: options.method,
    path: options.path,
    requestId: options.requestId,
  });
};

export const startApiRequestLog = (args: {
  request: Request;
  path: string;
  event: string;
  requestId?: string;
  context?: Record<string, unknown>;
}) => {
  const requestId = args.requestId ?? args.request.headers.get("x-request-id") ?? createCorrelationId();
  const logger = createScopedLogger({
    method: args.request.method,
    path: args.path,
    requestId,
  });
  logger.set({
    event: args.event,
    requestId,
    ...(args.context ?? {}),
  });
  return { logger, requestId };
};

export const runWithApiRequestLog = async (args: {
  request: Request;
  path: string;
  event: string;
  context?: Record<string, unknown>;
  handler: ApiLogHandler;
}) => {
  const startedAt = Date.now();
  const { logger, requestId } = startApiRequestLog({
    request: args.request,
    path: args.path,
    event: args.event,
    context: args.context,
  });

  let status = 500;
  try {
    const result = await args.handler({ logger, requestId });
    status = result.status;
    logger.set({
      outcome: result.outcome ?? (status >= 400 ? "error" : "success"),
      ...(result.context ?? {}),
    });
    return result.response;
  } catch (error) {
    logScopedError(logger, error, {
      code: "API_ROUTE_FAILED",
      why: "Route handler threw before response serialization.",
      fix: "Check request payload parsing, auth checks, and dependency calls.",
    });
    logger.set({
      outcome: "error",
    });
    throw error;
  } finally {
    logger.emit({
      status,
      durationMs: Date.now() - startedAt,
    });
  }
};

export const addLogContext = <T extends object>(
  logger: RequestLogger<T>,
  context: FieldContext<T>,
) => {
  logger.set(context);
};

export const emitScopedLog = <T extends object>(
  logger: RequestLogger<T>,
  context?: FieldContext<T>,
) => {
  logger.emit(context);
};

export const logScopedError = <T extends object>(
  logger: RequestLogger<T>,
  error: unknown,
  metadata: ErrorMetadata = {},
) => {
  const normalizedError =
    error instanceof Error ? error : new Error(typeof error === "string" ? error : "Unknown error.");
  const context: Record<string, unknown> = {
    errorCode: metadata.code ?? "UNEXPECTED_ERROR",
    why: metadata.why,
    fix: metadata.fix,
    link: metadata.link,
    errorDetails: metadata.details ?? null,
  };
  logger.error(normalizedError, context as unknown as FieldContext<T>);
};

