import { and, eq, inArray, isNull, sql } from 'drizzle-orm'

import { db } from '@/lib/db'
import {
  indexBranchStates,
  indexFileStates,
  indexRunFileChanges,
  indexRuns,
} from '@/lib/db/schema'

type FinalizeStatus = 'ready' | 'superseded' | 'not_found' | 'invalid_state'

export type FinalizeIndexRunResult = {
  runId: string
  status: FinalizeStatus
}

const FINALIZABLE_STATUSES = new Set(['ingesting', 'indexing'])

export const markIndexRunFailed = async (
  runId: string,
  error: Record<string, unknown>,
): Promise<void> => {
  await db
    .update(indexRuns)
    .set({
      status: 'failed',
      error,
      updatedAt: new Date(),
    })
    .where(eq(indexRuns.id, runId))
}

export const finalizeIndexRun = async (runId: string): Promise<FinalizeIndexRunResult> => {
  return db.transaction(async (tx) => {
    const [run] = await tx
      .select({
        id: indexRuns.id,
        branchStateId: indexRuns.branchStateId,
        baseSha: indexRuns.baseSha,
        headSha: indexRuns.headSha,
        status: indexRuns.status,
      })
      .from(indexRuns)
      .where(eq(indexRuns.id, runId))
      .limit(1)

    if (!run) {
      return { runId, status: 'not_found' }
    }

    if (!FINALIZABLE_STATUSES.has(run.status)) {
      return { runId, status: 'invalid_state' }
    }

    const now = new Date()

    if (deletePaths.length > 0) {
      await tx
        .delete(indexFileStates)
        .where(
          and(
            eq(indexFileStates.branchStateId, run.branchStateId),
            inArray(indexFileStates.path, deletePaths),
          ),
        )
    }

    const upserts = stagedChanges.filter(
      (change) => change.changeType === 'upsert' && change.fileId && change.sizeBytes !== null,
    )

    if (upserts.length > 0) {
      await tx
        .insert(indexFileStates)
        .values(
          upserts.map((change) => ({
            branchStateId: run.branchStateId,
            path: change.path,
            fileId: change.fileId as string,
            sizeBytes: change.sizeBytes as number,
            skipReason: change.skipReason,
            lastReadySha: run.headSha,
            createdAt: now,
            updatedAt: now,
          })),
        )
        .onConflictDoUpdate({
          target: [indexFileStates.branchStateId, indexFileStates.path],
          set: {
            fileId: sql`excluded.file_id`,
            sizeBytes: sql`excluded.size_bytes`,
            skipReason: sql`excluded.skip_reason`,
            lastReadySha: run.headSha,
            updatedAt: now,
          },
        })
    }

    await tx
      .update(indexRuns)
      .set({
        status: 'ready',
        error: null,
        updatedAt: now,
      })
      .where(eq(indexRuns.id, run.id))

    return { runId: run.id, status: 'ready' }
  })
}

import { headers } from "next/headers"
import { notFound, redirect } from "next/navigation"

import { RepoProjectTabs } from "@/components/repos/repo-project-tabs"
import { SiteHeaderTitle } from "@/components/site-header-title"
import { auth } from "@/lib/auth"
import { buildRepoRouteId, findIntegrationByRepoRouteId } from "@/lib/gitlab/repo-route"
import { listUserIntegrations } from "@/lib/gitlab/service"

type RepoPageProps = {
  params: Promise<{
    integrationId: string
  }>
}

const integrationStatusLabel: Record<"active" | "degraded" | "disabled", string> = {
  active: "Active",
  degraded: "Degraded",
  disabled: "Disabled",
}

const integrationStatusVariant: Record<"active" | "degraded" | "disabled", "default" | "secondary" | "outline"> = {
  active: "default",
  degraded: "secondary",
  disabled: "outline",
}

export default async function RepoPage({ params }: RepoPageProps) {
  const session = await auth.api.getSession({
    headers: await headers(),
  })

  if (!session?.user?.id) {
    redirect("/")
  }

  const { integrationId: repoRouteId } = await params
  const integrations = await listUserIntegrations(session.user.id)
  const integration = findIntegrationByRepoRouteId(integrations, repoRouteId)

  if (!integration) {
    notFound()
  }

  const canonicalRepoRouteId = buildRepoRouteId(integration)
  if (repoRouteId !== canonicalRepoRouteId) {
    redirect(`/repos/${encodeURIComponent(canonicalRepoRouteId)}`)
  }

  return (
    <div className="space-y-6">
      <SiteHeaderTitle title={integration.projectName} />

      <RepoProjectTabs
        integrationId={integration.id}
        repoRouteId={canonicalRepoRouteId}
        instanceUrl={integration.instanceUrl}
        projectId={integration.projectId}
        projectName={integration.projectName}
        projectPath={integration.projectPath}
        integrationStatus={integration.status}
        integrationStatusLabel={integrationStatusLabel[integration.status]}
        integrationStatusVariant={integrationStatusVariant[integration.status]}
        lastWebhookReceivedAt={integration.lastWebhookReceivedAt?.toISOString() ?? null}
        lastHookSyncAt={integration.lastHookSyncAt?.toISOString() ?? null}
        lastError={integration.lastError}
      />
    </div>
  )
}

