type GitLabRouteErrorCode =
  | "GITLAB_TOKEN_REQUIRED"
  | "GITLAB_TOKEN_STALE"
  | "GITLAB_TOKEN_INVALID"
  | "GITLAB_TOKEN_SCOPE_INVALID"
  | "GITLAB_HOST_UNREACHABLE"
  | "GITLAB_NETWORK_VPN_REQUIRED"
  | "GITLAB_TIMEOUT"
  | "GITLAB_RESOURCE_UNAUTHORIZED"
  | "GITLAB_RATE_LIMITED"
  | "GITLAB_UPSTREAM_TRANSIENT"
  | "GITLAB_UPSTREAM_ERROR";

type GitLabRouteErrorOptions = {
  status: number;
  code: GitLabRouteErrorCode;
  retryable?: boolean;
  reconnectRequired?: boolean;
  details?: Record<string, unknown>;
};

const MAX_PATCH_BYTES = 50_000_000;
const MAX_CACHED_PATCH_BYTES = 2_500_000;
const MERGE_REQUESTS_PER_PAGE_DEFAULT = 5;
const MERGE_REQUESTS_PER_PAGE_MAX = 100;
const PROJECTS_PER_PAGE_DEFAULT = 5;
const PROJECTS_PER_PAGE_MAX = 100;
const GITLAB_CACHE_TTL_MS = 15_000;
const GITLAB_CACHE_MAX_ENTRIES = 128;
const GITLAB_REQUEST_TIMEOUT_MS = 12_000;
const GITLAB_DIFF_REQUEST_TIMEOUT_MS = 60_000;
const GITLAB_VALIDATE_TIMEOUT_MS = 6_000;
const DIFF_TOO_LARGE_ERROR =
  "Diff exceeds maximum supported size of 50 MB.";

const TOKEN_STALE_CODES = new Set<GitLabRouteErrorCode>([
  "GITLAB_TOKEN_INVALID",
  "GITLAB_TOKEN_SCOPE_INVALID",
]);

type CacheEntry = {
  expiresAt: number;
  value: Promise<unknown>;
};

const gitLabResponseCache = new Map<string, CacheEntry>();

class GitLabRouteError extends Error {
  status: number;
  code: GitLabRouteErrorCode;
  retryable: boolean;
  reconnectRequired: boolean;
  details: Record<string, unknown> | null;

  constructor(message: string, options: GitLabRouteErrorOptions) {
    super(message);
    this.status = options.status;
    this.code = options.code;
    this.retryable = options.retryable ?? false;
    this.reconnectRequired = options.reconnectRequired ?? false;
    this.details = options.details ?? null;
  }
}

const isNonEmptyString = (value: unknown): value is string =>
  typeof value === "string" && value.trim().length > 0;

const asRecord = (value: unknown): Record<string, unknown> | null => {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return null;
  }

  return value as Record<string, unknown>;
};

const hashTokenForCache = (token: string) =>
  createHash("sha256").update(token).digest("hex");

const normalizePerPage = (value: unknown, fallback: number, max: number) => {
  if (typeof value !== "number" || Number.isNaN(value)) {
    return fallback;
  }

  const normalized = Math.floor(value);
  return Math.min(max, Math.max(1, normalized));
};

const buildRouteError = (message: string, options: GitLabRouteErrorOptions) =>
  new GitLabRouteError(message, options);

const getTruncatedBodyMessage = async (response: Response) => {
  const responseText = await response.text().catch(() => "");
  return responseText.length > 0 ? responseText.slice(0, 400) : "";
};

const classifyGitLabHttpError = (

  status: number,
  bodyMessage: string,
  action: GitLabAction,
) => {
  const normalizedBody = bodyMessage.toLowerCase();

  if (status === 401) {
    return buildRouteError(
      "GitLab token is invalid or expired. Reconnect your instance.",
      {
        status: 401,
        code: "GITLAB_TOKEN_INVALID",
        reconnectRequired: true,
      },
    );
  }

  if (status === 403) {
    if (
      normalizedBody.includes("scope") ||
      normalizedBody.includes("insufficient")
    ) {
      return buildRouteError(
        "GitLab token is missing required scope. Reconnect with api scope.",
        {
          status: 403,
          code: "GITLAB_TOKEN_SCOPE_INVALID",
          reconnectRequired: true,
        },
      );
    }

    if (action !== "projects" && action !== "validate-token") {
      return buildRouteError(
        "You do not have access to this project or merge request.",
        {
          status: 403,
          code: "GITLAB_RESOURCE_UNAUTHORIZED",
        },
      );
    }
  }

  if (status === 404 && action !== "projects") {
    return buildRouteError(
      "Project or merge request not found or access is restricted.",
      {
        status: 404,
        code: "GITLAB_RESOURCE_UNAUTHORIZED",
      },
    );
  }

  if (status === 429) {
    return buildRouteError("GitLab rate limit reached. Wait and retry.", {
      status: 429,
      code: "GITLAB_RATE_LIMITED",
      retryable: true,
    });
  }

  if (status >= 500) {
    return buildRouteError(
      "GitLab is temporarily unavailable. Try again shortly.",
      {
        status,
        code: "GITLAB_UPSTREAM_TRANSIENT",
        retryable: true,
      },
    );
  }

  return buildRouteError(
    bodyMessage
      ? `GitLab request failed (${status}): ${bodyMessage}`
      : `GitLab request failed (${status}).`,
    {
      status,
      code: "GITLAB_UPSTREAM_ERROR",
    },
  );
};

const isLikelyVpnHost = (instanceUrl: string) => {
  try {
    const host = new URL(instanceUrl).hostname.toLowerCase();
    return host.endsWith(".lmco.com");
  } catch {
    return false;
  }
};

const classifyNetworkError = (error: unknown, instanceUrl: string) => {
  const message = error instanceof Error ? error.message : String(error);
  const normalized = message.toLowerCase();

  if (error instanceof Error && error.name === "AbortError") {
    return buildRouteError(
      "GitLab request timed out. Check host connectivity and retry.",
      {
        status: 504,
        code: "GITLAB_TIMEOUT",
        retryable: true,
      },
    );
  }

if (
  normalized.includes("enotfound") ||
  normalized.includes("eai_again") ||
  normalized.includes("dns")
) {
  const vpnLikely = isLikelyVpnHost(instanceUrl);
  return buildRouteError(
    vpnLikely
      ? "Cannot reach GitLab host. Connect to the required network or VPN and retry."
      : "GitLab host could not be resolved. Verify the instance URL and network.",
    {
      status: 502,
      code: vpnLikely
        ? "GITLAB_NETWORK_VPN_REQUIRED"
        : "GITLAB_HOST_UNREACHABLE",
      retryable: true,
    },
  );
}

if (
  normalized.includes("timeout") ||
  normalized.includes("timed out") ||
  normalized.includes("econnrefused") ||
  normalized.includes("econnreset")
) {
  const vpnLikely = isLikelyVpnHost(instanceUrl);
  return buildRouteError(
    vpnLikely
      ? "GitLab host is unreachable from this network. Connect VPN and retry."
      : "GitLab host is unreachable. Verify URL and network.",
    {
      status: 502,
      code: vpnLikely
        ? "GITLAB_NETWORK_VPN_REQUIRED"
        : "GITLAB_HOST_UNREACHABLE",
      retryable: true,
    },
  );
}

return buildRouteError("Unable to reach GitLab host.", {
  status: 502,
  code: "GITLAB_HOST_UNREACHABLE",
  retryable: true,
  details: {
    cause: message,
  },
});

};

const getGitLabRequest = async ({
  instanceUrl,
  token,
  apiPath,
  action,
}: {
  instanceUrl: string;
  token: string;
  apiPath: string;
  action: GitLabAction;
}) => {
  const controller = new AbortController();
  const timeoutMs =
    action === "validate-token"
      ? GITLAB_VALIDATE_TIMEOUT_MS
      : action === "merge-request-diff"
        ? GITLAB_DIFF_REQUEST_TIMEOUT_MS
        : GITLAB_REQUEST_TIMEOUT_MS;
  const timeout = setTimeout(() => {
    controller.abort();
  }, timeoutMs);

  try {
    const response = await fetch(`${instanceUrl}${apiPath}`, {
      headers: {
        "PRIVATE-TOKEN": token,
        "User-Agent": "argus-app",
      },
      method: "GET",
      signal: controller.signal,
    });

    if (!response.ok) {
      const bodyMessage = await getTruncatedBodyMessage(response);
      throw classifyGitLabHttpError(response.status, bodyMessage, action);
    }

    return response;
  } catch (error) {
    if (error instanceof GitLabRouteError) {
      throw error;
    }

    throw classifyNetworkError(error, instanceUrl);
  } finally {
    clearTimeout(timeout);
  }
};

const getGitLabJson = async <T>({
  instanceUrl,
  token,
  apiPath,
  action,
}: {
  instanceUrl: string;
  token: string;
  apiPath: string;
  action: GitLabAction;
}) => {
  const response = await getGitLabRequest({
    instanceUrl,
    token,
    apiPath,
    action,
  });
  return (await response.json()) as T;
};

const trimGitLabResponseCache = () => {
  const now = Date.now();
  for (const [key, value] of gitLabResponseCache.entries()) {
    if (value.expiresAt <= now) {
      gitLabResponseCache.delete(key);
    }
  }

  while (gitLabResponseCache.size > GITLAB_CACHE_MAX_ENTRIES) {
    const oldestKey = gitLabResponseCache.keys().next().value;
    if (!oldestKey) {
      return;
    }
    gitLabResponseCache.delete(oldestKey);
  }
};

const getCachedGitLabValue = <T>(
  key: string,
  load: () => Promise<T>,
  options?: { shouldCacheValue?: (value: T) => boolean },
) => {
  const now = Date.now();
  const cached = gitLabResponseCache.get(key);
  if (cached && cached.expiresAt > now) {
    return cached.value as Promise<T>;
  }
  if (cached) {
    gitLabResponseCache.delete(key);
  }

  const promise = load();
  gitLabResponseCache.set(key, {
    expiresAt: now + GITLAB_CACHE_TTL_MS,
    value: promise,
  });
  trimGitLabResponseCache();

  promise
    .then((value) => {
      if (!options?.shouldCacheValue || options.shouldCacheValue(value)) {
        return;
      }
      const current = gitLabResponseCache.get(key);
      if (current?.value === promise) {
        gitLabResponseCache.delete(key);
      }
    })
    .catch(() => {
      const current = gitLabResponseCache.get(key);
      if (current?.value === promise) {
        gitLabResponseCache.delete(key);
      }
    });

  return promise;
};

const getPatchSizeBytes = (patch: string) => Buffer.byteLength(patch, "utf8");

const shouldCachePatchPayload = (payload: { patch: string }) =>
  getPatchSizeBytes(payload.patch) <= MAX_CACHED_PATCH_BYTES;

const buildDiffTooLargeError = () =>
  new GitLabRouteError(DIFF_TOO_LARGE_ERROR, {
    status: 413,
    code: "GITLAB_UPSTREAM_ERROR",
  });

const getCachedGitLabJson = <T>({
  instanceUrl,
  token,
  apiPath,
  action,
}: {
  instanceUrl: string;
  token: string;
  apiPath: string;
  action: GitLabAction;
}) => {
  const tokenHash = hashTokenForCache(token);
  return getCachedGitLabValue(
    `json::${instanceUrl}::${tokenHash}::${apiPath}`,
    () =>
      getGitLabJson<T>({
        instanceUrl,
        token,
        apiPath,
        action,
      }),
  );
};

const normalizeGitLabUser = (value: unknown): GitLabCurrentUser => {
  const root = asRecord(value);
  if (!root) {
    return {
      id: null,
      username: null,
      name: null,
    };
  }

  return {
    id:
      typeof root.id === "number" && Number.isFinite(root.id) ? root.id : null,
    username:
      typeof root.username === "string" && root.username.trim().length > 0
        ? root.username.toLowerCase()
        : null,
    name:
      typeof root.name === "string" && root.name.trim().length > 0
        ? root.name.toLowerCase()
        : null,
  };
};

const isSameGitLabUser = (
  candidate: unknown,
  currentUser: GitLabCurrentUser,
) => {
  const root = asRecord(candidate);
  if (!root) {
    return false;
  }

  if (
    currentUser.id !== null &&
    typeof root.id === "number" &&
    root.id === currentUser.id
  ) {
    return true;
  }

  const username =
    typeof root.username === "string" && root.username.trim().length > 0
      ? root.username.toLowerCase()
      : null;
  if (username && currentUser.username && username === currentUser.username) {
    return true;
  }

  const name =
    typeof root.name === "string" && root.name.trim().length > 0
      ? root.name.toLowerCase()
      : null;

  return Boolean(name && currentUser.name && name === currentUser.name);
};

const mapMergeRequest = (
  row: Record<string, unknown>,
  currentUser: GitLabCurrentUser,
): MergeRequest => {
  const assignees = Array.isArray(row.assignees) ? row.assignees : [];
  const reviewers = Array.isArray(row.reviewers) ? row.reviewers : [];

  const authorRecord = asRecord(row.author);
  const authorName =
    typeof authorRecord?.name === "string" &&
    authorRecord.name.trim().length > 0
      ? authorRecord.name
      : "Unknown author";

  return {
    id: String(row.id),
    iid: String(row.iid),
    title: String(row.title ?? ""),
    state: String(row.state ?? "unknown"),
    author: authorName,
    webUrl: String(row.web_url ?? ""),
    projectId:
      typeof row.project_id === "number" || typeof row.project_id === "string"
        ? String(row.project_id)
        : undefined,
    authoredByCurrentUser: isSameGitLabUser(row.author, currentUser),
    assignedToCurrentUser: assignees.some((assignee) =>
      isSameGitLabUser(assignee, currentUser),
    ),
    reviewRequestedFromCurrentUser: reviewers.some((reviewer) =>
      isSameGitLabUser(reviewer, currentUser),
    ),
  };
};

const buildPatchFromChanges = (payload: unknown) => {
  const root =
    payload && typeof payload === "object"
      ? (payload as Record<string, unknown>)
      : null;

  const changes = Array.isArray(root?.changes)
    ? root.changes.filter(
        (item): item is Record<string, unknown> =>
          Boolean(item) && typeof item === "object",
      )
    : [];

  return changes
    .map((change) => {
      const rawDiff = String(change.diff ?? "").trimEnd();
      if (!rawDiff) {
        return null;
      }

      if (rawDiff.startsWith("diff --git ")) {
        return rawDiff;
      }

      const oldPath = String(change.old_path ?? change.new_path ?? "unknown");
      const newPath = String(change.new_path ?? change.old_path ?? "unknown");
      const oldHeader = change.new_file === true ? "/dev/null" : `a/${oldPath}`;
      const newHeader =
        change.deleted_file === true ? "/dev/null" : `b/${newPath}`;
      const diffHeader = `diff --git a/${oldPath} b/${newPath}`;
      const includesFileHeaders =
        /^---\s/m.test(rawDiff) && /^\+\+\+\s/m.test(rawDiff);

      if (includesFileHeaders) {
        return `${diffHeader}\n${rawDiff}`;
      }

      return `${diffHeader}\n--- ${oldHeader}\n+++ ${newHeader}\n${rawDiff}`;
    })
    .filter((value): value is string => Boolean(value))
    .join("\n\n");
};

const getMergeRequestPatchFromChanges = async ({
  instanceUrl,
  token,
  encodedProjectId,
  encodedMergeRequestIid,
}: {
  instanceUrl: string;
  token: string;
  encodedProjectId: string;
  encodedMergeRequestIid: string;
}) => {
  const changesPayload = await getGitLabJson<Record<string, unknown>>({
    instanceUrl,
    token,
    action: "merge-request-diff",
    apiPath: `/api/v4/projects/${encodedProjectId}/merge_requests/${encodedMergeRequestIid}/changes?access_raw_diffs=true`,
  });
  const fallbackPatch = buildPatchFromChanges(changesPayload);

  if (!fallbackPatch.trim()) {
    throw new GitLabRouteError("Merge request has no diff content to render.", {
      status: 404,
      code: "GITLAB_RESOURCE_UNAUTHORIZED",
    });
  }

  if (getPatchSizeBytes(fallbackPatch) > MAX_PATCH_BYTES) {
    throw buildDiffTooLargeError();
  }

  return fallbackPatch;
};

const getMergeRequestPatchStreamResponse = async ({
  instanceUrl,
  token,
  projectId,
  mergeRequestIid,
}: {
  instanceUrl: string;
  token: string;
  projectId: string;
  mergeRequestIid: string;
}) => {
  const encodedProjectId = encodeURIComponent(projectId);
  const encodedMergeRequestIid = encodeURIComponent(mergeRequestIid);

  try {
    const rawDiffResponse = await getGitLabRequest({
      instanceUrl,
      token,
      apiPath: `/api/v4/projects/${encodedProjectId}/merge_requests/${encodedMergeRequestIid}/raw_diffs`,
      action: "merge-request-diff",
    });

    const contentLength = Number(rawDiffResponse.headers.get("content-length"));

if (Number.isFinite(contentLength) && contentLength > MAX_PATCH_BYTES) {
  throw buildDiffTooLargeError();
}

if (rawDiffResponse.body) {
  const reader = rawDiffResponse.body.getReader();
  const firstRead = await reader.read();

if (!firstRead.done && firstRead.value && firstRead.value.byteLength > 0) {
  let bytesRead = firstRead.value.byteLength;
  if (bytesRead > MAX_PATCH_BYTES) {
    throw buildDiffTooLargeError();
  }

  const firstChunk = firstRead.value;
  const stream = new ReadableStream<Uint8Array>({
    start(controller) {
      controller.enqueue(firstChunk);
      void (async () => {
        try {
          while (true) {
            const { done, value } = await reader.read();
            if (done) {
              break;
            }
            if (!value || value.byteLength === 0) {
              continue;
            }
            bytesRead += value.byteLength;
            if (bytesRead > MAX_PATCH_BYTES) {
              throw buildDiffTooLargeError();
            }
            controller.enqueue(value);
          }
          controller.close();
        } catch (error) {
          controller.error(error);
        } finally {
          reader.releaseLock();
        }
      })();
    },
    cancel(reason) {
      return reader.cancel(reason);
    },
  });

  return new Response(stream, {
    headers: {
      "content-type": "text/plain; charset=utf-8",
      "cache-control": "no-store",
      "x-diff-source": "raw_diffs",
    },
  });
}
reader.releaseLock();

  } else {
    const patch = await rawDiffResponse.text();
    if (getPatchSizeBytes(patch) > MAX_PATCH_BYTES) {
      throw buildDiffTooLargeError();
    }
    if (patch.trim().length > 0) {
      return new Response(patch, {
        headers: {
          "content-type": "text/plain; charset=utf-8",
          "cache-control": "no-store",
          "x-diff-source": "raw_diffs",
        },
      });
    }
  }
} catch (rawDiffError) {
  if (
    rawDiffError instanceof GitLabRouteError &&
    rawDiffError.status === 413
  ) {
    throw rawDiffError;
  }
}

const fallbackPatch = await getMergeRequestPatchFromChanges({
  instanceUrl,
  token,
  encodedProjectId,
  encodedMergeRequestIid,
});

return new Response(fallbackPatch, {
  headers: {
    "content-type": "text/plain; charset=utf-8",
    "cache-control": "no-store",
    "x-diff-source": "changes",
  },
});

};

const getMergeRequestPatch = async ({
  instanceUrl,
  token,
  projectId,
  mergeRequestIid,
}: {
  instanceUrl: string;
  token: string;
  projectId: string;
  mergeRequestIid: string;
}) => {
  const encodedProjectId = encodeURIComponent(projectId);
  const encodedMergeRequestIid = encodeURIComponent(mergeRequestIid);

  try {
    const rawDiffResponse = await getGitLabRequest({
      instanceUrl,
      token,
      apiPath: `/api/v4/projects/${encodedProjectId}/merge_requests/${encodedMergeRequestIid}/raw_diffs`,
      action: "merge-request-diff",
    });
    const contentLength = Number(rawDiffResponse.headers.get("content-length"));
    if (Number.isFinite(contentLength) && contentLength > MAX_PATCH_BYTES) {
      throw buildDiffTooLargeError();
    }

    const patch = await rawDiffResponse.text();
    if (getPatchSizeBytes(patch) > MAX_PATCH_BYTES) {
      throw buildDiffTooLargeError();
    }

    if (patch.trim().length > 0) {
      return { patch, source: "raw_diffs" as const };
    }
  } catch (rawDiffError) {
    if (
      rawDiffError instanceof GitLabRouteError &&
      rawDiffError.status === 413
    ) {
      throw rawDiffError;
    }
  }

  const fallbackPatch = await getMergeRequestPatchFromChanges({
    instanceUrl,
    token,
    encodedProjectId,
    encodedMergeRequestIid,
  });

  return { patch: fallbackPatch, source: "changes" as const };
};

const getCachedMergeRequestPatch = ({
  instanceUrl,
  token,
  projectId,
  mergeRequestIid,
}: {
  instanceUrl: string;
  token: string;
  projectId: string;
  mergeRequestIid: string;
}) => {
  const tokenHash = hashTokenForCache(token);
  return getCachedGitLabValue(
    `patch::${instanceUrl}::${tokenHash}::${projectId}::${mergeRequestIid}`,
    () =>
      getMergeRequestPatch({
        instanceUrl,
        token,
        projectId,
        mergeRequestIid,
      }),
    {
      shouldCacheValue: shouldCachePatchPayload,
    },
  );
};

const resolveTokenForRequest = async ({
  userId,
  instanceUrl,
  requestToken,
  integrationId,
  projectId,
}: {
  userId: string;
  instanceUrl: string;
  requestToken: string | undefined;
  integrationId?: string;
  projectId?: string;
}) => {
  const normalizedRequestToken = requestToken?.trim();
  if (normalizedRequestToken) {
    // Token persistence is best-effort. Read actions should still work even if
    // the optional user-token cache table is unavailable/misaligned.
    await upsertGitLabUserInstanceToken({
      userId,
      instanceUrl,
      token: normalizedRequestToken,
    }).catch(() => null);
    return {
      token: normalizedRequestToken,
      source: "request" as const,
    };
  }

  let storedToken = null as Awaited<
    ReturnType<typeof getGitLabUserInstanceToken>
  >;
  try {
    storedToken = await getGitLabUserInstanceToken(userId, instanceUrl);
  } catch {
    storedToken = null;
  }

  if (!storedToken) {
    const normalizedIntegrationId = integrationId?.trim();
    const normalizedProjectId = projectId?.trim();

    if (normalizedIntegrationId) {
      const integration = await getUserIntegration(
        normalizedIntegrationId,
        userId,
      );
      const matchesScope =
        integration &&
        integration.instanceUrl === instanceUrl &&
        (!normalizedProjectId || integration.projectId === normalizedProjectId);

      if (matchesScope && integration) {
        try {
          const integrationToken = decryptIntegrationToken(integration);
          if (integrationToken.trim()) {
            return {
              token: integrationToken,
              source: "integration" as const,
            };
          }
        } catch {
          // Fall through to token-required error below.
        }
      }
    }

    throw buildRouteError(
      "Personal access token is required. Reconnect your GitLab instance.",
      {
        status: 400,
        code: "GITLAB_TOKEN_REQUIRED",
        reconnectRequired: true,
      },
    );
  }

  if (storedToken.staleAt) {
    throw buildRouteError(
      "Stored GitLab token is stale. Reconnect your GitLab instance.",
      {
        status: 401,
        code: "GITLAB_TOKEN_STALE",
        reconnectRequired: true,
        details: {
          staleAt: storedToken.staleAt.toISOString(),
          staleReason: storedToken.staleReason,
        },
      },
    );
  }

  return {
    token: storedToken.token,
    source: "stored" as const,
  };
};

export async function POST(request: Request) {

return runWithApiRequestLog({
  request,
  path: "/api/gitlab",
  event: "api.gitlab.proxy",
  handler: async ({ logger }) => {
    const [userId, rawPayload] = await Promise.all([
      getSessionUserId(),
      request.json().catch(() => null),
    ]);

    if (!userId) {
      return {
        status: 401,
        outcome: "unauthorized",
        response: NextResponse.json(
          { error: "Unauthorized" },
          { status: 401 },
        ),
      };
    }

    const payload = rawPayload as GitLabProjectPayload | null;

    if (!payload || payload.action === undefined) {
      return {
        status: 400,
        outcome: "invalid_request",
        response: NextResponse.json(
          { error: "Invalid request payload." },
          { status: 400 },
        ),
      };
    }

    if (
      payload.action !== "projects" &&
      payload.action !== "merge-requests" &&
      payload.action !== "merge-request-diff" &&
      payload.action !== "validate-token" &&
      payload.action !== "recent-merge-requests"
    ) {
      return {
        status: 400,
        outcome: "invalid_request",
        response: NextResponse.json(
          { error: "Unsupported action." },
          { status: 400 },
        ),
      };
    }

if (!isNonEmptyString(payload.instanceUrl)) {
  return {
    status: 400,
    outcome: "invalid_request",
    response: NextResponse.json(
      { error: "GitLab instance URL is required." },
      { status: 400 },
    ),
  };
}

let normalizedInstanceUrl: string;
try {
  normalizedInstanceUrl = normalizeGitLabInstanceUrl(payload.instanceUrl);
} catch (error) {
  const message =
    error instanceof Error
      ? error.message
      : "GitLab instance URL is invalid.";
  return {
    status: 400,
    outcome: "invalid_request",
    response: NextResponse.json(
      {
        error: message,
        code: "GITLAB_UPSTREAM_ERROR",
      },
      { status: 400 },
    ),
  };
}

try {
  const resolvedToken = await resolveTokenForRequest({
    userId,
    instanceUrl: normalizedInstanceUrl,
    requestToken: payload.token,
    integrationId: payload.integrationId,
    projectId: payload.projectId,
  });

  logger.set({
    action: payload.action,
    instanceUrl: normalizedInstanceUrl,
    tokenSource: resolvedToken.source,
  });

if (payload.action === "validate-token") {
  const currentUserData = await getCachedGitLabJson<
    Record<string, unknown>
  >({
    instanceUrl: normalizedInstanceUrl,
    token: resolvedToken.token,
    action: payload.action,
    apiPath: "/api/v4/user",
  });
  const currentUser = normalizeGitLabUser(currentUserData);

  return {
    status: 200,
    outcome: "success",
    response: NextResponse.json({
      data: {
        id: currentUser.id,
        username: currentUser.username,
        name: currentUser.name,
      },
    }),
  };
}

if (payload.action === "projects") {
  const perPage = normalizePerPage(
    payload.perPage,
    PROJECTS_PER_PAGE_DEFAULT,
    PROJECTS_PER_PAGE_MAX,
  );
  const normalizedSearch = payload.search?.trim() ?? "";
  const useSearch = normalizedSearch.length >= 3;
  const searchParam = useSearch
    ? `&search=${encodeURIComponent(normalizedSearch)}`
    : "";

  const responseData = await getCachedGitLabJson<
    Array<Record<string, unknown>>
  >({
    instanceUrl: normalizedInstanceUrl,
    token: resolvedToken.token,
    action: payload.action,
    apiPath: `/api/v4/projects?membership=true&per_page=${perPage}&order_by=last_activity_at&sort=desc${searchParam}`,
  });

const projects: Project[] = responseData
  .filter((item) => item && typeof item === "object")
  .map((item) => ({
    id: String(item.id),
    name: String(item.name_with_namespace ?? item.name ?? item.path),
    path: String(item.path_with_namespace ?? item.path),
    webUrl: String(item.web_url ?? ""),
    defaultBranch:
      typeof item.default_branch === "string" &&
      item.default_branch.trim().length > 0
        ? item.default_branch
        : undefined,
  }));

logger.set({
  count: projects.length,
  searchApplied: useSearch,
});
return {
  status: 200,
  outcome: "success",
  response: NextResponse.json({ data: projects }),
};

}

if (payload.action === "recent-merge-requests") {
  const perPage = normalizePerPage(
    payload.perPage,
    MERGE_REQUESTS_PER_PAGE_DEFAULT,
    MERGE_REQUESTS_PER_PAGE_MAX,
  );
  const [responseData, currentUserData] = await Promise.all([
    getCachedGitLabJson<Array<Record<string, unknown>>>({
      instanceUrl: normalizedInstanceUrl,
      token: resolvedToken.token,
      action: payload.action,
      apiPath: `/api/v4/merge_requests?scope=all&state=opened&per_page=${perPage}&order_by=updated_at&sort=desc`,
    }),
    getCachedGitLabJson<Record<string, unknown>>({
      instanceUrl: normalizedInstanceUrl,
      token: resolvedToken.token,
      action: payload.action,
      apiPath: "/api/v4/user",
    }).catch(() => ({})),
  ]);

  const currentUser = normalizeGitLabUser(currentUserData);
  const mergeRequests: MergeRequest[] = responseData
    .filter((item) => item && typeof item === "object")
    .map((item) => mapMergeRequest(item, currentUser));

  logger.set({ count: mergeRequests.length });
  return {
    status: 200,
    outcome: "success",
    response: NextResponse.json({ data: mergeRequests }),
