}

if (!isNonEmptyString(payload.mergeRequestIid)) {
  return {
    status: 400,
    outcome: "invalid_request",
    response: NextResponse.json(
      { error: "Merge request selection is required." },
      { status: 400 },
    ),
  };
}

if (payload.streamDiff === true) {
  const streamResponse = await getMergeRequestPatchStreamResponse({
    instanceUrl: normalizedInstanceUrl,
    token: resolvedToken.token,
    projectId: payload.projectId,
    mergeRequestIid: payload.mergeRequestIid,
  });

  logger.set({
    projectId: payload.projectId,
    mergeRequestIid: payload.mergeRequestIid,
    source: streamResponse.headers.get("x-diff-source") ?? "raw_diffs",
    streamDiff: true,
  });

  return {
    status: 200,
    outcome: "success",
    response: streamResponse,
  };
}

const mergeRequestDiff = await getCachedMergeRequestPatch({
  instanceUrl: normalizedInstanceUrl,
  token: resolvedToken.token,
  projectId: payload.projectId,
  mergeRequestIid: payload.mergeRequestIid,
});

logger.set({
  projectId: payload.projectId,
  mergeRequestIid: payload.mergeRequestIid,
  source: mergeRequestDiff.source,
  patchLength: mergeRequestDiff.patch.length,
});

        return {
          status: 200,
          outcome: "success",
          response: NextResponse.json({ data: mergeRequestDiff }),
        };
      } catch (error) {
        const routeError =
          error instanceof GitLabRouteError
            ? error
            : buildRouteError(
                error instanceof Error
                  ? error.message
                  : "Unexpected GitLab lookup error.",
                {
                  status: 502,
                  code: "GITLAB_UPSTREAM_ERROR",
                },
              );

        if (TOKEN_STALE_CODES.has(routeError.code)) {
          await markGitLabUserInstanceTokenStale({
            userId,
            instanceUrl: normalizedInstanceUrl,
            reason: routeError.code,
          }).catch(() => null);
        }

        logger.set({
          errorCode: routeError.code,
          retryable: routeError.retryable,
          reconnectRequired: routeError.reconnectRequired,
        });

        return {
          status: routeError.status,
          outcome: "upstream_error",
          response: NextResponse.json(
            {
              error: routeError.message,
              code: routeError.code,
              retryable: routeError.retryable,
              reconnectRequired: routeError.reconnectRequired,
            },
            { status: routeError.status },
          ),
        };
      }
    },
  });
}

