import { eq } from 'drizzle-orm'

import { db } from '@/lib/db'
import {
  indexBranchStates,
  indexRunFileChanges,
  indexRuns,
} from '@/lib/db/schema'
import type { ArtifactStore, GitLabSource, IngestJob, VectorStore } from '@/lib/indexing/contracts'
import {
  DeltaSnapshotFallbackError,
  runDeltaIngest,
} from '@/lib/indexing/delta'
import {
  finalizeIndexRun,
  markIndexRunFailed,
} from '@/lib/indexing/finalize'
import { runSnapshotIngest } from '@/lib/indexing/snapshot'
import { createArtifactStore } from '@/lib/indexing/stores/artifact-store'
import { createPostgresVectorStore } from '@/lib/indexing/stores/vector-store.pg'
import { createGitLabSource } from '@/lib/indexing/sources/gitlab-source'
import type { IngestResult } from '@/lib/indexing/types'

type IngestProcessorDeps = {
  source: GitLabSource
  vectorStore: VectorStore
  artifactStore: ArtifactStore
}

const asRecord = (value: unknown): Record<string, unknown> | null => {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    return null
  }

  return value as Record<string, unknown>
}

const defaultDeps = (): IngestProcessorDeps => ({
  source: createGitLabSource(),
  vectorStore: createPostgresVectorStore(),
  artifactStore: createArtifactStore(),
})

const getErrorDetails = (error: unknown): Record<string, unknown> | null => {
  if (!(error instanceof Error)) {
    return null
  }

  return asRecord((error as Error & { details?: unknown }).details)
}

const toErrorPayload = (error: unknown) => {
  const details = getErrorDetails(error)
  if (error instanceof Error) {
    return {
      code: 'INGEST_FAILED',
      message: error.message.slice(0, 500),
      stack: error.stack?.slice(0, 1000) ?? null,
      details,
    }
  }

  return {
    code: 'INGEST_FAILED',
    message: 'Unexpected ingest failure.',
    stack: null,
    details,
  }
}

const cleanupStaleVectorsForRun = async (args: {
  runId: string
  branchStateId: string
  vectorStore: VectorStore
}) => {
  const stagedChanges = await db
    .select({
      path: indexRunFileChanges.path,
      changeType: indexRunFileChanges.changeType,
      fileId: indexRunFileChanges.fileId,
    })
    .from(indexRunFileChanges)
    .where(eq(indexRunFileChanges.runId, args.runId))

  for (const change of stagedChanges) {
    await args.vectorStore.deleteStaleByPath({
      branchStateId: args.branchStateId,
      path: change.path,
      keepFileId: change.changeType === 'upsert' ? change.fileId : null,
    })
  }
}

export const processIngestJob = async (
  job: IngestJob,
  deps: IngestProcessorDeps = defaultDeps(),
): Promise<IngestResult> => {

try {
  let ingestStats: Record<string, number>

  const runContext = {
    runId: run.id,
    branchStateId: run.branchStateId,
    integrationId: run.integrationId,
    configHash: run.configHash,
    baseSha: run.baseSha,
    headSha: run.headSha,
    artifactsPrefix: run.artifactsPrefix,
  }

  if (run.mode === 'delta') {
    try {
      const delta = await runDeltaIngest({
        run: runContext,
        source: deps.source,
        vectorStore: deps.vectorStore,
        artifactStore: deps.artifactStore,
      })
      ingestStats = delta.stats
    } catch (error) {
      if (!(error instanceof DeltaSnapshotFallbackError)) {
        throw error
      }

      const snapshot = await runSnapshotIngest({
        run: runContext,
        source: deps.source,
        vectorStore: deps.vectorStore,
        artifactStore: deps.artifactStore,
      })

      ingestStats = snapshot.stats
      modeFallback = 'snapshot'
      modeFallbackReason = error.reason
    }
  } else {
    const snapshot = await runSnapshotIngest({
      run: runContext,
      source: deps.source,
      vectorStore: deps.vectorStore,
      artifactStore: deps.artifactStore,
    })

    ingestStats = snapshot.stats
  }

  const stats = {
    ...ingestStats,
    ingestMode: run.mode,
    modeFallback,
    modeFallbackReason,
  }

  await db
    .update(indexRuns)
    .set({
      stats,
      updatedAt: new Date(),
    })
    .where(eq(indexRuns.id, run.id))
} catch (error) {

  if (finalized.status === 'ready') {
    gcStatus = 'succeeded'
    try {
      await cleanupStaleVectorsForRun({
        runId: run.id,
        branchStateId: run.branchStateId,
        vectorStore: deps.vectorStore,
      })
    } catch (error) {
      gcStatus = 'failed'
      errorCode = 'VECTOR_GC_FAILED'
      errorMessage = error instanceof Error ? error.message.slice(0, 500) : 'Vector cleanup failed.'
      await db
        .update(indexRuns)
        .set({
          error: {
            code: 'VECTOR_GC_FAILED',
            message: errorMessage,
          },
          updatedAt: new Date(),
        })
        .where(eq(indexRuns.id, run.id))
    }
  } else {
    gcStatus = 'skipped'
  }

  return {
    runId: run.id,
    status: finalized.status,
    ingestMode: run.mode,
    modeFallback,
    modeFallbackReason,
    finalizeStatus: finalized.status,
    gcStatus,
    errorCode,
    errorMessage,
    errorDetails: null,
  }
}

import { NextResponse } from "next/server"

import { disconnectGitLabIntegration, getUserIntegration } from "@/lib/gitlab/service"
import { getSessionUserId } from "@/lib/session"
import { runWithApiRequestLog } from "@/lib/utils/logger"

export async function POST(
  request: Request,
  context: { params: Promise<{ integrationId: string }> },
) {
  const { integrationId } = await context.params
  return runWithApiRequestLog({
    request,
    path: `/api/gitlab/integrations/${integrationId}/disconnect`,
    event: "api.gitlab.integrations.disconnect",
    context: { integrationId },
    handler: async ({ logger }) => {
      const userId = await getSessionUserId()
      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      const integration = await getUserIntegration(integrationId, userId)
      if (!integration) {
        return {
          status: 404,
          outcome: "not_found",
          response: NextResponse.json({ error: "Integration not found." }, { status: 404 }),
        }
      }

      const result = await disconnectGitLabIntegration({
        integration,
        userId,
      })
      logger.set({
        scope: result.scope,
      })
      return {
        status: 200,
        outcome: "success",
        response: NextResponse.json({
          data: {
            scope: result.scope,
          },
          warning: result.warning,
        }),
      }
    },
  })
}

import { describe, expect, test } from "bun:test"

import {
  resolveDescriptionRequestInput,
  resolveServerApiUrl,
  type ReviewDescriptionRequestPayload,
} from "./route"

const withEnv = async <T>(
  overrides: Partial<NodeJS.ProcessEnv>,
  fn: () => Promise<T> | T,
) => {
  const previous = new Map<string, string | undefined>()
  for (const [key, value] of Object.entries(overrides)) {
    previous.set(key, process.env[key])
    if (value === undefined) {
      delete process.env[key]
    } else {
      process.env[key] = value
    }
  }

  try {
    return await fn()
  } finally {
    for (const [key, value] of previous.entries()) {
      if (value === undefined) {
        delete process.env[key]
      } else {
        process.env[key] = value
      }
    }
  }
}

describe("review description provider config", () => {
  test("normalizes server API URL", async () =>
    withEnv(
      {
        AI_API_URL: "https://api.openai.com/v1/?x=1#frag",
        OPENAI_BASE_URL: undefined,
      },
      () => {
        expect(resolveServerApiUrl()).toBe("https://api.openai.com/v1")
      },
    ))

test("rejects invalid provider URLs", async () => {
  await withEnv(
    {
      AI_API_URL: "file:///tmp/provider",
      OPENAI_BASE_URL: undefined,
    },
    () => {
      expect(() => resolveServerApiUrl()).toThrow("AI provider URL must use http or https.")
    },
  )

  await withEnv(
    {
      AI_API_URL: "https://user:pass@example.com/v1",
      OPENAI_BASE_URL: undefined,
    },
    () => {
      expect(() => resolveServerApiUrl()).toThrow(
        "AI provider URL must not include credentials.",
      )
    },
  )
})

test("ignores client provider overrides in payload", async () =>
  withEnv(
    {
      AI_API_URL: "https://api.openai.com/v1",
      AI_MODEL: "gpt-4o-mini",
      AI_API_TOKEN: "server-secret-token",
      OPENAI_BASE_URL: undefined,
      OPENAI_MODEL: undefined,
      OPENAI_API_KEY: undefined,
    },
    () => {
      const payload = {
        patch: "diff --git a/x b/x",
        apiUrl: "https://attacker.example",
        model: "malicious-model",
      } as unknown as ReviewDescriptionRequestPayload

      const resolved = resolveDescriptionRequestInput(payload)
      expect(resolved.patch).toBe("diff --git a/x b/x")
      expect(resolved.apiUrl).toBe("https://api.openai.com/v1")
      expect(resolved.model).toBe("gpt-4o-mini")
      expect(resolved.token).toBe("server-secret-token")
      expect(resolved.stream).toBe(false)
    },
  ))

  test("accepts stream flag from payload", async () =>
    withEnv(
      {
        AI_API_URL: "https://api.openai.com/v1",
        AI_MODEL: "gpt-4o-mini",
        AI_API_TOKEN: "server-secret-token",
        OPENAI_BASE_URL: undefined,
        OPENAI_MODEL: undefined,
        OPENAI_API_KEY: undefined,
      },
      () => {
        const resolved = resolveDescriptionRequestInput({
          patch: "diff --git a/x b/x",
          stream: true,
        })

        expect(resolved.stream).toBe(true)
      },
    ))
})

"use client";

import {
