/* ------------------------------------------------------------------ */
/*  Types                                                              */
/* ------------------------------------------------------------------ */

type GraphNode = {
	id: string;
	kind: string;
	name: string | null;
	filePath: string | null;
};

type GraphEdge = {
	sourceId: string;
	targetId: string;
	type: string;
};

type GraphPayload = {
	indexRunId: string;
	generatedAt: string;
	totalNodes: number;
	totalEdges: number;
	availableEdgeTypes: string[];
	appliedEdgeTypes: string[];
	nodes: GraphNode[];
	edges: GraphEdge[];
};

type ConnectedEntity = {
	node: GraphNode;
	edgeType: string;
	isOutgoing: boolean;
};

/* ------------------------------------------------------------------ */
/*  Constants                                                          */
/* ------------------------------------------------------------------ */

const EDGE_COLORS = [
	"#2563eb",
	"#16a34a",
	"#ea580c",
	"#dc2626",
	"#0891b2",
	"#7c3aed",
	"#c2410c",
];
const EMPTY_NODES: GraphNode[] = [];
