	},
	light: {
		file: "#0f766e",
		function: "#1d4ed8",
		class: "#6d28d9",
		external: "#6b7280",
		default: "#374151",
	},
} as const;

const nodeColor = (kind: string, isDark: boolean) => {
	const palette = isDark ? NODE_COLORS.dark : NODE_COLORS.light;
	if (kind === "file") return palette.file;
	if (kind === "function") return palette.function;
	if (kind === "class" || kind === "type") return palette.class;
	if (kind === "external") return palette.external;
	return palette.default;
};

const packageKeyFromNode = (node: GraphNode) => {
	if (!node.filePath) {
		return node.kind === "external" ? "external" : "workspace";
	}
	const parts = node.filePath.split("/").filter((p) => p.length > 0);
	if (parts.length === 0) return "workspace";
	return parts.slice(0, Math.min(2, parts.length)).join("/");
};

const sampleArray = <T,>(items: T[], limit: number): T[] => {
	if (limit <= 0 || items.length <= limit) {
		return items;
	}

	const out: T[] = [];
	for (let offset = 0; offset < limit; offset += 1) {
		const index = Math.floor((offset * items.length) / limit);
		const item = items[index];
		if (item) {
			out.push(item);
		}
	}
	return out;
};

const resolveGraphRequestLimits = () => {
	if (typeof navigator === "undefined") {
		return { maxNodes: 2_000, maxEdges: 10_000 };
	}

	const browserNavigator = navigator as Navigator & { deviceMemory?: number };
	const cores = navigator.hardwareConcurrency || 8;
	const deviceMemory = browserNavigator.deviceMemory ?? 8;

	if (cores <= 4 || deviceMemory <= 4) {
		return { maxNodes: 900, maxEdges: 2_500 };
	}
	if (cores <= 8 || deviceMemory <= 8) {
		return { maxNodes: 1_200, maxEdges: 4_000 };
	}
	return { maxNodes: 1_600, maxEdges: 6_000 };
};

const normalizeGraphPayload = (payload: GraphPayload): GraphPayload => {
	const nodeIds = new Set(payload.nodes.map((node) => node.id));
	const edges = payload.edges.filter(
		(edge) => nodeIds.has(edge.sourceId) && nodeIds.has(edge.targetId),
	);

	if (edges.length === payload.edges.length) {
		return payload;
	}

	return {
		...payload,
		edges,
	};
};

const pickRenderableEdges = (
	edges: GraphEdge[],
	budget: number,
	selectedNodeId: string | null,
) => {
	if (budget <= 0 || edges.length <= budget) {
		return edges;
	}

	const picked = new Set<number>();
	const out: GraphEdge[] = [];

	// Keep local neighborhood edges first so selected-node exploration stays useful.
	if (selectedNodeId) {
		for (let index = 0; index < edges.length && out.length < budget; index += 1) {
			const edge = edges[index];
			if (!edge) continue;
			if (edge.sourceId === selectedNodeId || edge.targetId === selectedNodeId) {
				picked.add(index);
				out.push(edge);
			}
		}
	}

	const remaining = budget - out.length;
	if (remaining <= 0) {
		return out;
	}

	for (let offset = 0; offset < remaining; offset += 1) {
		const sampleIndex = Math.floor((offset * edges.length) / remaining);
		const edge = edges[sampleIndex];
		if (!edge || picked.has(sampleIndex)) {
			continue;
		}
		picked.add(sampleIndex);
		out.push(edge);
		if (out.length >= budget) {
			return out;
		}
	}

	for (let index = 0; index < edges.length && out.length < budget; index += 1) {
		if (picked.has(index)) {
			continue;
		}
		const edge = edges[index];
		if (!edge) continue;
		picked.add(index);
		out.push(edge);
	}

	return out;
};

/* ------------------------------------------------------------------ */
/*  Component                                                          */
/* ------------------------------------------------------------------ */

export function CodeGraphVisualizationPanel() {
	/* ---- theme ---- */
	const { resolvedTheme } = useTheme();

const isDark = resolvedTheme === "dark" || resolvedTheme === "argus-dark";
const reagraphTheme = useMemo(() => buildReagraphTheme(isDark), [isDark]);

/* ---- core state ---- */
const [graph, setGraph] = useState<GraphPayload | null>(null);
const [selectedNodeId, setSelectedNodeId] = useState<string | null>(null);
const [searchText, setSearchText] = useState("");
const [isLoading, setIsLoading] = useState(false);
const [errorMessage, setErrorMessage] = useState<string | null>(null);

/* ---- refs ---- */
const graphRef = useRef<GraphCanvasRef | null>(null);
const searchInputRef = useRef<HTMLInputElement | null>(null);
const graphRequestLimits = useMemo(() => resolveGraphRequestLimits(), []);

const allNodes = graph?.nodes ?? EMPTY_NODES;
const allEdges = graph?.edges ?? EMPTY_EDGES;
const deferredSearchText = useDeferredValue(searchText);

/* ---- derived ---- */
const nodeById = useMemo(() => {
	const out = new Map<string, GraphNode>();
	for (const node of allNodes) {
		out.set(node.id, node);
	}
	return out;
}, [allNodes]);

const nodeIdSet = useMemo(() => {
	const out = new Set<string>();
	for (const node of allNodes) {
		out.add(node.id);
	}
	return out;
}, [allNodes]);

const selectedNode = useMemo(
	() => (selectedNodeId ? (nodeById.get(selectedNodeId) ?? null) : null),
	[nodeById, selectedNodeId],
);

const connectedByNodeId = useMemo(() => {
	const out = new Map<string, ConnectedEntity[]>();

	const push = (id: string, entity: ConnectedEntity) => {
		const bucket = out.get(id);
		if (bucket) {
			if (bucket.length < MAX_CONNECTED_ENTITIES) {
				bucket.push(entity);
			}
			return;
		}
		out.set(id, [entity]);
	};

	for (const edge of allEdges) {
		const sourceNode = nodeById.get(edge.sourceId);
		const targetNode = nodeById.get(edge.targetId);

		if (targetNode) {
			push(edge.sourceId, {
				node: targetNode,
				edgeType: edge.type,
				isOutgoing: true,
			});
		}
		if (sourceNode) {
			push(edge.targetId, {
				node: sourceNode,
				edgeType: edge.type,
				isOutgoing: false,
			});
		}
	}

	return out;
}, [allEdges, nodeById]);

const connectedEntities = useMemo(() => {
	if (!selectedNodeId) {
		return EMPTY_CONNECTED_ENTITIES;
	}
	return connectedByNodeId.get(selectedNodeId) ?? EMPTY_CONNECTED_ENTITIES;
}, [connectedByNodeId, selectedNodeId]);

const activeNodeIds = useMemo(() => {
	if (!selectedNodeId) return EMPTY_IDS;
	const ids = new Set<string>([selectedNodeId]);
	for (const entity of connectedEntities) {
		ids.add(entity.node.id);
	}
	return [...ids];
}, [connectedEntities, selectedNodeId]);

const selectedNodeIds = useMemo(
	() => (selectedNodeId ? [selectedNodeId] : EMPTY_IDS),
	[selectedNodeId],
);

const isDenseGraph = allNodes.length > 900 || allEdges.length > 3_200;
const denseOverviewNodes = useMemo(
	() => sampleArray(allNodes, DENSE_OVERVIEW_NODE_LIMIT),
	[allNodes],
);

const renderedNodeIdSet = useMemo(() => {
	if (!isDenseGraph) {
		return nodeIdSet;
	}

	const out = new Set<string>();
	if (selectedNodeId) {
		out.add(selectedNodeId);
		for (const entity of connectedEntities) {
			if (out.size >= DENSE_FOCUS_NODE_LIMIT) {
				break;
			}
			out.add(entity.node.id);
		}
	}

	for (const node of denseOverviewNodes) {
		if (out.size >= DENSE_FOCUS_NODE_LIMIT && selectedNodeId) {
			break;
		}
		out.add(node.id);
		if (!selectedNodeId && out.size >= DENSE_OVERVIEW_NODE_LIMIT) {
			break;
		}
	}
	return out;
}, [connectedEntities, denseOverviewNodes, isDenseGraph, nodeIdSet, selectedNodeId]);

const visibleNodes = useMemo(() => {
	if (!isDenseGraph) {
		return allNodes;
	}
	return allNodes.filter((node) => renderedNodeIdSet.has(node.id));
}, [allNodes, isDenseGraph, renderedNodeIdSet]);

const graphLayoutType: GraphLayoutType = isDenseGraph
	? "nooverlap"
	: "forceDirected2d";
const graphLabelType: GraphLabelType = isDenseGraph
	? "none"
	: allEdges.length > 2_200
		? "nodes"
		: "auto";
const showNodeLabels = graphLabelType !== "none";
const showEdgeLabels = graphLabelType === "auto";
const graphClusterAttribute = isDenseGraph ? undefined : "package";
const graphAnimated = !isDenseGraph;
const graphDraggable = !isDenseGraph;
const graphLayoutOverrides = useMemo<LayoutOverrides | undefined>(() => {
	if (!isDenseGraph) {
		return undefined;
	}
	return {
		maxIterations: 12,
		margin: 2,
		ratio: 1.1,
	};
}, [isDenseGraph]);

const degreeByNodeId = useMemo(() => {
	const degree = new Map<string, number>();
	for (const edge of allEdges) {
		degree.set(edge.sourceId, (degree.get(edge.sourceId) ?? 0) + 1);
		degree.set(edge.targetId, (degree.get(edge.targetId) ?? 0) + 1);
	}
	return degree;
}, [allEdges]);

const edgeColorMap = useMemo(() => {
	const types = graph?.availableEdgeTypes?.length
		? graph.availableEdgeTypes
		: [...new Set(allEdges.map((e) => e.type))];
	const map = new Map<string, string>();
	types.forEach((type, i) => {
		map.set(type, EDGE_COLORS[i % EDGE_COLORS.length] as string);
	});
	return map;
}, [allEdges, graph?.availableEdgeTypes]);

const edgeBudget = isDenseGraph
	? selectedNodeId
		? DENSE_FOCUS_EDGE_LIMIT
		: DENSE_OVERVIEW_EDGE_LIMIT
	: allEdges.length;
const candidateVisibleEdges = useMemo(() => {
	if (!isDenseGraph) {
		return allEdges;
	}

	const out: GraphEdge[] = [];
	for (const edge of allEdges) {
		if (
			renderedNodeIdSet.has(edge.sourceId) &&
			renderedNodeIdSet.has(edge.targetId)
		) {
			out.push(edge);
		}
	}
	return out;
}, [allEdges, isDenseGraph, renderedNodeIdSet]);
const renderEdges = useMemo(
	() => pickRenderableEdges(candidateVisibleEdges, edgeBudget, selectedNodeId),
	[candidateVisibleEdges, edgeBudget, selectedNodeId],
);

const reagraphNodes = useMemo(() => {
	return visibleNodes.map((node) => {
		const degree = degreeByNodeId.get(node.id) ?? 0;
		return {
			id: node.id,
			label: showNodeLabels ? (node.name ?? shortId(node.id)) : undefined,
			fill: nodeColor(node.kind, isDark),
			size: Math.max(5, Math.min(12, 5 + degree * 0.25)),
			data: {
				kind: node.kind,
				filePath: node.filePath,
				package: packageKeyFromNode(node),
			},
		};
	});
}, [degreeByNodeId, isDark, showNodeLabels, visibleNodes]);

const reagraphEdges = useMemo(() => {
	const out: Array<{
		id: string;
		source: string;
		target: string;
		label?: string;
		fill: string;
		data: { type: string };
	}> = [];

	let index = 0;
	for (const edge of renderEdges) {
		out.push({
			id: `${edge.sourceId}-${edge.targetId}-${edge.type}-${index}`,
			source: edge.sourceId,
			target: edge.targetId,
			label: showEdgeLabels ? edge.type : undefined,
			fill: edgeColorMap.get(edge.type) ?? "#94a3b8",
			data: {
				type: edge.type,
			},
		});
		index += 1;
	}
	return out;
}, [edgeColorMap, renderEdges, showEdgeLabels]);

const graphSelectionIds = selectedNodeIds;
const graphActiveIds = isDenseGraph ? EMPTY_IDS : activeNodeIds;

const searchableNodes = useMemo(
	() =>
		allNodes.map((node) => ({
			node,
			searchValue: `${node.name ?? ""} ${node.id} ${node.filePath ?? ""}`
				.toLowerCase()
				.trim(),
		})),
	[allNodes],
);

const searchResults = useMemo(() => {
	const term = deferredSearchText.trim().toLowerCase();
	if (!term) return EMPTY_NODES;

	const out: GraphNode[] = [];
	for (const entry of searchableNodes) {
		if (entry.searchValue.includes(term)) {
			out.push(entry.node);
		}
		if (out.length >= MAX_SEARCH_RESULTS) {
			break;
		}
	}
	return out;
}, [deferredSearchText, searchableNodes]);

const findFirstSearchMatch = useCallback(
	(rawTerm: string) => {
		const term = rawTerm.trim().toLowerCase();
		if (!term) {
			return null;
		}

		for (const entry of searchableNodes) {
			if (entry.searchValue.includes(term)) {
				return entry.node;
			}
		}
		return null;
	},
	[searchableNodes],
);

/* ---- data fetching ---- */

const runVisualization = useCallback(async () => {
	setIsLoading(true);
	setErrorMessage(null);

	try {
		const response = await fetch("/api/code/graph/visualization", {
			method: "POST",
			headers: { "content-type": "application/json" },
			body: JSON.stringify(graphRequestLimits),
		});

		const parsed = (await response.json().catch(() => ({}))) as {
			data?: GraphPayload;
			error?: string;
		};
		if (!response.ok || !parsed.data) {
			throw new Error(parsed.error ?? "Failed to load graph.");
		}

		const normalizedGraph = normalizeGraphPayload(parsed.data);
		startTransition(() => {
			setGraph(normalizedGraph);
			const firstNodeId = normalizedGraph.nodes[0]?.id ?? null;
			setSelectedNodeId((prev) => prev ?? firstNodeId);
		});
	} catch (error) {
		setErrorMessage(
			error instanceof Error ? error.message : "Failed to load graph.",
		);
	} finally {
		setIsLoading(false);
	}
}, [graphRequestLimits]);

/* ---- node interaction ---- */
const focusNode = useCallback((nodeId: string | null) => {
	if (!nodeId || !graphRef.current) return;
	graphRef.current.centerGraph([nodeId]);
}, []);

const selectNode = useCallback(
	(nodeId: string, focus = false) => {
		setSelectedNodeId(nodeId);
		if (focus) focusNode(nodeId);
	},
	[focusNode],
);

const handleGraphNodeClick = useCallback((nodeId: string) => {
	setSelectedNodeId(nodeId);
}, []);

const handleGraphCanvasClick = useCallback(() => {
	setSelectedNodeId(null);
}, []);

/* ---- keyboard shortcut: / to focus search ---- */

useEffect(() => {
	const handler = (event: KeyboardEvent) => {
		if (event.key === "/" && document.activeElement?.tagName !== "INPUT") {
			event.preventDefault();
			searchInputRef.current?.focus();
		}
		if (event.key === "Escape") {
			setSearchText("");
			searchInputRef.current?.blur();
		}
	};
	window.addEventListener("keydown", handler);
	return () => window.removeEventListener("keydown", handler);
}, []);

/* ---- load on mount ---- */
useEffect(() => {
	void runVisualization();
}, [runVisualization]);

/* ---- keep selection in sync with loaded graph ---- */
useEffect(() => {
	if (!graph) return;
	if (!selectedNodeId) {
		const first = graph.nodes[0]?.id ?? null;
		setSelectedNodeId(first);
		return;
	}
	if (!nodeIdSet.has(selectedNodeId)) {
		setSelectedNodeId(graph.nodes[0]?.id ?? null);
	}
}, [graph, nodeIdSet, selectedNodeId]);

/* ---- search form submit ---- */
const handleSearchSubmit = (event: FormEvent) => {
	event.preventDefault();
	const first = findFirstSearchMatch(searchText);
	if (first) {
		selectNode(first.id, true);
		setSearchText("");
	}
};

const inspectorOpen = !!selectedNode;

return (
	<div className="relative flex min-h-0 flex-1 flex-col overflow-hidden rounded-lg border border-border/60 bg-background">
		{/* ============ FLOATING SEARCH (top-left) ============ */}

{graph && (
	<div
		className={cn(
			"absolute top-3 z-20 flex items-center gap-2",
			inspectorOpen ? "right-[21rem]" : "right-3",
		)}
	>
		<span className="rounded-md bg-background/90 px-2.5 py-1 text-xs text-muted-foreground shadow backdrop-blur-sm">
			{reagraphNodes.length.toLocaleString()} /{" "}
			{graph.nodes.length.toLocaleString()} /{" "}
			{graph.totalNodes.toLocaleString()} nodes &middot;{" "}
			{reagraphEdges.length.toLocaleString()} /{" "}
			{graph.edges.length.toLocaleString()} /{" "}
			{graph.totalEdges.toLocaleString()} edges
			{isDenseGraph
				? selectedNodeId
					? " · focus mode"
					: " · overview mode"
				: ""}
		</span>
	</div>
)}

{/* ============ ZOOM CONTROLS (bottom-left) ============ */}

						{edgeColorMap.size > 0 && (
							<div className="border-t border-border/40 p-4">
								<p className="mb-2 text-[10px] font-medium uppercase tracking-wider text-muted-foreground">
									Edge types
								</p>
								<div className="flex flex-wrap gap-x-3 gap-y-1">
									{[...edgeColorMap.entries()].map(([type, color]) => (
										<span
											key={type}
											className="flex items-center gap-1.5 text-[10px] text-muted-foreground"
										>
											<span
												className="inline-block size-2 rounded-full"
												style={{ backgroundColor: color }}
											/>
											{type}
										</span>
									))}
								</div>
							</div>
						)}
					</div>
				)}
			</div>
		</div>
	);
}

export function useMergeRequestDiffModel({
