import { and, asc, eq } from "drizzle-orm";

import { db } from "@/lib/db";
import {
  onboardingEvents,
  type OnboardingEventMetadata,
} from "@/lib/db/schema";

const ONBOARDING_STARTED_EVENT = "onboarding_started";
const ONBOARDING_COMPLETED_EVENT = "onboarding_completed";

const getFirstEventAt = async (
  userId: string,
  event: typeof ONBOARDING_STARTED_EVENT | typeof ONBOARDING_COMPLETED_EVENT,
) => {
  const rows = await db
    .select({ createdAt: onboardingEvents.createdAt })
    .from(onboardingEvents)
    .where(
      and(
        eq(onboardingEvents.userId, userId),
        eq(onboardingEvents.event, event),
      ),
    )
    .orderBy(asc(onboardingEvents.createdAt))
    .limit(1);

  return rows[0]?.createdAt ?? null;
};

export const isOnboardingCompleted = async (userId: string) => {
  const completedAt = await getFirstEventAt(userId, ONBOARDING_COMPLETED_EVENT);
  return completedAt !== null;
};

export const recordOnboardingCompletedIfMissing = async ({
  userId,
  metadata,
}: {
  userId: string;
  metadata?: OnboardingEventMetadata;
}) => {
  const existingCompletedAt = await getFirstEventAt(
    userId,
    ONBOARDING_COMPLETED_EVENT,
  );
  if (existingCompletedAt) {
    return {
      alreadyCompleted: true,
      onboardingDurationMs: metadata?.onboardingDurationMs ?? null,
      onboardingCompletedAt: existingCompletedAt,
    };
  }

  const startedAt = await getFirstEventAt(userId, ONBOARDING_STARTED_EVENT);
  const completedAt = new Date();
  const onboardingDurationMs = startedAt
    ? Math.max(0, completedAt.getTime() - startedAt.getTime())
    : null;

  const completionMetadata: OnboardingEventMetadata = {
    ...metadata,
    onboardingStartedAt: startedAt?.toISOString(),
    onboardingCompletedAt: completedAt.toISOString(),
    onboardingDurationMs: onboardingDurationMs ?? undefined,
  };

  await db.insert(onboardingEvents).values({
    userId,
    event: ONBOARDING_COMPLETED_EVENT,
    createdAt: completedAt,
    metadata: completionMetadata,
  });

  return {
    alreadyCompleted: false,
    onboardingDurationMs,
    onboardingCompletedAt: completedAt,
  };
};

