  active: "Active",
  degraded: "Degraded",
  disabled: "Disabled",
}

const integrationStatusVariant: Record<"active" | "degraded" | "disabled", "default" | "secondary" | "outline"> = {
  active: "default",
  degraded: "secondary",
  disabled: "outline",
}

export default async function MergeRequestReviewPage({
  params,
}: MergeRequestReviewPageProps) {
  const session = await auth.api.getSession({
    headers: await headers(),
  })

  if (!session?.user?.id) {
    redirect("/")
  }

  const { integrationId: repoRouteId, mergeRequestIid } = await params
  const integrations = await listUserIntegrations(session.user.id)
  const integration = findIntegrationByRepoRouteId(integrations, repoRouteId)
  if (!integration) {
    notFound()
  }

const canonicalRepoRouteId = buildRepoRouteId(integration)
if (repoRouteId !== canonicalRepoRouteId) {
  redirect(buildRepoMergeRequestPath(integration, mergeRequestIid))
}

