        onboardingCompletionSource,
      })
      return {
        status: 200,
        outcome: "success",
        response: NextResponse.json({
          ok: true,
          data: {
            onboardingDurationMs,
            onboardingAlreadyCompleted,
          },
        }),
      }
    },
  })
}

