const TIMELINE_STEPS: TimelineStep[] = [
  {
    key: "chunking",
    label: "Queue Batches",
    description: "Split changed files into reviewable batches.",
  },
  {
    key: "analyzing",
    label: "Analyze Changes",
    description: "Run AI over each batch of files.",
  },
  {
    key: "mapping",
    label: "Map Findings",
    description: "Attach findings to files and line ranges.",
  },
  {
    key: "done",
    label: "Complete",
    description: "Summarize output and severity counts.",
  },
]

const STAGE_ORDER: ReviewRunStage[] = [
  "idle",
  "chunking",
  "analyzing",
  "mapping",
  "done",
  "failed",
]

/* ─── helpers ─── */

const stageRank = (stage: ReviewRunStage) => STAGE_ORDER.indexOf(stage)

const getStepStatus = ({
  step,
  stage,
  hasError,
}: {
  step: TimelineStep["key"]
  stage: ReviewRunStage
  hasError: boolean
}): StepStatus => {
  if (hasError || stage === "failed") {
    if (step === "analyzing") return "error"
    if (step === "chunking" && stageRank(stage) > stageRank("chunking")) return "complete"
    return "pending"
  }
  if (stage === step) return "current"
  if (step === "done" && stage === "done") return "complete"
  if (stageRank(stage) > stageRank(step)) return "complete"
  return "pending"
}

const stepIcon = (status: StepStatus) => {
  if (status === "error") return <AlertTriangle className="size-3.5" aria-hidden="true" />
  if (status === "complete") return <CheckCircle2 className="size-3.5" aria-hidden="true" />
  if (status === "current") return <LoaderCircle className="size-3.5 animate-spin" aria-hidden="true" />
  return <Circle className="size-3.5" aria-hidden="true" />
}

const stepIconColor = (status: StepStatus) => {
  if (status === "error") return "text-red-500 dark:text-red-400"
  if (status === "complete") return "text-emerald-500 dark:text-emerald-400"
  if (status === "current") return "text-blue-500 dark:text-blue-400"
  return "text-muted-foreground/50"
}

const stepLineColor = (status: StepStatus) => {
  if (status === "complete") return "bg-emerald-500/40 dark:bg-emerald-400/30"
  if (status === "error") return "bg-red-500/40 dark:bg-red-400/30"
  return "bg-border"
}

/** Group events by the step they belong to. */
const eventsByStep = (events: ReviewRunEvent[]) => {
  const map: Record<string, ReviewRunEvent[]> = {}
  for (const event of events) {
    const key = event.stage === "failed" ? "analyzing" : event.stage
    if (!map[key]) map[key] = []
    map[key].push(event)
  }
  return map
}

/** Build a short context string for the currently active step. */

const getStepDetail = (
  step: TimelineStep["key"],
  reviewRun: ReviewRunState,
  reviewError: string,
): string | null => {
  if (step === "chunking" && reviewRun.totalBatches > 0) {
    return `${reviewRun.totalBatches} ${reviewRun.totalBatches === 1 ? "batch" : "batches"} queued`
  }
  if (step === "analyzing") {
    if (reviewRun.stage === "failed" || reviewError) {
      return reviewError || "Review failed"
    }
    if (reviewRun.totalBatches > 0) {
      return `Batch ${Math.min(reviewRun.currentBatchIndex, reviewRun.totalBatches)}/${reviewRun.totalBatches}`
    }
  }
  return null
}

/** Format file list for the analyzing step. */
const formatBatchFiles = (files: string[]) => {
  if (files.length === 0) return null
  if (files.length <= 3) return files.join(", ")
  return `${files.slice(0, 3).join(", ")} +${files.length - 3} more`
}

/* ─── header status helpers ─── */

const headerStatusIcon = (stage: ReviewRunStage, isReviewing: boolean) => {
  if (stage === "failed") return <AlertTriangle className="size-4" aria-hidden="true" />
  if (stage === "done") return <CheckCircle2 className="size-4" aria-hidden="true" />
  if (isReviewing) return <LoaderCircle className="size-4 animate-spin" aria-hidden="true" />
  return <Sparkles className="size-4" aria-hidden="true" />
}

const headerStatusColor = (stage: ReviewRunStage, isReviewing: boolean) => {
  if (stage === "failed") return "text-red-500 dark:text-red-400"
  if (stage === "done") return "text-emerald-500 dark:text-emerald-400"
  if (isReviewing) return "text-blue-500 dark:text-blue-400"
  return "text-muted-foreground"
}

/* ─── component ─── */

export function MergeRequestReviewProcess({
  isReviewing,
  reviewError,
  reviewSummary,
  reviewFindingsCount,
  reviewSeverityCounts,
  reviewRun,
  reviewId,
  reviewFeedback,
  reviewFeedbackError,
  isSubmittingReviewFeedback,
  onSubmitReviewFeedback,
}: MergeRequestReviewProcessProps) {
  const hasStarted = reviewRun.stage !== "idle" || reviewRun.events.length > 0
  const isDone = reviewRun.stage === "done"
  const hasFailed = reviewRun.stage === "failed"
  const hasError = reviewError.trim().length > 0 || hasFailed
  const hasFindings = reviewFindingsCount > 0

  const [isManuallyOpen, setIsManuallyOpen] = useState(false)
  const isOpen = isReviewing || isManuallyOpen

  if (!hasStarted) return null

  const groupedEvents = eventsByStep(reviewRun.events)

  return (
    <Collapsible
      open={isOpen}
      onOpenChange={(open) => {
        if (!isReviewing) {
          setIsManuallyOpen(open)
        }
      }}
    >
      {/* ── collapsed header row ── */}

  {hasFindings ? (
    <div className="ml-auto flex items-center gap-1.5">
      {reviewSeverityCounts.high > 0 ? (
        <Badge
          variant="outline"
          className="border-red-300 bg-red-100/70 text-[10px] font-medium text-red-800 dark:border-red-900/60 dark:bg-red-950/40 dark:text-red-200"
        >
          {reviewSeverityCounts.high} High
        </Badge>
      ) : null}
      {reviewSeverityCounts.med > 0 ? (
        <Badge
          variant="outline"
          className="border-amber-300 bg-amber-100/70 text-[10px] font-medium text-amber-800 dark:border-amber-900/60 dark:bg-amber-950/40 dark:text-amber-200"
        >
          {reviewSeverityCounts.med} Med
        </Badge>
      ) : null}
      {reviewSeverityCounts.low > 0 ? (
        <Badge variant="outline" className="text-[10px] font-medium">
          {reviewSeverityCounts.low} Low
        </Badge>
      ) : null}
    </div>
  ) : isDone && !hasFindings ? (
    <span className="ml-auto text-[11px] text-muted-foreground">No findings</span>
  ) : null}

  <ChevronDown
    className={cn(
      "size-4 shrink-0 text-muted-foreground transition-transform duration-200",
      isOpen && "rotate-180",
      hasFindings ? "" : "ml-auto",
    )}
    aria-hidden="true"
  />
</CollapsibleTrigger>

{/* ── expanded: vertical stepper ── */}
<CollapsibleContent className="mt-1">

          {stepEvents.length > 0 ? (
            <ul className="mt-1.5 space-y-0.5">
              {stepEvents.slice(-4).map((event) => (
                <li
                  key={event.id}
                  className={cn(
                    "text-[10px] leading-4",
                    event.stage === "failed"
                      ? "text-red-600 dark:text-red-400"
                      : "text-muted-foreground/70",
                  )}
                >
                  {event.message}
                </li>
              ))}
            </ul>
          ) : null}
        </div>
      </li>
    )
  })}
</ol>

{/* findings summary row — only when done with findings */}

{isDone && hasFindings ? (
  <div className="mt-3 flex flex-wrap items-center gap-1.5 border-t border-border/50 pt-3">
    <Badge variant="outline" className="text-[10px]">
      {reviewFindingsCount} {reviewFindingsCount === 1 ? "finding" : "findings"}
    </Badge>
    {reviewSeverityCounts.high > 0 ? (
      <Badge
        variant="outline"
        className="border-red-300 bg-red-100/70 text-[10px] text-red-800 dark:border-red-900/60 dark:bg-red-950/40 dark:text-red-200"
      >
        {reviewSeverityCounts.high} High
      </Badge>
    ) : null}
    {reviewSeverityCounts.med > 0 ? (
      <Badge
        variant="outline"
        className="border-amber-300 bg-amber-100/70 text-[10px] text-amber-800 dark:border-amber-900/60 dark:bg-amber-950/40 dark:text-amber-200"
      >
        {reviewSeverityCounts.med} Med
      </Badge>
    ) : null}
    {reviewSeverityCounts.low > 0 ? (
      <Badge variant="outline" className="text-[10px]">
        {reviewSeverityCounts.low} Low
      </Badge>
    ) : null}
  </div>
) : null}

{/* summary text when done */}
{isDone && reviewSummary ? (
  <p className="mt-2 text-[11px] text-muted-foreground">{reviewSummary}</p>
) : null}

          {isDone && reviewId ? (
            <div className="mt-2 flex flex-wrap items-center gap-2">
              <span className="text-[11px] text-muted-foreground">Helpful?</span>
              <Button
                type="button"
                size="sm"
                variant={reviewFeedback === "up" ? "default" : "outline"}
                className="h-7 px-2"
                disabled={isSubmittingReviewFeedback}
                onClick={() =>
                  onSubmitReviewFeedback(reviewFeedback === "up" ? null : "up")
                }
              >
                <ThumbsUp className="size-3.5" />
              </Button>
              <Button
                type="button"
                size="sm"
                variant={reviewFeedback === "down" ? "default" : "outline"}
                className="h-7 px-2"
                disabled={isSubmittingReviewFeedback}
                onClick={() =>
                  onSubmitReviewFeedback(reviewFeedback === "down" ? null : "down")
                }
              >
                <ThumbsDown className="size-3.5" />
              </Button>
              {isSubmittingReviewFeedback ? (
                <span className="text-[11px] text-muted-foreground">Saving...</span>
              ) : null}
              {reviewFeedbackError ? (
                <span className="text-[11px] text-red-600 dark:text-red-400">
                  {reviewFeedbackError}
                </span>
              ) : null}
            </div>
          ) : null}
        </div>
      </CollapsibleContent>
    </Collapsible>
  )
}

"use client"

import type { ReactNode } from "react"
import { useEffect } from "react"
import { usePathname, useRouter, useSearchParams } from "next/navigation"

import { AppShell } from "@/components/app-shell"
import { QueryProvider } from "@/components/query-provider"
import { TooltipProvider } from "@/components/ui/tooltip"
import { isOnboardingPath } from "./layout.utils"

type AppLayoutClientProps = {
  children: ReactNode
  isAuthenticated: boolean
}

export function AppLayoutClient({
  children,
  isAuthenticated,
}: Readonly<AppLayoutClientProps>) {
  const router = useRouter()
  const pathname = usePathname()
  const searchParams = useSearchParams()
  const onboardingShellOnly = isOnboardingPath(pathname)

  useEffect(() => {
    if (isAuthenticated || pathname === "/") {
      return
    }

    const search = searchParams.toString()
    const nextPath = `${pathname}${search ? `?${search}` : ""}`
    router.replace(`/?next=${encodeURIComponent(nextPath)}`)
  }, [isAuthenticated, pathname, router, searchParams])

  if (!isAuthenticated && pathname !== "/") {
    return null
  }

  if (!isAuthenticated) {
    return <QueryProvider>{children}</QueryProvider>
  }

  if (onboardingShellOnly) {
    return (
      <QueryProvider>
        <TooltipProvider>
          <div className="group/sidebar-wrapper has-data-[variant=inset]:bg-sidebar flex min-h-svh w-full [--header-height:calc(var(--spacing)*12)]">
            <main className="bg-background relative flex w-full flex-1 flex-col max-h-svh overflow-hidden md:m-2 md:rounded-xl md:shadow-sm">
              <div className="h-(--header-height) shrink-0" />
              <div className="flex min-h-0 flex-1 flex-col overflow-hidden">
                <div className="@container/main flex min-h-0 flex-1 flex-col gap-2 overflow-hidden">
                  <div className="flex min-h-0 flex-1 flex-col gap-4 overflow-auto px-4 py-4 md:gap-6 md:py-6 lg:px-6">
                    {children}
                  </div>
                </div>
              </div>
            </main>
          </div>
        </TooltipProvider>
      </QueryProvider>
    )
  }

  return (
    <QueryProvider>
      <AppShell>{children}</AppShell>
    </QueryProvider>
  )
}

import {
  useCallback,
  useEffect,
  useRef,
  useState,
  type Dispatch,
  type SetStateAction,
} from "react"

import { getErrorMessage, resolveGitLabInstance } from "@/components/onboarding/onboarding-flow.utils"
import type {
  OnboardingEventMetadata,
  OnboardingTrackedEvent,
  Project,
  WebhookSetupFeedback,
} from "@/components/onboarding/onboarding-types"

type UseOnboardingIntegrationConnectOptions = {
  gitlabInstance: string
  customInstance: string
  token: string
  setWebhookSetupFeedback: Dispatch<SetStateAction<WebhookSetupFeedback | null>>
  trackEvent?: (event: OnboardingTrackedEvent, metadata?: OnboardingEventMetadata) => void
}

type ConnectIntegrationAndEnableIndexingResult = {
  integrationId: string
  warning?: string
  branch?: string
  planJobId?: string
  reconcileJobId?: string
}

type ProjectReviewState = {
  integrationId: string | null
  reviewMode: "quick" | "full"
  indexingStatus: string
}

const INDEXING_POLL_INTERVAL_MS = 4_000

const asRecord = (value: unknown): Record<string, unknown> | null =>
  value && typeof value === "object" ? (value as Record<string, unknown>) : null

const getWarning = (payload: unknown) => {
  const root = asRecord(payload)
  return typeof root?.warning === "string" ? root.warning : ""
}

const getIntegrationId = (payload: unknown) => {
  const root = asRecord(payload)
  const data = asRecord(root?.data)
  return typeof data?.id === "string" && data.id.trim().length > 0 ? data.id : null
}

export const connectIntegrationAndEnableIndexing = async ({

  project,
  normalizedInstance,
  token,
  fetchImpl = fetch,
}: {
  project: Project
  normalizedInstance: string
  token: string
  fetchImpl?: typeof fetch
}): Promise<ConnectIntegrationAndEnableIndexingResult> => {
  const response = await fetchImpl("/api/gitlab/integrations/connect", {
    method: "POST",
    headers: {
      "content-type": "application/json",
    },
    body: JSON.stringify({
      instanceUrl: normalizedInstance,
      ...(token.trim() ? { token: token.trim() } : {}),
      projectId: project.id,
      projectPath: project.path,
      projectName: project.name,
    }),
  })

  const payload = await response.json().catch(() => null)
  if (!response.ok) {
    throw new Error(getErrorMessage(payload))
  }

  const integrationId = getIntegrationId(payload)
  if (!integrationId) {
    throw new Error("Connect response is missing integration id.")
  }

  const warning = getWarning(payload)
  if (warning) {
    return { integrationId, warning }
  }

  const branch = project.defaultBranch?.trim()
  if (!branch) {
    return {
      integrationId,
      warning:
        "Webhook active, but indexing was not queued because no default branch was found.",
    }
  }

  const enableResponse = await fetchImpl(
    `/api/gitlab/integrations/${integrationId}/index/enable`,
    {
      method: "POST",
      headers: {
        "content-type": "application/json",
      },
      body: JSON.stringify({ branch }),
    },
  )
  const enablePayload = await enableResponse.json().catch(() => null)

  if (!enableResponse.ok) {
    return {
      integrationId,
      warning: `Webhook active, but indexing could not be queued. ${getErrorMessage(enablePayload)}`,
    }
  }

  const enableRoot = asRecord(enablePayload)
  const enableData = asRecord(enableRoot?.data)
  const job = asRecord(enableData?.job)
  const reconcileJob = asRecord(enableData?.reconcileJob)
  const resolvedBranch =
    typeof enableData?.branch === "string" && enableData.branch.trim().length > 0
      ? enableData.branch
      : branch

  return {
    integrationId,
    branch: resolvedBranch,
    planJobId: typeof job?.id === "string" ? job.id : undefined,
    reconcileJobId: typeof reconcileJob?.id === "string" ? reconcileJob.id : undefined,
  }
}

const buildIndexingStatusLabel = (indexingStatus: string) => {
  if (indexingStatus === "ready") {
    return "Indexing complete. Full context is ready."
  }
  if (indexingStatus === "failed") {
    return "Indexing failed. Continuing in Quick Review mode."
  }
  if (indexingStatus === "disabled") {
    return "Indexing is disabled for this integration."
  }
  return "Indexing in progress. Quick Review uses MR metadata and diff context first."
}

export function useOnboardingIntegrationConnect({
  gitlabInstance,
  customInstance,
  token,
  setWebhookSetupFeedback,
  trackEvent,
}: UseOnboardingIntegrationConnectOptions) {
  const integrationConnectPromiseByKeyRef = useRef(new Map<string, Promise<string | null>>())
  const [projectReviewStateByProjectId, setProjectReviewStateByProjectId] = useState<
    Record<string, ProjectReviewState>
  >({})

useEffect(() => {
  const quickReviewEntries = Object.entries(projectReviewStateByProjectId).filter(
    ([, state]) => state.integrationId && state.reviewMode === "quick",
  )
  if (quickReviewEntries.length === 0) {
    return
  }

  let cancelled = false

  const pollStatus = async () => {
    await Promise.allSettled(
      quickReviewEntries.map(async ([projectId, state]) => {
        const integrationId = state.integrationId
        if (!integrationId || cancelled) {
          return
        }

        const response = await fetch(
          `/api/gitlab/integrations/${integrationId}/index/runs?page=1&limit=1`,
          {
            method: "GET",
            headers: {
              "content-type": "application/json",
            },
          },
        )

        const payload = await response.json().catch(() => null)
        if (!response.ok || cancelled) {
          return
        }

        const root = asRecord(payload)
        const rows = Array.isArray(root?.data) ? root.data : []
        const topRow = asRecord(rows[0])
        const nextStatus =
          typeof topRow?.status === "string" && topRow.status.trim().length > 0
            ? topRow.status
            : "indexing"

        setProjectReviewStateByProjectId((current) => {
          const prev = current[projectId]
          if (!prev || prev.integrationId !== integrationId) {
            return current
          }

          const nextMode = nextStatus === "ready" ? "full" : "quick"
          if (
            prev.reviewMode === nextMode &&
            prev.indexingStatus === nextStatus
          ) {
            return current
          }

          if (prev.reviewMode === "quick" && nextMode === "full") {
            trackEvent?.("onboarding_full_review_ready", {
              projectId,
              reviewMode: "full",
            })
          }

          return {
            ...current,
            [projectId]: {
              ...prev,
              reviewMode: nextMode,
              indexingStatus: nextStatus,
            },
          }
        })
      }),
    )
  }

  void pollStatus()
  const timer = window.setInterval(() => {
    void pollStatus()
  }, INDEXING_POLL_INTERVAL_MS)

  return () => {
    cancelled = true
    window.clearInterval(timer)
  }
}, [projectReviewStateByProjectId, trackEvent])

const connectIntegration = useCallback(
  async (project: Project) => {
    const normalizedInstance = resolveGitLabInstance(gitlabInstance, customInstance)
    const connectKey = `${normalizedInstance}::${project.id}`
    const pendingConnect = integrationConnectPromiseByKeyRef.current.get(connectKey)
    if (pendingConnect) {
      return pendingConnect
    }

const connectPromise = (async () => {
  setProjectReviewStateByProjectId((current) => ({
    ...current,
    [project.id]: {
      integrationId: current[project.id]?.integrationId ?? null,
      reviewMode: "quick",
      indexingStatus: "connecting",
    },
  }))

  try {
    const result = await connectIntegrationAndEnableIndexing({
      project,
      normalizedInstance,
      token,
    })

    setProjectReviewStateByProjectId((current) => ({
      ...current,
      [project.id]: {
        integrationId: result.integrationId,
        reviewMode: "quick",
        indexingStatus: result.warning ? "warning" : "indexing",
      },
    }))

    if (result.warning) {
      setWebhookSetupFeedback({
        kind: "warning",
        message: result.warning,
      })
      return result.integrationId
    }

    const jobIdsMessage =
      result.planJobId && result.reconcileJobId
        ? ` Plan job: ${result.planJobId}. Reconcile job: ${result.reconcileJobId}.`
        : ""
    setWebhookSetupFeedback({
      kind: "success",
      message: `Webhook active for ${project.path}. Indexing queued for ${result.branch}.${jobIdsMessage}`,
    })

    return result.integrationId
  } catch (error) {

        setProjectReviewStateByProjectId((current) => ({
          ...current,
          [project.id]: {
            integrationId: current[project.id]?.integrationId ?? null,
            reviewMode: "quick",
            indexingStatus: "failed",
          },
        }))
        setWebhookSetupFeedback({
          kind: "warning",
          message: `Webhook setup warning: ${getErrorMessage(error)}`,
        })

        return null
      } finally {
        integrationConnectPromiseByKeyRef.current.delete(connectKey)
      }
    })()

    integrationConnectPromiseByKeyRef.current.set(connectKey, connectPromise)
    return connectPromise
  },
  [customInstance, gitlabInstance, setWebhookSetupFeedback, token],
)

const getProjectReviewContext = useCallback(
  (projectId: string | null | undefined) => {
    if (!projectId) {
      return {
        reviewMode: "quick" as const,
        indexingStatusLabel:
          "Indexing in progress. Quick Review uses MR metadata and diff context first.",
      }
    }

    const state = projectReviewStateByProjectId[projectId]
    if (!state) {
      return {
        reviewMode: "quick" as const,
        indexingStatusLabel:
          "Indexing in progress. Quick Review uses MR metadata and diff context first.",
      }
    }

    return {
      reviewMode: state.reviewMode,
      indexingStatusLabel: buildIndexingStatusLabel(state.indexingStatus),
    }
  },
  [projectReviewStateByProjectId],
)

  const getProjectIntegrationId = useCallback(
    (projectId: string | null | undefined) => {
      if (!projectId) {
        return null
      }
      return projectReviewStateByProjectId[projectId]?.integrationId ?? null
    },
    [projectReviewStateByProjectId],
  )

  return {
    connectIntegration,
    getProjectReviewContext,
    getProjectIntegrationId,
    projectReviewStateByProjectId,
  }
}

