import { Separator } from "@/components/ui/separator"
import { SidebarTrigger } from "@/components/ui/sidebar"
import { CommandPalette } from "@/components/command-palette"
import {
  buildSiteHeaderBreadcrumbs,
  resolveSiteHeaderTitle,
} from "@/components/site-header-breadcrumbs"

export function SiteHeader() {
  const { title, subtitle } = useSiteHeader()
  const pathname = usePathname()
  const breadcrumbs = useMemo(() => buildSiteHeaderBreadcrumbs(pathname), [pathname])
  const resolvedTitle = resolveSiteHeaderTitle(title)

  return (
    <header className="flex h-(--header-height) shrink-0 items-center gap-2 border-b transition-[width,height] ease-linear group-has-data-[collapsible=icon]/sidebar-wrapper:h-(--header-height)">
      <div className="flex w-full items-center gap-1 px-4 lg:gap-2 lg:px-6">
        <SidebarTrigger className="-ml-1" />
        <Separator
          orientation="vertical"
          className="mx-2 data-[orientation=vertical]:h-4"
        />

import { pgTable, text, timestamp } from "drizzle-orm/pg-core";

export const verification = pgTable("verification", {
  id: text("id").primaryKey(),
  identifier: text("identifier").notNull(),
  value: text("value").notNull(),
  expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
  createdAt: timestamp("created_at", { withTimezone: true }),
  updatedAt: timestamp("updated_at", { withTimezone: true }),
});

import path from 'node:path'

const SKIP_DIRS = new Set(['.git', 'node_modules', 'vendor', 'dist', 'build'])
const SKIP_FILES = new Set([
  'bun.lock',
  'package-lock.json',
  'pnpm-lock.yaml',
  'yarn.lock',
  'cargo.lock',
  'composer.lock',
  'go.sum',
])

const BINARY_EXTENSIONS = new Set([
  '.png',
  '.jpg',
  '.jpeg',
  '.gif',
  '.webp',
  '.ico',
  '.pdf',
  '.zip',
  '.gz',
  '.tar',
  '.tgz',
  '.7z',
  '.exe',
  '.dll',
  '.so',
  '.dylib',
  '.woff',
  '.woff2',
  '.ttf',
  '.otf',
  '.mp3',
  '.mp4',
  '.mov',
  '.avi',
])

export const DEFAULT_MAX_FILE_SIZE_BYTES = 512 * 1024

export const shouldSkipPath = (relativePath: string): boolean => {
  const normalized = relativePath.replace(/\\/g, '/').toLowerCase()
  const segments = normalized.split('/').filter(Boolean)
  if (segments.some((segment) => SKIP_DIRS.has(segment))) {
    return true
  }

  const fileName = segments.at(-1)
  if (!fileName) {
    return false
  }

  return SKIP_FILES.has(fileName)
}

export const isLikelyBinary = (relativePath: string, content: Buffer): boolean => {
  const ext = path.extname(relativePath).toLowerCase()
  if (BINARY_EXTENSIONS.has(ext)) {
    return true
  }

  const checkLength = Math.min(content.length, 8_192)
  for (let i = 0; i < checkLength; i += 1) {
    if (content[i] === 0) {
      return true
    }
  }

  return false
}

export const classifySkipReason = (args: {
  relativePath: string
  content: Buffer
  maxFileSizeBytes: number
}): 'path_excluded' | 'binary' | 'file_too_large' | null => {
  if (shouldSkipPath(args.relativePath)) {
    return 'path_excluded'
  }

  if (args.content.length > args.maxFileSizeBytes) {
    return 'file_too_large'
  }

  if (isLikelyBinary(args.relativePath, args.content)) {
    return 'binary'
  }

  return null
}

import { and, count, desc, eq, gte, inArray, sql } from "drizzle-orm"
import { NextResponse } from "next/server"

import { db } from "@/lib/db"
import { appLogEvents, indexJobs, indexRuns } from "@/lib/db/schema"
import { getSessionUserId } from "@/lib/session"
import { runWithApiRequestLog } from "@/lib/utils/logger"

type HealthStatus = "healthy" | "degraded" | "critical"

type HealthIssue = {
  key: string
  severity: "critical" | "warning"
  title: string
  detail: string
  count: number
  level: "info" | "warn" | "error" | "debug" | null
  lastSeenAt: string | null
  requestId: string | null
  event: string | null
  path: string | null
}

const WORKER_HEARTBEAT_STALE_AFTER_MS = 2 * 60_000

const toIso = (value: unknown): string | null => {
  if (!value) {
    return null
  }
  if (value instanceof Date) {
    return Number.isNaN(value.getTime()) ? null : value.toISOString()
  }
  if (typeof value === "string" && value.trim()) {
    const parsed = new Date(value)
    return Number.isNaN(parsed.getTime()) ? null : parsed.toISOString()
  }
  return null
}

const toCount = (value: unknown) => {
  if (typeof value === "number" && Number.isFinite(value)) {
    return value
  }
  if (typeof value === "bigint") {
    return Number(value)
  }
  if (typeof value === "string" && value.trim()) {
    const parsed = Number.parseInt(value, 10)
    return Number.isFinite(parsed) ? parsed : 0
  }
  return 0
}

const toAgeMs = (value: unknown) => {
  const iso = toIso(value)
  if (!iso) {
    return null
  }
  const parsed = new Date(iso)
  const ageMs = Date.now() - parsed.getTime()
  return Number.isFinite(ageMs) && ageMs >= 0 ? ageMs : null
}

const buildStatus = (args: {
  workerFatal15m: number
  heartbeatAgeMs: number | null
  ingestFailed30m: number
  apiIndex5xx10m: number
}) => {
  if (
    args.workerFatal15m > 0 ||
    (args.heartbeatAgeMs !== null && args.heartbeatAgeMs > WORKER_HEARTBEAT_STALE_AFTER_MS)
  ) {
    return "critical" as const
  }
  if (args.ingestFailed30m > 0 || args.apiIndex5xx10m >= 3) {
    return "degraded" as const
  }
  return "healthy" as const
}

export async function GET(request: Request) {
  return runWithApiRequestLog({
    request,
    path: "/api/observability/indexing-health",
    event: "api.observability.indexing_health",
    handler: async ({ logger }) => {
      const userId = await getSessionUserId()
      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      const [
        [workerFatal15mRow],
        [ingestFailed30mRow],
        [apiIndex5xx10mRow],
        [failedRuns24hRow],
        [failedJobs24hRow],
        [pendingJobsRow],
        [processingJobsRow],
        [latestHeartbeatRow],
        latestWorkerFatal,
        latestIngestFailed,
        latestApiIndex5xx,
      ] = await Promise.all([

  db
    .select({
      timestamp: appLogEvents.timestamp,
      level: appLogEvents.level,
      requestId: appLogEvents.requestId,
      event: appLogEvents.event,
      path: appLogEvents.path,
    })
    .from(appLogEvents)
    .where(
      and(
        eq(appLogEvents.event, "indexer.run.processing"),
        eq(sql`${appLogEvents.payload} ->> 'errorCode'`, "INGEST_FAILED"),
        gte(appLogEvents.timestamp, sql`now() - interval '24 hours'`),
      ),
    )
    .orderBy(desc(appLogEvents.timestamp))
    .limit(1),
  db
    .select({
      timestamp: appLogEvents.timestamp,
      level: appLogEvents.level,
      requestId: appLogEvents.requestId,
      event: appLogEvents.event,
      path: appLogEvents.path,
    })
    .from(appLogEvents)
    .where(
      and(
        sql`${appLogEvents.event} like 'api.gitlab.index.%'`,
        gte(appLogEvents.status, 500),
        gte(appLogEvents.timestamp, sql`now() - interval '24 hours'`),
      ),
    )
    .orderBy(desc(appLogEvents.timestamp))
    .limit(1),
])

const workerFatal15m = toCount(workerFatal15mRow?.count)
const ingestFailed30m = toCount(ingestFailed30mRow?.count)
const apiIndex5xx10m = toCount(apiIndex5xx10mRow?.count)
const failedRuns24h = toCount(failedRuns24hRow?.count)
const failedJobs24h = toCount(failedJobs24hRow?.count)

const pendingJobs = toCount(pendingJobsRow?.count)
const processingJobs = toCount(processingJobsRow?.count)
const workerHeartbeatAt = toIso(latestHeartbeatRow?.value)
const workerHeartbeatAgeMs = toAgeMs(latestHeartbeatRow?.value)

const status: HealthStatus = buildStatus({
  workerFatal15m,
  heartbeatAgeMs: workerHeartbeatAgeMs,
  ingestFailed30m,
  apiIndex5xx10m,
})

const issues: HealthIssue[] = []
if (latestWorkerFatal[0] && workerFatal15m > 0) {
  issues.push({
    key: "worker_fatal",
    severity: "critical",
    title: "Worker crashed",
    detail: "Indexer worker fatal errors detected recently.",
    count: workerFatal15m,
    level: latestWorkerFatal[0].level,
    lastSeenAt: toIso(latestWorkerFatal[0].timestamp),
    requestId: latestWorkerFatal[0].requestId,
    event: latestWorkerFatal[0].event,
    path: latestWorkerFatal[0].path,
  })
}
if (latestIngestFailed[0] && ingestFailed30m > 0) {
  issues.push({
    key: "ingest_failed",
    severity: "warning",
    title: "Ingest failed",
    detail: "One or more ingest runs failed recently.",
    count: ingestFailed30m,
    level: latestIngestFailed[0].level,
    lastSeenAt: toIso(latestIngestFailed[0].timestamp),
    requestId: latestIngestFailed[0].requestId,
    event: latestIngestFailed[0].event,
    path: latestIngestFailed[0].path,
  })
}

      if (latestApiIndex5xx[0] && apiIndex5xx10m > 0) {
        issues.push({
          key: "index_api_5xx",
          severity: "warning",
          title: "Index API errors",
          detail: "Indexing API endpoints returned 5xx responses.",
          count: apiIndex5xx10m,
          level: latestApiIndex5xx[0].level,
          lastSeenAt: toIso(latestApiIndex5xx[0].timestamp),
          requestId: latestApiIndex5xx[0].requestId,
          event: latestApiIndex5xx[0].event,
          path: latestApiIndex5xx[0].path,
        })
      }

      logger.set({
        status,
        workerFatal15m,
        ingestFailed30m,
        apiIndex5xx10m,
        failedRuns24h,
        failedJobs24h,
        pendingJobs,
        processingJobs,
        workerHeartbeatAgeMs,
      })

      return {
        status: 200,
        outcome: "success",
        response: NextResponse.json({
          status,
          summary: {
            workerFatal15m,
            ingestFailed30m,
            apiIndex5xx10m,
            failedRuns24h,
            failedJobs24h,
            pendingJobs,
            processingJobs,
            workerHeartbeatAt,
            workerHeartbeatAgeMs,
            workerHeartbeatStaleAfterMs: WORKER_HEARTBEAT_STALE_AFTER_MS,
          },
          issues,
        }),
      }
    },
  })
}

