import { Client } from 'pg'

type QueryResultLike<Row> = {
  rowCount: number | null
  rows: Row[]
}

export type BootstrapClient = {
  connect: () => Promise<void>
  query: <Row = Record<string, unknown>>(
    queryText: string,
    values?: unknown[],
  ) => Promise<QueryResultLike<Row>>
  end: () => Promise<void>
}

type BootstrapLogger = Pick<Console, 'log'>

type RunDbBootstrapOptions = {
  databaseUrl?: string
  extension?: string
  clientFactory?: (databaseUrl: string) => BootstrapClient
  logger?: BootstrapLogger
}

export const resolveDatabaseUrl = (value = process.env.DATABASE_URL): string => {
  const databaseUrl = value?.trim()
  if (!databaseUrl) {
    throw new Error('DATABASE_URL is required for db bootstrap.')
  }

  return databaseUrl
}

export const resolveVectorExtension = (value = process.env.DB_VECTOR_EXTENSION): string => {
  const extension = (value?.trim() || 'vector').toLowerCase()
  if (!/^[a-z_][a-z0-9_]*$/.test(extension)) {
    throw new Error(`Invalid DB_VECTOR_EXTENSION value: ${extension}`)
  }

  return extension
}

type PgErrorLike = Error & {
  code?: string
  detail?: string
  hint?: string
}

export const formatBootstrapError = (error: unknown, extensionName: string): Error => {
  const pgError = error as PgErrorLike
  const code = pgError?.code
  const detail = pgError?.detail ? ` Detail: ${pgError.detail}` : ''
  const hint = pgError?.hint ? ` Hint: ${pgError.hint}` : ''

  if (code === '42501') {
    return new Error(
      [
        `[db:bootstrap] cannot create extension "${extensionName}" (insufficient privilege).`,
        'Use a database owner/superuser for setup or ask your DB admin to run:',
        `create extension if not exists "${extensionName}";`,
        detail,
        hint,
      ]
        .join(' ')
        .trim(),
    )
  }

  if (code === '0A000') {
    return new Error(
      [
        `[db:bootstrap] extension "${extensionName}" is not available on this PostgreSQL server.`,
        'Install pgvector on the DB host/image first (for local Docker, prefer pgvector/pgvector images).',
        detail,
        hint,
      ]
        .join(' ')
        .trim(),
    )
  }

  return new Error(
    [
      `[db:bootstrap] failed to ensure extension "${extensionName}" is ready.`,
      pgError?.message ?? String(error),
      detail,
      hint,
    ]
      .join(' ')
      .trim(),
  )
}

export const runDbBootstrap = async (options: RunDbBootstrapOptions = {}): Promise<void> => {
  const databaseUrl = options.databaseUrl ?? resolveDatabaseUrl()
  const extension = options.extension ?? resolveVectorExtension()
  const clientFactory = options.clientFactory ?? ((connectionString: string) => new Client({ connectionString }))
  const logger = options.logger ?? console

  const client = clientFactory(databaseUrl)
  await client.connect()

  try {
    try {
      await client.query(`create extension if not exists "${extension}"`)
    } catch (error) {
      throw formatBootstrapError(error, extension)
    }

    const check = await client.query<{ extname: string; extversion: string }>(
      'select extname, extversion from pg_extension where extname = $1',
      [extension],
    )

    if (check.rowCount !== 1) {
      throw new Error(`Extension "${extension}" is not available in this database.`)
    }

    const typeCheck = await client.query<{ vectorType: string | null }>(
      `select to_regtype('vector')::text as "vectorType"`,
    )
    if (!typeCheck.rows[0]?.vectorType) {
      throw new Error(
        `Extension "${extension}" is installed but SQL type "vector" is missing. Ensure pgvector is correctly installed.`,
      )
    }

    const version = check.rows[0]?.extversion ?? 'unknown'
    logger.log(`[db:bootstrap] extension "${extension}" ready (version ${version}).`)
  } finally {
    await client.end()
  }
}

if (import.meta.main) {
  runDbBootstrap().catch((error) => {
    console.error('[db:bootstrap] failed', error)
    process.exit(1)
  })
}

