import path from 'node:path'

const DEFAULT_REPORTS_DIR = path.join(process.cwd(), '.benchmarks', 'indexing')
const DEFAULT_BASELINE_PATH = path.join(DEFAULT_REPORTS_DIR, 'phase2-baseline.json')

const getArgValue = (flag: string): string | null => {
  const args = process.argv.slice(2)
  const index = args.indexOf(flag)
  if (index < 0) {
    return null
  }

  const next = args[index + 1]
  if (!next || next.startsWith('--')) {
    return null
  }

  return next
}

const listReportFiles = async (reportsDir: string): Promise<string[]> => {
  const entries = await readdir(reportsDir, { withFileTypes: true })
  return entries
    .filter((entry) => entry.isFile())
    .map((entry) => entry.name)
    .filter((name) => /^phase2-.*\.json$/.test(name) && name !== 'phase2-baseline.json')
    .sort()
}

const resolveLatestReportPath = async (reportsDir: string): Promise<string> => {
  const reportFiles = await listReportFiles(reportsDir)
  const latest = reportFiles[reportFiles.length - 1]
  if (!latest) {
    throw new Error(`No benchmark reports found in ${reportsDir}. Run bench:indexing:phase2 first.`)
  }

  return path.join(reportsDir, latest)
}

const main = async () => {
  const reportsDir = process.env.INDEXING_BENCH_REPORTS_DIR?.trim() || DEFAULT_REPORTS_DIR
  const baselinePath = process.env.INDEXING_BENCH_BASELINE_PATH?.trim() || DEFAULT_BASELINE_PATH
  const explicitSource = getArgValue('--source')

  await mkdir(path.dirname(baselinePath), { recursive: true })

  const sourcePath = explicitSource
    ? path.resolve(explicitSource)
    : await resolveLatestReportPath(reportsDir)

  await copyFile(sourcePath, baselinePath)
  console.log(`Baseline updated: ${baselinePath}`)
  console.log(`Source report: ${sourcePath}`)
}

main().catch((error) => {
  console.error('[indexing-benchmark:set-baseline] failed', error)
  process.exit(1)
})

import { NextResponse } from "next/server"
import { z } from "zod"

import { getUserIntegration, resyncGitLabIntegration } from "@/lib/gitlab/service"
import { getSessionUserId } from "@/lib/session"
import { runWithApiRequestLog } from "@/lib/utils/logger"

const resyncSchema = z.object({
  token: z.string().optional(),
})

export async function POST(
  request: Request,
  context: { params: Promise<{ integrationId: string }> },
) {
  const { integrationId } = await context.params
  return runWithApiRequestLog({
    request,
    path: `/api/gitlab/integrations/${integrationId}/resync`,
    event: "api.gitlab.integrations.resync",
    context: { integrationId },
    handler: async ({ logger }) => {

      const userId = await getSessionUserId()
      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      const [integration, payload] = await Promise.all([
        getUserIntegration(integrationId, userId),
        request.json().catch(() => ({})),
      ])

      if (!integration) {
        return {
          status: 404,
          outcome: "not_found",
          response: NextResponse.json({ error: "Integration not found." }, { status: 404 }),
        }
      }

      const parsed = resyncSchema.safeParse(payload)
      if (!parsed.success) {
        return {
          status: 400,
          outcome: "invalid_request",
          response: NextResponse.json({ error: "Invalid resync payload." }, { status: 400 }),
        }
      }

      try {
        const result = await resyncGitLabIntegration({
          integration,
          token: parsed.data.token,
        })
        logger.set({
          hasWarning: Boolean(result.warning),
        })
        return {
          status: 200,
          outcome: "success",
          response: NextResponse.json({ data: result.integration, warning: result.warning }),
        }
      } catch (error) {
        const message = error instanceof Error ? error.message : "Failed to resync integration."
        return {
          status: 400,
          outcome: "invalid_request",
          response: NextResponse.json({ error: message }, { status: 400 }),
        }
      }
    },
  })
}

import { eq, inArray, sql } from "drizzle-orm"
import { NextResponse } from "next/server"

import { db } from "@/lib/db"
