import { useEffect } from "react"

import type { OnboardingRouteStep } from "@/components/onboarding/onboarding-types"

type RouterLike = {
  replace: (href: string) => void
}

type UseOnboardingRouteGuardsOptions = {
  isHydrated: boolean
  routeStep: OnboardingRouteStep
  token: string
  selectedProjectId: string
  router: RouterLike
}

export function useOnboardingRouteGuards({
  isHydrated,
  routeStep,
  token,
  selectedProjectId,
  router,
}: UseOnboardingRouteGuardsOptions) {
  useEffect(() => {
    if (!isHydrated) {
      return
    }

    if (routeStep === "projects" && !token.trim()) {
