}

const dedupeFindings = (findings: ReviewFinding[]) => {
  const deduped = new Map<string, ReviewFinding>()
  for (const finding of findings) {
    const normalizedFile = normalizePatchPath(finding.file)
    const key = `${normalizedFile}:${finding.side}:${finding.line}:${finding.title}`
    if (!deduped.has(key)) {
      deduped.set(key, {
        ...finding,
        file: normalizedFile,
      })
    }
  }
  return Array.from(deduped.values())
}

const buildReviewSummary = (findings: ReviewFinding[]) => {
  if (findings.length === 0) {
    return "AI review complete. No findings."
  }

  const highCount = findings.filter((finding) => finding.severity === "high").length
  const medCount = findings.filter((finding) => finding.severity === "med").length
  const lowCount = findings.length - highCount - medCount
  return `AI review complete: ${findings.length} findings (${highCount} high, ${medCount} med, ${lowCount} low).`
}

type ReviewBatch = {
  patch: string
  files: string[]
}

const buildReviewBatches = (patchText: string): ReviewBatch[] => {
  const patchChunks = splitPatchIntoFileChunks(patchText)
  if (patchChunks.length === 0) {
    return [
      {
        patch: patchText,
        files: extractFilePathsFromPatch(patchText),
      },
    ]
  }

  const groupedChunks: string[][] = []
  let currentBatch: string[] = []
  let currentBatchCharLength = 0

  for (const chunk of patchChunks) {
    const separatorCharLength = currentBatch.length > 0 ? 2 : 0
    const candidateLength = currentBatchCharLength + separatorCharLength + chunk.length
    const exceedsFileLimit = currentBatch.length >= REVIEW_BATCH_FILE_COUNT
    const exceedsCharLimit = candidateLength > REVIEW_BATCH_MAX_PATCH_CHARS

    if (currentBatch.length > 0 && (exceedsFileLimit || exceedsCharLimit)) {
      groupedChunks.push(currentBatch)
      currentBatch = [chunk]
      currentBatchCharLength = chunk.length
      continue
    }

    currentBatch.push(chunk)
    currentBatchCharLength = candidateLength
  }

  if (currentBatch.length > 0) {
    groupedChunks.push(currentBatch)
  }

  return groupedChunks.map((chunks) => {
    const joinedPatch = chunks.join("\n\n")
    return {
      patch: joinedPatch,
      files: extractFilePathsFromPatch(joinedPatch),
    }
  })
}

const normalizeFeedback = (value: unknown): ReviewFeedback | null => {
  if (value === "up" || value === "down") {
    return value
  }
  return null
}

export function useMergeRequestAiReview({
  instanceUrl,
  projectId,
  mergeRequestIid,
}: UseMergeRequestAiReviewOptions) {

const [isReviewing, setIsReviewing] = useState(false)
const [reviewError, setReviewError] = useState("")
const [reviewSummary, setReviewSummary] = useState("")
const [reviewFindings, setReviewFindings] = useState<ReviewFinding[]>([])
const [reviewRun, setReviewRun] = useState<ReviewRunState>(() => createInitialReviewRunState())
const [reviewId, setReviewId] = useState<string | null>(null)
const [reviewFeedback, setReviewFeedback] = useState<ReviewFeedback | null>(null)
const [isSubmittingReviewFeedback, setIsSubmittingReviewFeedback] = useState(false)
const [reviewFeedbackError, setReviewFeedbackError] = useState("")
const reviewRunEventIdRef = useRef(0)

const appendReviewRunEvent = useCallback(
  (stage: ReviewRunState["stage"], message: string) => {
    const createdAt = Date.now()
    const id = reviewRunEventIdRef.current + 1
    reviewRunEventIdRef.current = id
    setReviewRun((current) => ({
      ...current,
      events: [...current.events, { id, stage, message, createdAt }].slice(-MAX_REVIEW_RUN_EVENTS),
    }))
  },
  [],
)

const resetReviewState = useCallback(() => {
  setReviewFindings([])
  setReviewError("")
  setReviewSummary("")
  setReviewId(null)
  setReviewFeedback(null)
  setReviewFeedbackError("")
  setIsSubmittingReviewFeedback(false)
  reviewRunEventIdRef.current = 0
  setReviewRun(createInitialReviewRunState())
}, [])

const clearReviewFindings = useCallback(() => {
  resetReviewState()
}, [resetReviewState])

const loadLatestSavedReview = useCallback(async () => {

resetReviewState()
const normalizedInstanceUrl = instanceUrl.trim().replace(/\/+$/, "")
const normalizedProjectId = projectId.trim()
const normalizedMergeRequestIid = mergeRequestIid.trim()
if (!normalizedInstanceUrl || !normalizedProjectId || !normalizedMergeRequestIid) {
  return
}

try {
  const params = new URLSearchParams({
    instanceUrl: normalizedInstanceUrl,
    projectId: normalizedProjectId,
    mergeRequestIid: normalizedMergeRequestIid,
  })
  const response = await fetch(`/api/review/diff?${params.toString()}`, {
    method: "GET",
  })
  const payload = (await response.json().catch(() => null)) as DiffReviewPayload | null
  if (!response.ok) {
    throw new Error(getReviewErrorMessage(payload))
  }

  const persistedReview = normalizePersistedReview(payload?.data?.review)
  if (!persistedReview) {
    return
  }

  const findings = dedupeFindings(persistedReview.findings)
  const parsedCreatedAt = Date.parse(persistedReview.createdAt)
  const createdAt = Number.isFinite(parsedCreatedAt) ? parsedCreatedAt : Date.now()
  setReviewFindings(findings)
  setReviewSummary(persistedReview.summary || buildReviewSummary(findings))
  setReviewId(persistedReview.id)
  setReviewFeedback(persistedReview.feedback)

    setReviewRun({
      ...createInitialReviewRunState(),
      stage: "done",
      totalBatches: 1,
      completedBatches: 1,
      currentBatchIndex: 1,
      reviewedFiles: Array.from(
        new Set(
          findings
            .map((finding) => normalizePatchPath(finding.file))
            .filter((path) => path.length > 0),
        ),
      ),
      startedAt: createdAt,
      finishedAt: createdAt,
      events: [
        {
          id: 1,
          stage: "done",
          message: "Loaded latest saved review.",
          createdAt,
        },
      ],
    })
    reviewRunEventIdRef.current = 1
  } catch (error) {
    setReviewError(getReviewErrorMessage(error))
  }
}, [instanceUrl, mergeRequestIid, projectId, resetReviewState])

const runAiReview = useCallback(
  async (patchText: string) => {
    if (!patchText.trim()) {
      setReviewError("Load a diff before running AI review.")
      setReviewSummary("")
      setReviewFindings([])
      setReviewId(null)
      setReviewFeedback(null)
      setReviewFeedbackError("")
      reviewRunEventIdRef.current = 0
      setReviewRun(createInitialReviewRunState())
      return
    }

    const startedAt = Date.now()
    setIsReviewing(true)
    setReviewError("")
    setReviewSummary("")
    setReviewFindings([])
    setReviewId(null)
    setReviewFeedback(null)
    setReviewFeedbackError("")
    reviewRunEventIdRef.current = 0

setReviewRun({
  ...createInitialReviewRunState(),
  stage: "chunking",
  startedAt,
})
appendReviewRunEvent("chunking", "Preparing review batches from patch files.")

try {
  const reviewBatches = buildReviewBatches(patchText)
  const totalBatches = reviewBatches.length
  appendReviewRunEvent(
    "chunking",
    `Queued ${totalBatches} ${totalBatches === 1 ? "batch" : "batches"} for AI analysis.`,
  )
  setReviewRun((current) => ({
    ...current,
    stage: "analyzing",
    totalBatches,
    currentBatchIndex: totalBatches > 0 ? 1 : 0,
    currentBatchFiles: reviewBatches[0]?.files ?? [],
  }))

  let allFindings: ReviewFinding[] = []
  const reviewedFiles = new Set<string>()

  for (let index = 0; index < reviewBatches.length; index += 1) {
    const batch = reviewBatches[index]
    const batchIndex = index + 1
    const fileCountLabel = batch.files.length > 0 ? ` (${batch.files.length} files)` : ""
    appendReviewRunEvent(
      "analyzing",
      `Analyzing batch ${batchIndex}/${totalBatches}${fileCountLabel}.`,
    )
    setReviewRun((current) => ({
      ...current,
      stage: "analyzing",
      currentBatchIndex: batchIndex,
      currentBatchFiles: batch.files,
    }))

  const response = await fetch("/api/review/diff", {
    method: "POST",
    headers: {
      "content-type": "application/json",
    },
    body: JSON.stringify({
      patch: batch.patch,
    }),
  })

  const payload = (await response.json().catch(() => null)) as DiffReviewPayload | null
  if (!response.ok) {
    throw new Error(getReviewErrorMessage(payload))
  }

  const batchFindings = normalizeReviewFindings(payload?.data?.findings)
  allFindings = allFindings.concat(batchFindings)
  for (const path of batch.files) {
    reviewedFiles.add(path)
  }

  setReviewFindings(dedupeFindings(allFindings))
  setReviewRun((current) => ({
    ...current,
    completedBatches: batchIndex,
    reviewedFiles: Array.from(reviewedFiles),
  }))
  appendReviewRunEvent(
    "analyzing",
    `Batch ${batchIndex}/${totalBatches} complete: ${batchFindings.length} findings.`,
  )
}

setReviewRun((current) => ({
  ...current,
  stage: "mapping",
  currentBatchFiles: [],
}))
appendReviewRunEvent("mapping", "Consolidating findings across all batches.")
const findings = dedupeFindings(allFindings)
const summary = buildReviewSummary(findings)
setReviewFindings(findings)
setReviewSummary(summary)

setReviewRun((current) => ({
  ...current,
  stage: "done",
  finishedAt: Date.now(),
  currentBatchFiles: [],
}))
appendReviewRunEvent(
  "done",
  findings.length === 0
    ? "Review complete: no findings."
    : `Review complete: ${summary.replace("AI review complete: ", "")}`,
)

const normalizedInstanceUrl = instanceUrl.trim().replace(/\/+$/, "")
const normalizedProjectId = projectId.trim()
const normalizedMergeRequestIid = mergeRequestIid.trim()

if (normalizedInstanceUrl && normalizedProjectId && normalizedMergeRequestIid) {
  try {
    const saveResponse = await fetch("/api/review/save", {
      method: "POST",
      headers: {
        "content-type": "application/json",
      },
      body: JSON.stringify({
        patch: patchText,
        findings,
        summary,
        instanceUrl: normalizedInstanceUrl,
        projectId: normalizedProjectId,
        mergeRequestIid: normalizedMergeRequestIid,
      }),
    })
    const savePayload = (await saveResponse.json().catch(() => null)) as
      | DiffReviewPayload
      | null
    if (!saveResponse.ok) {
      throw new Error(getReviewErrorMessage(savePayload))
    }

    const persistedReview = normalizePersistedReview(savePayload?.data?.review)
    if (persistedReview) {
      setReviewId(persistedReview.id)
      setReviewFeedback(persistedReview.feedback)
    }
  } catch {
    appendReviewRunEvent("done", "Review complete, but saving the review failed.")
  }
}

  } catch (error) {
    const message = getReviewErrorMessage(error)
    setReviewSummary("")
    setReviewError(message)
    setReviewRun((current) => ({
      ...current,
      stage: "failed",
      finishedAt: Date.now(),
      failedFiles: Array.from(new Set([...current.failedFiles, ...current.currentBatchFiles])),
      currentBatchFiles: [],
    }))
    appendReviewRunEvent("failed", message)
  } finally {
    setIsReviewing(false)
  }
},
[appendReviewRunEvent, instanceUrl, mergeRequestIid, projectId],

  )

  const submitReviewFeedback = useCallback(
    async (nextFeedback: ReviewFeedback | null) => {
      if (!reviewId || isSubmittingReviewFeedback) {
        return
      }

      setIsSubmittingReviewFeedback(true)
      setReviewFeedbackError("")
      try {
        const response = await fetch("/api/review/feedback", {
          method: "POST",
          headers: {
            "content-type": "application/json",
          },
          body: JSON.stringify({
            reviewId,
            feedback: nextFeedback,
          }),
        })
        const payload = (await response.json().catch(() => null)) as ReviewFeedbackPayload | null
        if (!response.ok) {
          throw new Error(getReviewErrorMessage(payload))
        }
        setReviewFeedback(normalizeFeedback(payload?.data?.review?.feedback))
      } catch (error) {
        setReviewFeedbackError(getReviewErrorMessage(error))
      } finally {
        setIsSubmittingReviewFeedback(false)
      }
    },
    [isSubmittingReviewFeedback, reviewId],
  )

  return {
    isReviewing,
    reviewError,
    reviewSummary,
    reviewFindings,
    reviewRun,
    reviewId,
    reviewFeedback,
    reviewFeedbackError,
    isSubmittingReviewFeedback,
    clearReviewFindings,
    resetReviewState,
    loadLatestSavedReview,
    runAiReview,
    submitReviewFeedback,
  }
}

