import { and, eq, sql } from 'drizzle-orm'

import { db } from '@/lib/db'
import { gitlabIntegrations, indexBranchStates, indexJobs } from '@/lib/db/schema'
import { DEFAULT_INDEX_CONFIG_HASH } from '@/lib/indexing/constants'

type ClaimedIndexJob = {
  id: string
  integrationId: string
  jobType: 'plan' | 'reconcile'
  debounceKey: string
  branch: string | null
  configHash: string | null
  hintedHeadSha: string | null
  configJson: Record<string, unknown> | null
  attempts: number
}

const INDEX_JOB_MAX_ATTEMPTS = 8

const parsePositiveInt = (value: string | undefined, fallback: number) => {
  if (!value) {
    return fallback
  }

  const parsed = Number.parseInt(value, 10)
  if (!Number.isFinite(parsed) || parsed <= 0) {
    return fallback
  }

  return parsed
}

const resolveIndexJobMaxAttempts = () =>
  parsePositiveInt(process.env.INDEXER_JOB_MAX_ATTEMPTS, INDEX_JOB_MAX_ATTEMPTS)

const INDEXER_RECONCILE_INTERVAL_MS = 5 * 60_000
const INDEXER_RECONCILE_INTEGRATION_LIMIT = 500

const resolveReconcileIntervalMs = () =>
  parsePositiveInt(process.env.INDEXER_RECONCILE_INTERVAL_MS, INDEXER_RECONCILE_INTERVAL_MS)

const resolveReconcileIntegrationLimit = () =>
  parsePositiveInt(
    process.env.INDEXER_RECONCILE_INTEGRATION_LIMIT,
    INDEXER_RECONCILE_INTEGRATION_LIMIT,
  )

const getRetryDelayMs = (attempt: number) => {
  const exponent = Math.max(0, attempt - 1)
  const baseDelayMs = 30_000
  return Math.min(60 * 60 * 1_000, baseDelayMs * 2 ** exponent)
}

const normalizeConfigHash = (value?: string) => value?.trim() || DEFAULT_INDEX_CONFIG_HASH

export const enqueueReconcileJob = async (args: { integrationId: string }) => {
  const now = new Date()
  const debounceKey = buildReconcileDebounceKey(args.integrationId)

  const [row] = await db
    .insert(indexJobs)
    .values({
      integrationId: args.integrationId,
      jobType: 'reconcile',
      debounceKey,
      status: 'pending',
      attempts: 0,
      nextAttemptAt: now,
      startedAt: null,
      finishedAt: null,
      lastError: null,
      result: null,
      createdAt: now,
      updatedAt: now,
    })
    .onConflictDoUpdate({
      target: [indexJobs.debounceKey],
      set: {
        integrationId: args.integrationId,
        jobType: 'reconcile',
        status: 'pending',
        attempts: 0,
        nextAttemptAt: now,
        startedAt: null,
        finishedAt: null,
        lastError: null,
        result: null,
        updatedAt: now,
      },
    })
    .returning({
      id: indexJobs.id,
      debounceKey: indexJobs.debounceKey,
      status: indexJobs.status,
    })

  if (!row) {
    throw new Error('Failed to enqueue reconcile job.')
  }

  return row
}

export const enqueueDueReconcileJobs = async () => {
  const now = new Date()
  const dueBefore = new Date(now.getTime() - resolveReconcileIntervalMs())
  const integrationLimit = resolveReconcileIntegrationLimit()
  const query = sql<{ id: string }>`
    with candidate_integrations as (
      select distinct ${indexBranchStates.integrationId} as integration_id
      from ${indexBranchStates}
      inner join ${gitlabIntegrations}

  return result.rows.map((raw) => {
    const row = raw as Record<string, unknown>
    return {
      id: String(row.id),
      integrationId: String(row.integrationId),
      jobType: row.jobType === 'reconcile' ? 'reconcile' : 'plan',
      debounceKey: String(row.debounceKey),
      branch: typeof row.branch === 'string' ? row.branch : null,
      configHash: typeof row.configHash === 'string' ? row.configHash : null,
      hintedHeadSha: typeof row.hintedHeadSha === 'string' ? row.hintedHeadSha : null,
      configJson:
        row.configJson && typeof row.configJson === 'object' && !Array.isArray(row.configJson)
          ? (row.configJson as Record<string, unknown>)
          : null,
      attempts: Number(row.attempts),
    }
  })
}

export const markIndexJobSucceeded = async (args: {
  jobId: string
  result: Record<string, unknown>
}) => {
  const rows = await db
    .update(indexJobs)
    .set({
      status: 'succeeded',
      finishedAt: new Date(),
      lastError: null,
      result: args.result,
      updatedAt: new Date(),
    })
    .where(and(eq(indexJobs.id, args.jobId), eq(indexJobs.status, 'processing')))
    .returning({ id: indexJobs.id })

  return rows.length > 0
}

export const markIndexJobFailed = async (args: {
  job: ClaimedIndexJob
  error: unknown
}) => {
  const message =
    args.error instanceof Error
      ? args.error.message.slice(0, 500)
      : 'Unexpected indexing job processing error.'

  const maxAttempts = resolveIndexJobMaxAttempts()
  const exceededAttempts = args.job.attempts >= maxAttempts
  const rows = await db
    .update(indexJobs)
    .set({
      status: exceededAttempts ? 'dead' : 'failed',
      finishedAt: exceededAttempts ? new Date() : null,
      nextAttemptAt: exceededAttempts
        ? new Date()
        : new Date(Date.now() + getRetryDelayMs(args.job.attempts)),
      lastError: message,
      updatedAt: new Date(),
    })
    .where(and(eq(indexJobs.id, args.job.id), eq(indexJobs.status, 'processing')))
    .returning({ id: indexJobs.id, status: indexJobs.status })

  return rows[0]?.status ?? null
}

import { describe, expect, test } from 'bun:test'

import {
  buildDeltaIngestPlan,
  resolveDeltaFallbackReason,
} from '@/lib/indexing/delta-plan'

describe('resolveDeltaFallbackReason', () => {
  test('returns missing_base_sha when base sha is unavailable', () => {
    const reason = resolveDeltaFallbackReason({
      baseSha: null,
      compare: {
        valid: true,
        incomplete: false,
        changes: [],
      },
      maxChanges: 10,
    })

    expect(reason).toBe('missing_base_sha')
  })

  test('returns compare_invalid, compare_incomplete, and too_many_changes in order', () => {
    expect(
      resolveDeltaFallbackReason({
        baseSha: 'base-sha',
        compare: {
          valid: false,
          incomplete: false,
          changes: [],
        },
        maxChanges: 10,
      }),
    ).toBe('compare_invalid')

    expect(
      resolveDeltaFallbackReason({
        baseSha: 'base-sha',
        compare: {
          valid: true,
          incomplete: true,
          changes: [],
        },
        maxChanges: 10,
      }),
    ).toBe('compare_incomplete')

    expect(
      resolveDeltaFallbackReason({
        baseSha: 'base-sha',
        compare: {
          valid: true,
          incomplete: false,
          changes: [
            { oldPath: 'a.ts', newPath: 'a.ts', type: 'modified' },
            { oldPath: 'b.ts', newPath: 'b.ts', type: 'modified' },
          ],
        },
        maxChanges: 1,
      }),
    ).toBe('too_many_changes')
  })

  test('returns null when compare is usable for delta', () => {
    const reason = resolveDeltaFallbackReason({
      baseSha: 'base-sha',
      compare: {
        valid: true,
        incomplete: false,
        changes: [{ oldPath: 'a.ts', newPath: 'a.ts', type: 'modified' }],
      },
      maxChanges: 10,
    })

    expect(reason).toBeNull()
  })
})

describe('buildDeltaIngestPlan', () => {
  test('maps rename to delete old path and upsert new path', () => {
    const plan = buildDeltaIngestPlan([
      { oldPath: 'src/old.ts', newPath: 'src/new.ts', type: 'renamed' },
      { oldPath: 'src/deleted.ts', newPath: null, type: 'deleted' },
      { oldPath: null, newPath: 'src/added.ts', type: 'added' },
    ])

    expect(plan.deletes).toEqual([
      { path: 'src/old.ts', reason: 'renamed' },
      { path: 'src/deleted.ts', reason: 'deleted' },
    ])
    expect(plan.upserts).toEqual([
      { path: 'src/new.ts', changeType: 'renamed', oldPath: 'src/old.ts' },
      { path: 'src/added.ts', changeType: 'added', oldPath: null },
    ])
  })

  test('keeps paths unique and applies the last change for the same path', () => {
    const plan = buildDeltaIngestPlan([
      { oldPath: null, newPath: 'src/a.ts', type: 'added' },
      { oldPath: 'src/a.ts', newPath: 'src/a.ts', type: 'modified' },
      { oldPath: 'src/a.ts', newPath: null, type: 'deleted' },
    ])

    expect(plan.deletes).toEqual([{ path: 'src/a.ts', reason: 'deleted' }])
    expect(plan.upserts).toEqual([])
  })
})

