import { connectIntegrationAndEnableIndexing } from "@/components/onboarding/hooks/use-onboarding-integration-connect"

describe("connectIntegrationAndEnableIndexing", () => {
  test("queues plan and reconcile jobs after project connect", async () => {
    const fetchMock = mock(async (input: string) => {
      if (input === "/api/gitlab/integrations/connect") {
        return new Response(
          JSON.stringify({
            data: { id: "integration-1" },
          }),
          { status: 200, headers: { "content-type": "application/json" } },
        )
      }

      if (input === "/api/gitlab/integrations/integration-1/index/enable") {
        return new Response(
          JSON.stringify({
            data: {
              branch: "main",
              job: { id: "plan-job-1" },
              reconcileJob: { id: "reconcile-job-1" },
            },
          }),
          { status: 200, headers: { "content-type": "application/json" } },
        )
      }

      return new Response(JSON.stringify({ error: "Unexpected request" }), {
        status: 500,
        headers: { "content-type": "application/json" },
      })
    })

    const result = await connectIntegrationAndEnableIndexing({
      project: {
        id: "project-1",
        name: "Project 1",
        path: "group/project-1",
        webUrl: "https://gitlab.com/group/project-1",
        defaultBranch: "main",
      },
      normalizedInstance: "https://gitlab.com",
      token: "token-123",
      fetchImpl: fetchMock as unknown as typeof fetch,
    })

  })

  test("returns integration id with warning when indexing enable fails", async () => {
    const fetchMock = mock(async (input: string) => {
      if (input === "/api/gitlab/integrations/connect") {
        return new Response(
          JSON.stringify({
            data: { id: "integration-1" },
          }),
          { status: 200, headers: { "content-type": "application/json" } },
        )
      }

      if (input === "/api/gitlab/integrations/integration-1/index/enable") {
        return new Response(
          JSON.stringify({
            error: "Indexing queue unavailable",
          }),
          { status: 503, headers: { "content-type": "application/json" } },
        )
      }

      return new Response(JSON.stringify({ error: "Unexpected request" }), {
        status: 500,
        headers: { "content-type": "application/json" },
      })
    })

    const result = await connectIntegrationAndEnableIndexing({
      project: {
        id: "project-1",
        name: "Project 1",
        path: "group/project-1",
        webUrl: "https://gitlab.com/group/project-1",
        defaultBranch: "main",
      },
      normalizedInstance: "https://gitlab.com",
      token: "token-123",
      fetchImpl: fetchMock as unknown as typeof fetch,
    })

    expect(fetchMock).toHaveBeenCalledTimes(2)
    expect(result).toEqual({
      integrationId: "integration-1",
      warning: "Webhook active, but indexing could not be queued. Indexing queue unavailable",
    })
  })
})

