import { eq } from "drizzle-orm"
import { db } from "@/lib/db"
import { jiraCredentials } from "@/lib/db/schema"
import { decryptGitLabToken, encryptGitLabToken } from "@/lib/gitlab/crypto"
import { normalizeJiraInstanceUrl } from "@/lib/jira/instance"

export type JiraStoredCredentials = {
  baseUrl: string
  email: string
  token: string
}

const normalizeEmail = (value: string) => value.trim()

const decryptStoredToken = (row: typeof jiraCredentials.$inferSelect) =>
  decryptGitLabToken({
    ciphertext: row.tokenCiphertext,
    iv: row.tokenIv,
    authTag: row.tokenAuthTag,
  })

export const getStoredJiraCredentials = async (
  userId: string,
): Promise<JiraStoredCredentials | null> => {
  const row = await db.query.jiraCredentials.findFirst({
    where: eq(jiraCredentials.userId, userId),
  })

  if (!row) {
    return null
  }

  return {
    baseUrl: row.baseUrl,
    email: row.email,
    token: decryptStoredToken(row),
  }
}

export const getStoredJiraCredentialSummary = async (userId: string) => {
  const row = await db.query.jiraCredentials.findFirst({
    where: eq(jiraCredentials.userId, userId),
  })

  if (!row) {
    return {
      baseUrl: "",
      email: "",
      hasCredentials: false,
    }
  }

  return {
    baseUrl: row.baseUrl,
    email: row.email,
    hasCredentials: true,
  }
}

export const upsertJiraCredentials = async (
  userId: string,
  input: JiraStoredCredentials,
) => {
  const normalizedBaseUrl = normalizeJiraInstanceUrl(input.baseUrl)
  const normalizedEmail = normalizeEmail(input.email)
  const normalizedToken = input.token.trim()

  if (!normalizedEmail) {
    throw new Error("Jira email is required.")
  }

  if (!normalizedToken) {
    throw new Error("Jira API token is required.")
  }

  const encryptedToken = encryptGitLabToken(normalizedToken)

  await db
    .insert(jiraCredentials)
    .values({
      userId,
      baseUrl: normalizedBaseUrl,
      email: normalizedEmail,
      tokenCiphertext: encryptedToken.ciphertext,
      tokenIv: encryptedToken.iv,
      tokenAuthTag: encryptedToken.authTag,
    })
    .onConflictDoUpdate({
      target: jiraCredentials.userId,
      set: {
        baseUrl: normalizedBaseUrl,
        email: normalizedEmail,
        tokenCiphertext: encryptedToken.ciphertext,
        tokenIv: encryptedToken.iv,
        tokenAuthTag: encryptedToken.authTag,
        updatedAt: new Date(),
      },
    })

  return {
    baseUrl: normalizedBaseUrl,
    email: normalizedEmail,
  }
}

type RepoRouteIntegrationLike = {
  id: string
  instanceUrl: string
  projectPath: string
  projectId: string
}

const slugify = (value: string, fallback: string) => {
  const normalized = value
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")

  return normalized.length > 0 ? normalized : fallback
}

const compactToken = (value: string) =>
  value.toLowerCase().replace(/[^a-z0-9]+/g, "")

const getInstanceHost = (instanceUrl: string) => {
  const trimmed = instanceUrl.trim()
  if (!trimmed) {
    return "instance"
  }

  try {
    return new URL(trimmed).host
  } catch {
    return trimmed
  }
}

export const buildRepoRouteId = ({
  id,
  instanceUrl,
  projectPath,
  projectId,
}: RepoRouteIntegrationLike) => {
  const hostSlug = slugify(getInstanceHost(instanceUrl), "instance")
  const pathSlug = slugify(projectPath, "repo")
  const projectToken = compactToken(projectId) || compactToken(id) || "repo"

  return `${hostSlug}--${pathSlug}--p${projectToken}`
}

export const buildRepoPath = (integration: RepoRouteIntegrationLike) =>
  `/repos/${encodeURIComponent(buildRepoRouteId(integration))}`

export const buildRepoMergeRequestPath = (
  integration: RepoRouteIntegrationLike,
  mergeRequestIid: string,
) => `${buildRepoPath(integration)}/mrs/${encodeURIComponent(mergeRequestIid)}`

export const buildRepoMergeRequestDescriptionPath = (
  integration: RepoRouteIntegrationLike,
  mergeRequestIid: string,
) => `${buildRepoMergeRequestPath(integration, mergeRequestIid)}/description`

export const findIntegrationByRepoRouteId = <T extends RepoRouteIntegrationLike>(
  integrations: readonly T[],
  routeId: string,
) => {
  const normalizedRouteId = routeId.trim()
  if (!normalizedRouteId) {
    return undefined
  }

  return integrations.find((integration) => (
    integration.id === normalizedRouteId ||
    buildRepoRouteId(integration) === normalizedRouteId
  ))
}

