import type { Dispatch, SetStateAction } from "react"
import { useCallback, useEffect, useRef, useState } from "react"

import {
  BACKGROUND_PARSE_FILE_BATCH_SIZE,
  getErrorMessage,
  getNow,
  getParsePatchFilesModule,
  getStableFileKey,
  INITIAL_PARSE_FILE_BATCH_SIZE,
  splitPatchIntoFileChunks,
  type DiffDataSource,
  type DiffLoadProfile,
  type DiffPayload,
  type ParsePatchResult,
  type ParsePatchWorkerResponse,
  type PendingParseRequest,
} from "./merge-request-diff-viewer.utils"

type UseMergeRequestDiffDataOptions = {
  instanceUrl: string
  token: string
  integrationId?: string
  projectId: string
  mergeRequestIid: string
  setCollapsedFileKeys: Dispatch<SetStateAction<Set<string>>>
  onResetReview: () => void
  onDiffLoaded: () => void | Promise<void>
  onResetVisibleFileCount: () => void
}

export function useMergeRequestDiffData({
  instanceUrl,
  token,
  integrationId,
  projectId,
  mergeRequestIid,
  setCollapsedFileKeys,
  onResetReview,
  onDiffLoaded,
  onResetVisibleFileCount,
}: UseMergeRequestDiffDataOptions) {
  const [isLoading, setIsLoading] = useState(false)
  const [loadError, setLoadError] = useState("")
  const [patchText, setPatchText] = useState("")
  const [dataSource, setDataSource] = useState<DiffDataSource | null>(null)
  const [loadProfile, setLoadProfile] = useState<DiffLoadProfile>({
    fetchMs: null,
    firstParseMs: null,
    fullParseMs: null,
  })
  const [parsedFiles, setParsedFiles] = useState<ParsePatchResult["files"]>([])
  const [parseError, setParseError] = useState("")

const [isParsingInitialPatch, setIsParsingInitialPatch] = useState(false)
const [isParsingRemainingPatch, setIsParsingRemainingPatch] = useState(false)

const parseWorkerRef = useRef<Worker | null>(null)
const parseRequestIdRef = useRef(0)
const pendingParseRequestsRef = useRef<Map<number, PendingParseRequest>>(new Map())

useEffect(() => {
  let worker: Worker | null = null
  try {
    worker = new Worker(
      new URL("../../workers/diff-parser.worker.ts", import.meta.url),
    )
  } catch {
    worker = null
  }

  parseWorkerRef.current = worker

  if (!worker) {
    return () => {
      parseWorkerRef.current = null
    }
  }

  const pendingParseRequests = pendingParseRequestsRef.current

  const handleMessage = (event: MessageEvent<ParsePatchWorkerResponse>) => {
    const { id, files, parseError: workerParseError } = event.data
    const pending = pendingParseRequests.get(id)
    if (!pending) {
      return
    }
    pendingParseRequests.delete(id)
    pending.resolve({
      files,
      parseError: workerParseError,
    })
  }

  const handleError = () => {
    const pendingRequests = Array.from(pendingParseRequests.values())
    pendingParseRequests.clear()
    for (const pending of pendingRequests) {
      pending.reject(new Error("Unable to parse merge request diff."))
    }
  }

  worker.addEventListener("message", handleMessage)
  worker.addEventListener("error", handleError)

  return () => {
    parseRequestIdRef.current += 1
    const pendingRequests = Array.from(pendingParseRequests.values())
    pendingParseRequests.clear()
    for (const pending of pendingRequests) {
      pending.reject(new Error("Unable to parse merge request diff."))
    }
    worker.removeEventListener("message", handleMessage)
    worker.removeEventListener("error", handleError)
    worker.terminate()
    if (parseWorkerRef.current === worker) {
      parseWorkerRef.current = null
    }
  }
}, [])

useEffect(() => {
  void getParsePatchFilesModule()
}, [])

const loadDiff = useCallback(async () => {

  const loadStart = getNow()
  setIsLoading(true)
  setLoadError("")

  try {
    const response = await fetch("/api/gitlab", {
      method: "POST",
      headers: {
        "content-type": "application/json",
      },
      body: JSON.stringify({
        action: "merge-request-diff",
        instanceUrl,
        token,
        ...(integrationId ? { integrationId } : {}),
        projectId,
        mergeRequestIid,
      }),
    })

    const payload = (await response.json().catch(() => null)) as DiffPayload | null
    if (!response.ok) {
      throw new Error(getErrorMessage(payload))
    }

    if (!payload?.data || typeof payload.data.patch !== "string") {
      throw new Error("Unexpected diff response from server.")
    }

    const source = payload.data.source === "changes" ? "changes" : "raw_diffs"
    setPatchText(payload.data.patch)
    setDataSource(source)
    setCollapsedFileKeys(new Set())
    setLoadProfile({
      fetchMs: Math.round(getNow() - loadStart),
      firstParseMs: null,
      fullParseMs: null,
    })
    onResetVisibleFileCount()
    onResetReview()
    void onDiffLoaded()
  } catch (error) {
    setPatchText("")
    setDataSource(null)
    setLoadError(getErrorMessage(error))
    setLoadProfile({
      fetchMs: null,
      firstParseMs: null,
      fullParseMs: null,
    })
    onResetReview()
  } finally {
    setIsLoading(false)
  }
}, [

  instanceUrl,
  integrationId,
  mergeRequestIid,
  onResetReview,
  onDiffLoaded,
  onResetVisibleFileCount,
  projectId,
  setCollapsedFileKeys,
  token,
])

useEffect(() => {
  void loadDiff()
}, [loadDiff])

useEffect(() => {
  if (!patchText) {
    parseRequestIdRef.current += 1
    setParsedFiles([])
    setParseError("")
    setIsParsingInitialPatch(false)
    setIsParsingRemainingPatch(false)
    return
  }

  let cancelled = false

  const parsePatchText = async (
    nextPatchText: string,
    cacheKeyPrefix: string,
    preferMainThread = false,
  ): Promise<ParsePatchResult> => {

  if (preferMainThread) {
    const { parsePatchFiles } = await getParsePatchFilesModule()
    try {
      const patches = parsePatchFiles(nextPatchText, cacheKeyPrefix)
      return {
        files: patches.flatMap((patch) => patch.files),
        parseError: "",
      }
    } catch (error) {
      return {
        files: [],
        parseError: getErrorMessage(error),
      }
    }
  }

  const worker = parseWorkerRef.current
  if (worker) {
    const requestId = parseRequestIdRef.current + 1
    parseRequestIdRef.current = requestId

    return await new Promise<ParsePatchResult>((resolve, reject) => {
      pendingParseRequestsRef.current.set(requestId, { resolve, reject })
      try {
        worker.postMessage({
          id: requestId,
          patchText: nextPatchText,
          cacheKeyPrefix,
        })
      } catch (error) {
        pendingParseRequestsRef.current.delete(requestId)
        reject(error)
      }
    })
  }

  const { parsePatchFiles } = await getParsePatchFilesModule()
  try {
    const patches = parsePatchFiles(nextPatchText, cacheKeyPrefix)
    return {
      files: patches.flatMap((patch) => patch.files),
      parseError: "",
    }
  } catch (error) {
    return {
      files: [],
      parseError: getErrorMessage(error),
    }
  }
}

const parseIncrementally = async () => {
  const parseStart = getNow()

const cacheKeyPrefix = `mr-${projectId}-${mergeRequestIid}`
const patchChunks = splitPatchIntoFileChunks(patchText)
setParseError("")
setParsedFiles([])
setIsParsingInitialPatch(true)
setIsParsingRemainingPatch(false)

if (patchChunks.length === 0) {
  const result = await parsePatchText(patchText, cacheKeyPrefix)
  if (cancelled) {
    return
  }
  setParsedFiles(result.files)
  setParseError(result.parseError)
  setLoadProfile((current) => ({
    ...current,
    firstParseMs: Math.round(getNow() - parseStart),
    fullParseMs: Math.round(getNow() - parseStart),
  }))
  setIsParsingInitialPatch(false)
  return
}

const initialPatchChunk = patchChunks
  .slice(0, INITIAL_PARSE_FILE_BATCH_SIZE)
  .join("\n\n")
const initialResult = await parsePatchText(
  initialPatchChunk,
  `${cacheKeyPrefix}-batch-0`,
  true,
)
if (cancelled) {
  return
}

if (initialResult.files.length === 0 && initialResult.parseError) {
  setParsedFiles([])
  setParseError(initialResult.parseError)
  setIsParsingInitialPatch(false)
  return
}

let nextFiles = initialResult.files
let nextParseError = initialResult.parseError
setParsedFiles(nextFiles)
setCollapsedFileKeys(
  new Set(
    nextFiles
      .slice(1)
      .map((file) => getStableFileKey(file)),
  ),
)
setParseError(nextParseError)

setLoadProfile((current) => ({
  ...current,
  firstParseMs: Math.round(getNow() - parseStart),
}))
setIsParsingInitialPatch(false)

const hasRemainingChunks = patchChunks.length > INITIAL_PARSE_FILE_BATCH_SIZE
if (!hasRemainingChunks) {
  setLoadProfile((current) => ({
    ...current,
    fullParseMs: Math.round(getNow() - parseStart),
  }))
  return
}

setIsParsingRemainingPatch(true)

for (
  let start = INITIAL_PARSE_FILE_BATCH_SIZE;
  start < patchChunks.length;
  start += BACKGROUND_PARSE_FILE_BATCH_SIZE
) {
  const nextChunk = patchChunks
    .slice(start, start + BACKGROUND_PARSE_FILE_BATCH_SIZE)
    .join("\n\n")
  const batchResult = await parsePatchText(
    nextChunk,
    `${cacheKeyPrefix}-batch-${start}`,
  )

  if (cancelled) {
    return
  }

  if (batchResult.files.length > 0) {
    nextFiles = [...nextFiles, ...batchResult.files]
    setParsedFiles(nextFiles)
    setCollapsedFileKeys((current) => {
      const next = new Set(current)
      for (const file of batchResult.files) {
        next.add(getStableFileKey(file))
      }
      return next
    })
  }
  if (!nextParseError && batchResult.parseError) {
    nextParseError = batchResult.parseError
    setParseError(nextParseError)
  }
}

      if (!cancelled) {
        setLoadProfile((current) => ({
          ...current,
          fullParseMs: Math.round(getNow() - parseStart),
        }))
        setIsParsingRemainingPatch(false)
      }
    }

    void parseIncrementally().catch((error: unknown) => {
      if (cancelled) {
        return
      }
      setParsedFiles([])
      setParseError(getErrorMessage(error))
      setIsParsingInitialPatch(false)
      setIsParsingRemainingPatch(false)
    })

    return () => {
      cancelled = true
    }
  }, [mergeRequestIid, patchText, projectId, setCollapsedFileKeys])

  return {
    isLoading,
    loadError,
    patchText,
    dataSource,
    loadProfile,
    parsedFiles,
    parseError,
    isParsingInitialPatch,
    isParsingRemainingPatch,
    loadDiff,
  }
}

const formatRelative = (value: Date | null) => {
  if (!value) return "never"
  const diffMs = Date.now() - value.getTime()
  const diffMin = Math.floor(diffMs / 60_000)
  if (diffMin < 1) return "just now"
  if (diffMin < 60) return `${diffMin}m ago`
  const diffHr = Math.floor(diffMin / 60)
  if (diffHr < 24) return `${diffHr}h ago`
  const diffDay = Math.floor(diffHr / 24)
  return `${diffDay}d ago`
}

const extractErrorMessage = (payload: unknown, fallback: string) => {
  if (
    payload &&
    typeof payload === "object" &&
    "error" in payload &&
    typeof (payload as { error?: unknown }).error === "string"
  ) {
    return (payload as { error: string }).error
  }
  return fallback
}

